	{
		return entries;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof Deck))
		{
			return false;
		}
		Deck that = (Deck) other;
		return id.equals(that.id) && name.equals(that.name) && entries.equals(that.entries);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, entries);
	}
}

