package com.osrstcgbattles.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/** Immutable flat battlefields for both players. */
public final class BoardState
{
	private final Map<PlayerId, List<BoardUnit>> units;

	private BoardState(Map<PlayerId, List<BoardUnit>> source)
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = new EnumMap<>(PlayerId.class);
		for (PlayerId player : PlayerId.values())
		{
			copy.put(player, Collections.unmodifiableList(new ArrayList<>(source.get(player))));
		}
		units = Collections.unmodifiableMap(copy);
	}

	static BoardState empty()
	{
		EnumMap<PlayerId, List<BoardUnit>> empty = new EnumMap<>(PlayerId.class);
		for (PlayerId player : PlayerId.values()) empty.put(player, Collections.emptyList());
		return new BoardState(empty);
	}

	public static BoardState visible(Map<PlayerId, List<BoardUnit>> units)
	{
		if (units == null) throw new IllegalArgumentException("units are required");
		for (PlayerId player : PlayerId.values())
		{
			if (units.get(player) == null || units.get(player).contains(null))
				throw new IllegalArgumentException("both player boards are required");
		}
		return new BoardState(units);
	}

	public List<BoardUnit> getUnits(PlayerId player)
	{
		return units.get(player);
	}

	/** @deprecated Rows no longer affect gameplay. */
	@Deprecated
	public List<BoardUnit> getRow(PlayerId player, Row row)
	{
		return row == Row.MELEE ? getUnits(player) : Collections.emptyList();
	}

	/** @deprecated Scores no longer determine a winner. */
	@Deprecated
	public int getTotalScore(PlayerId player)
	{
		return getUnits(player).stream().mapToInt(BoardUnit::getCurrentAttack).sum();
	}

	BoardState add(PlayerId player, BoardUnit unit)
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = mutableCopy();
		copy.get(player).add(unit);
		return new BoardState(copy);
	}

	BoardUnit find(String instanceId)
	{
		for (PlayerId player : PlayerId.values())
		{
			for (BoardUnit unit : getUnits(player))
			{
				if (unit.getInstanceId().equals(instanceId)) return unit;
			}
		}
		return null;
	}

	PlayerId ownerOf(String instanceId)
	{
		for (PlayerId player : PlayerId.values())
		{
			if (getUnits(player).stream().anyMatch(unit -> unit.getInstanceId().equals(instanceId))) return player;
		}
		return null;
	}

	BoardState replace(BoardUnit replacement)
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = mutableCopy();
		for (PlayerId player : PlayerId.values())
		{
			List<BoardUnit> list = copy.get(player);
			for (int i = 0; i < list.size(); i++)
			{
				if (list.get(i).getInstanceId().equals(replacement.getInstanceId()))
				{
					list.set(i, replacement);
					return new BoardState(copy);
				}
			}
		}
		return this;
	}

	BoardState remove(String instanceId)
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = mutableCopy();
		for (PlayerId player : PlayerId.values())
		{
			if (copy.get(player).removeIf(unit -> unit.getInstanceId().equals(instanceId))) return new BoardState(copy);
		}
		return this;
	}

	BoardState readyAll(PlayerId player)
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = mutableCopy();
		List<BoardUnit> list = copy.get(player);
		for (int i = 0; i < list.size(); i++) list.set(i, list.get(i).withReady(true));
		return new BoardState(copy);
	}

	private EnumMap<PlayerId, List<BoardUnit>> mutableCopy()
	{
		EnumMap<PlayerId, List<BoardUnit>> copy = new EnumMap<>(PlayerId.class);
		for (PlayerId player : PlayerId.values()) copy.put(player, new ArrayList<>(getUnits(player)));
		return copy;
	}
}

package com.osrstcgbattles.engine;

import java.util.Objects;

/** One specific unit on the board, separate from its reusable card definition. */
public final class BoardUnit
{
	private final String instanceId;
	private final UnitCard definition;
	private final int currentAttack;
	private final int currentHealth;
	private final boolean ready;
	private final boolean shielded;
	private final boolean stealthed;
	private final boolean rushRestricted;

	BoardUnit(String instanceId, UnitCard definition, int currentAttack, int currentHealth, boolean ready,
		boolean shielded, boolean stealthed, boolean rushRestricted)
	{
		this.instanceId = Objects.requireNonNull(instanceId, "instanceId");
		this.definition = Objects.requireNonNull(definition, "definition");
		this.currentAttack = currentAttack;
		this.currentHealth = currentHealth;
		this.ready = ready;
		this.shielded = shielded;
		this.stealthed = stealthed;
		this.rushRestricted = rushRestricted;
	}

	static BoardUnit deploy(String instanceId, UnitCard definition)
	{
		boolean rush = definition.hasKeyword(UnitKeyword.RUSH);
		return new BoardUnit(instanceId, definition, definition.getBaseAttack(), definition.getBaseHealth(), rush,
			definition.hasKeyword(UnitKeyword.SHIELD), definition.hasKeyword(UnitKeyword.STEALTH), rush);
	}

	public static BoardUnit visible(String instanceId, UnitCard definition, int attack, int health, boolean ready,
		boolean shielded, boolean stealthed, boolean rushRestricted)
	{
		if (instanceId == null || instanceId.isEmpty() || definition == null || attack < 0 || health < 0)
			throw new IllegalArgumentException("invalid visible board unit");
		return new BoardUnit(instanceId, definition, attack, health, ready, shielded, stealthed, rushRestricted);
	}

	public String getInstanceId()
	{
		return instanceId;
	}

	public UnitCard getDefinition()
	{
		return definition;
	}

	public int getCurrentAttack()
	{
		return currentAttack;
	}

	public int getCurrentHealth()
	{
		return currentHealth;
	}

	public boolean isReady()
	{
		return ready;
	}

	public boolean isShielded() { return shielded; }
	public boolean isStealthed() { return stealthed; }
	public boolean isRushRestricted() { return rushRestricted; }
	public boolean hasKeyword(UnitKeyword keyword) { return definition.hasKeyword(keyword); }

	BoardUnit withStats(int attack, int health)
	{
		return new BoardUnit(instanceId, definition, attack, health, ready, shielded, stealthed, rushRestricted);
	}

	BoardUnit withReady(boolean value)
	{
		return new BoardUnit(instanceId, definition, currentAttack, currentHealth, value, shielded, stealthed,
			value ? false : rushRestricted);
	}

	BoardUnit withoutShield()
	{
		return new BoardUnit(instanceId, definition, currentAttack, currentHealth, ready, false, stealthed,
			rushRestricted);
	}

	BoardUnit reveal()
	{
		return new BoardUnit(instanceId, definition, currentAttack, currentHealth, ready, shielded, false,
			rushRestricted);
	}

	/** @deprecated Use {@link #getCurrentAttack()}. */
	@Deprecated
	public int getCurrentPower()
	{
		return currentAttack;
	}

	@Override
	public String toString()
	{
		return definition.getName() + " (" + currentAttack + "/" + currentHealth + ")";
	}
}

