import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/** An immutable card that resolves its effects without entering the board. */
public final class SpecialCard implements Card
{
	private final String id;
	private final String name;
	private final int manaCost;
	private final List<DeployEffect> deployEffects;

	public SpecialCard(String id, String name, int manaCost, List<DeployEffect> deployEffects)
	{
		this.id = requireText(id, "id");
		this.name = requireText(name, "name");
		if (manaCost < 0 || manaCost > 10)
		{
			throw new IllegalArgumentException("manaCost must be between 0 and 10");
		}
		this.manaCost = manaCost;
		Objects.requireNonNull(deployEffects, "deployEffects");
		List<DeployEffect> effects = new ArrayList<>(deployEffects.size());
		for (DeployEffect effect : deployEffects)
		{
			effect = Objects.requireNonNull(effect, "deployEffects contains null");
			if (effect.getTarget() == DeployEffect.Target.SELF)
			{
				throw new IllegalArgumentException("Special cards cannot target self");
			}
			effects.add(effect);
		}
		this.deployEffects = Collections.unmodifiableList(effects);
	}

	private static String requireText(String value, String field)
	{
		Objects.requireNonNull(value, field);
		if (value.trim().isEmpty())
		{
			throw new IllegalArgumentException(field + " must not be blank");
		}
		return value;
	}

	@Override
	public String getId()
	{
		return id;
	}

	@Override
	public String getName()
	{
		return name;
	}

	@Override
	public int getManaCost()
	{
		return manaCost;
	}

	public List<DeployEffect> getDeployEffects()
	{
		return deployEffects;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SpecialCard))
		{
			return false;
		}
		SpecialCard card = (SpecialCard) other;
		return manaCost == card.manaCost && id.equals(card.id) && name.equals(card.name)
			&& deployEffects.equals(card.deployEffects);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, manaCost, deployEffects);
	}

	@Override
	public String toString()
	{
		return name + " (" + manaCost + ", Special)";
	}
}

package com.osrstcgbattles.engine;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;

public final class StateHasher
{
	private StateHasher() { }

	public static String publicStateSha256(MatchState state) { return stateSha256(state, false); }
	public static String synchronizationStateSha256(MatchState state) { return stateSha256(state, true); }

	private static String stateSha256(MatchState state, boolean synchronization)
	{
		try
		{
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			DataOutputStream out = new DataOutputStream(bytes);
			out.writeUTF(synchronization ? "osrs-tcg-hearthstone-lite-sync-v3"
				: "osrs-tcg-hearthstone-lite-public-v3");
			writePublicState(out, state);
			if (synchronization)
			{
				for (PlayerId player : PlayerId.values())
				{
					writeCards(out, state.getPlayer(player).getHand());
					writeCards(out, state.getPlayer(player).getDrawPile());
				}
			}
			out.flush();
			return sha256Hex(bytes.toByteArray());
		}
		catch (IOException exception)
		{
			throw new IllegalStateException("Could not serialize match state", exception);
		}
	}

	private static void writePublicState(DataOutputStream out, MatchState state) throws IOException
	{
		out.writeInt(DuelscapeEngine.RULESET_VERSION);
		out.writeInt(state.getTurnNumber());
		out.writeUTF(state.getStartingPlayer().name());
		out.writeUTF(state.getStatus().name());
		out.writeUTF(state.getPhase().name());
		out.writeUTF(state.getActivePlayer().map(Enum::name).orElse(""));
		out.writeUTF(state.getWinner().map(Enum::name).orElse(""));
		out.writeLong(state.getNextUnitInstanceId());
		for (PlayerId player : PlayerId.values())
		{
			PlayerState value = state.getPlayer(player);
			out.writeUTF(player.name());
			out.writeInt(value.getHeroHealth());
			out.writeInt(value.getMana());
			out.writeInt(value.getTemporaryMana());
			out.writeInt(value.getMaximumMana());
			out.writeInt(value.getFatigue());
			out.writeInt(value.getTurnsStarted());
			out.writeInt(value.getRemainingMulligans());
			out.writeBoolean(value.isMulliganFinished());
			out.writeInt(value.getHand().size());
			out.writeInt(value.getDrawPile().size());
			writeCards(out, value.getGraveyard());
			writeBoardUnits(out, state.getBoard().getUnits(player));
		}
	}

	private static void writeCards(DataOutputStream out, Iterable<? extends Card> cards) throws IOException
	{
		int count = 0;
		for (Card ignored : cards) count++;
		out.writeInt(count);
		for (Card card : cards) writeCard(out, card);
	}

	private static void writeBoardUnits(DataOutputStream out, Iterable<BoardUnit> units) throws IOException
	{
		int count = 0;
		for (BoardUnit ignored : units) count++;
		out.writeInt(count);
		for (BoardUnit unit : units)
		{
			out.writeUTF(unit.getInstanceId());
			out.writeInt(unit.getCurrentAttack());
			out.writeInt(unit.getCurrentHealth());
			out.writeBoolean(unit.isReady());
			out.writeBoolean(unit.isShielded());
			out.writeBoolean(unit.isStealthed());
			out.writeBoolean(unit.isRushRestricted());
			writeCard(out, unit.getDefinition());
		}
	}

	private static void writeCard(DataOutputStream out, Card card) throws IOException
	{
		if (!(card instanceof UnitCard) && !(card instanceof SpecialCard))
		{
			throw new IllegalArgumentException("unsupported card type");
		}
		out.writeUTF(card instanceof UnitCard ? "UNIT" : "SPECIAL");
		out.writeUTF(card.getId());
		out.writeUTF(card.getName());
		out.writeInt(card.getManaCost());
		List<DeployEffect> effects;
		if (card instanceof UnitCard)
		{
			UnitCard unit = (UnitCard) card;
			out.writeInt(unit.getBaseAttack());
			out.writeInt(unit.getBaseHealth());
			effects = unit.getDeployEffects();
			out.writeInt(unit.getKeywords().size());
			for (UnitKeyword keyword : unit.getKeywords()) out.writeUTF(keyword.name());
			out.writeInt(unit.getDeathrattles().size());
			for (DeathrattleEffect effect : unit.getDeathrattles())
			{
				out.writeUTF(effect.getType().name());
				out.writeInt(effect.getAmount());
			}
		}
		else
		{
			effects = ((SpecialCard) card).getDeployEffects();
			out.writeInt(0);
			out.writeInt(0);
		}
		out.writeInt(effects.size());
		for (DeployEffect effect : effects)
		{
			out.writeUTF(effect.getType().name());
			out.writeUTF(effect.getTarget().name());
			out.writeInt(effect.getAmount());
		}
	}

	private static String sha256Hex(byte[] value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(value);
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte item : digest)
			{
				hex.append(Character.forDigit((item >>> 4) & 0xf, 16));
				hex.append(Character.forDigit(item & 0xf, 16));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}
}

package com.osrstcgbattles.engine;

import java.util.Collections;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

public final class UnitCard implements Card
{
	private final String id;
	private final String name;
	private final int manaCost;
	private final int baseAttack;
	private final int baseHealth;
	private final List<DeployEffect> deployEffects;
	private final Set<UnitKeyword> keywords;
	private final List<DeathrattleEffect> deathrattles;

	public UnitCard(String id, String name, int manaCost, int baseAttack, int baseHealth)
	{
		this(id, name, manaCost, baseAttack, baseHealth, Collections.emptyList());
	}

	public UnitCard(String id, String name, int manaCost, int baseAttack, int baseHealth,
		List<DeployEffect> deployEffects)
	{
		this(id, name, manaCost, baseAttack, baseHealth, deployEffects,
			Collections.emptySet(), Collections.emptyList());
	}

	public UnitCard(String id, String name, int manaCost, int baseAttack, int baseHealth,
		List<DeployEffect> deployEffects, Set<UnitKeyword> keywords, List<DeathrattleEffect> deathrattles)
	{
		this.id = requireText(id, "id");
		this.name = requireText(name, "name");
		if (manaCost < 0 || manaCost > 10)
		{
			throw new IllegalArgumentException("manaCost must be between 0 and 10");
		}
		if (baseAttack < 0 || baseHealth <= 0)
		{
			throw new IllegalArgumentException("Unit attack must not be negative and health must be positive");
		}
		this.manaCost = manaCost;
		this.baseAttack = baseAttack;
		this.baseHealth = baseHealth;
		Objects.requireNonNull(deployEffects, "deployEffects");
		List<DeployEffect> effects = new ArrayList<>(deployEffects.size());
		for (DeployEffect effect : deployEffects)
		{
			effects.add(Objects.requireNonNull(effect, "deployEffects contains null"));
		}
		this.deployEffects = Collections.unmodifiableList(effects);
		Objects.requireNonNull(keywords, "keywords");
		EnumSet<UnitKeyword> keywordCopy = EnumSet.noneOf(UnitKeyword.class);
		for (UnitKeyword keyword : keywords)
		{
			keywordCopy.add(Objects.requireNonNull(keyword, "keywords contains null"));
		}
		this.keywords = Collections.unmodifiableSet(keywordCopy);
		Objects.requireNonNull(deathrattles, "deathrattles");
		List<DeathrattleEffect> deathrattleCopy = new ArrayList<>(deathrattles.size());
		for (DeathrattleEffect effect : deathrattles)
		{
			deathrattleCopy.add(Objects.requireNonNull(effect, "deathrattles contains null"));
		}
		this.deathrattles = Collections.unmodifiableList(deathrattleCopy);
	}

	private static String requireText(String value, String field)
	{
		Objects.requireNonNull(value, field);
		if (value.trim().isEmpty())
		{
			throw new IllegalArgumentException(field + " must not be blank");
		}
		return value;
	}

	@Override
	public String getId()
	{
		return id;
	}

	@Override
	public String getName()
	{
		return name;
	}

	@Override
	public int getManaCost()
	{
		return manaCost;
	}

	public int getBaseAttack()
	{
		return baseAttack;
	}

	public int getBaseHealth()
	{
		return baseHealth;
	}

	public List<DeployEffect> getDeployEffects()
	{
		return deployEffects;
	}

	public Set<UnitKeyword> getKeywords() { return keywords; }
	public boolean hasKeyword(UnitKeyword keyword) { return keywords.contains(keyword); }
	public List<DeathrattleEffect> getDeathrattles() { return deathrattles; }

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof UnitCard))
		{
			return false;
		}
		UnitCard card = (UnitCard) other;
		return manaCost == card.manaCost && baseAttack == card.baseAttack && baseHealth == card.baseHealth
			&& id.equals(card.id) && name.equals(card.name) && deployEffects.equals(card.deployEffects)
			&& keywords.equals(card.keywords) && deathrattles.equals(card.deathrattles);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, manaCost, baseAttack, baseHealth, deployEffects, keywords, deathrattles);
	}

	@Override
	public String toString()
	{
		return name + " (" + manaCost + ", " + baseAttack + "/" + baseHealth + ")";
	}
}

