package com.osrstcgbattles.integration;

import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.catalog.CardCategory;
import com.osrstcgbattles.catalog.CardAbility;
import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.Rarity;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.engine.Card;
import com.osrstcgbattles.engine.DeathrattleEffect;
import com.osrstcgbattles.engine.DeployEffect;
import com.osrstcgbattles.engine.SpecialCard;
import com.osrstcgbattles.engine.UnitCard;
import com.osrstcgbattles.engine.UnitKeyword;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Random;

public final class CatalogDeckFactory
{
	private static final int DEFAULT_DEMO_SIZE = 30;

	private final BattleCardCatalog catalog;
	private final Random random;

	public CatalogDeckFactory(BattleCardCatalog catalog)
	{
		this(catalog, new Random());
	}

	CatalogDeckFactory(BattleCardCatalog catalog, Random random)
	{
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		this.random = Objects.requireNonNull(random, "random");
	}

	public List<Card> create(Deck deck)
	{
		Objects.requireNonNull(deck, "deck");
		List<Card> cards = new ArrayList<>();
		for (DeckEntry entry : deck.getEntries())
		{
			if (entry.getCount() <= 0)
			{
				throw new IllegalArgumentException("Deck entry count must be positive for card: " + entry.getCardId());
			}
			BattleCard definition = catalog.findById(entry.getCardId())
				.orElseThrow(() -> new IllegalArgumentException("Unknown catalog card ID: " + entry.getCardId()));
			for (int i = 0; i < entry.getCount(); i++)
			{
				cards.add(toCard(definition));
			}
		}
		return Collections.unmodifiableList(cards);
	}

	public Card createCard(String cardId)
	{
		BattleCard definition = catalog.findById(Objects.requireNonNull(cardId, "cardId"))
			.orElseThrow(() -> new IllegalArgumentException("Unknown catalog card ID: " + cardId));
		return toCard(definition);
	}

	public UnitCard createBoardUnitCard(String cardId)
	{
		BattleCard definition = catalog.findBoardCardById(Objects.requireNonNull(cardId, "cardId"))
			.orElseThrow(() -> new IllegalArgumentException("Unknown board card ID: " + cardId));
		if (definition.getCategory() != CardCategory.UNIT)
			throw new IllegalArgumentException("Board card is not a unit: " + cardId);
		return toUnitCard(definition);
	}

	public List<UnitCard> demoDeck()
	{
		return demoDeck(DEFAULT_DEMO_SIZE);
	}

	public List<UnitCard> demoDeck(int minimumSize)
	{
		if (minimumSize <= 0)
		{
			throw new IllegalArgumentException("minimumSize must be positive");
		}
		List<BattleCard> units = new ArrayList<>();
		for (BattleCard card : catalog.getCards())
		{
			if (card.getCategory() == CardCategory.UNIT)
			{
				units.add(card);
			}
		}
		if (units.isEmpty())
		{
			throw new IllegalStateException("Catalog contains no unit cards for a demo deck");
		}

		List<UnitCard> deck = new ArrayList<>(minimumSize);
		for (int i = 0; i < minimumSize; i++)
		{
			deck.add(toUnitCard(units.get(i % units.size())));
		}
		return Collections.unmodifiableList(deck);
	}

	/** Builds a random, validator-passing deck of exactly {@code size} cards from the catalog units. */
	public Deck randomDeck()
	{
		return randomDeck(DEFAULT_DEMO_SIZE);
	}

	public Deck randomDeck(int size)
	{
		if (size <= 0)
		{
			throw new IllegalArgumentException("size must be positive");
		}
		List<BattleCard> units = new ArrayList<>();
		for (BattleCard card : catalog.getCards())
		{
			if (card.getCategory() == CardCategory.UNIT)
			{
				units.add(card);
			}
		}
		if (units.isEmpty())
		{
			throw new IllegalStateException("Catalog contains no unit cards for a random deck");
		}

		List<BattleCard> available = new ArrayList<>();
		for (BattleCard card : units)
		{
			int limit = card.getRarity() == Rarity.LEGENDARY ? 1 : 2;
			for (int i = 0; i < limit; i++)
			{
				available.add(card);
			}
		}
		if (available.size() < size)
		{
			throw new IllegalStateException("Catalog cannot fill a " + size + "-card random deck");
		}
		Collections.shuffle(available, random);

		Map<String, Integer> counts = new LinkedHashMap<>();
		for (BattleCard card : available.subList(0, size))
		{
			counts.put(card.getId(), counts.getOrDefault(card.getId(), 0) + 1);
		}

		List<DeckEntry> entries = new ArrayList<>(counts.size());
		for (Map.Entry<String, Integer> entry : counts.entrySet())
		{
			entries.add(new DeckEntry(entry.getKey(), entry.getValue()));
		}
		return new Deck("random-" + Integer.toHexString(catalog.getSha256().hashCode() & 0xffffff), "Random Deck", entries);
	}

	private static UnitCard toUnitCard(BattleCard card)
	{
		return new UnitCard(card.getId(), card.getDisplayName(), card.getManaCost(), card.getAttack(),
			card.getHealth(), mapEffects(card), mapKeywords(card), mapDeathrattles(card));
	}

	private static Card toCard(BattleCard card)
	{
		return card.getCategory() == CardCategory.UNIT ? toUnitCard(card)
			: new SpecialCard(card.getId(), card.getDisplayName(), card.getManaCost(), mapEffects(card));
	}

	private static List<DeployEffect> mapEffects(BattleCard card)
	{
		List<DeployEffect> effects = new ArrayList<>();
		for (CardAbility ability : card.getAbilities())
		{
			if (ability.getType() == AbilityType.VANILLA || isKeyword(ability.getType())
				|| isDeathrattle(ability.getType()))
			{
				continue;
			}
			DeployEffect.Type type = ability.getType() == AbilityType.DEPLOY_BOOST
				? DeployEffect.Type.BOOST : ability.getType() == AbilityType.DEPLOY_DAMAGE
					? DeployEffect.Type.DAMAGE : DeployEffect.Type.MANA;
			DeployEffect.Target target = ability.getType() == AbilityType.GAIN_MANA
				? DeployEffect.Target.HERO : DeployEffect.Target.valueOf(ability.getStringParams().get("target"));
			effects.add(new DeployEffect(type, target, ability.getNumericParams().get("amount")));
		}
		return effects;
	}

	private static EnumSet<UnitKeyword> mapKeywords(BattleCard card)
	{
		EnumSet<UnitKeyword> keywords = EnumSet.noneOf(UnitKeyword.class);
		for (CardAbility ability : card.getAbilities())
		{
			switch (ability.getType())
			{
				case SHIELD: keywords.add(UnitKeyword.SHIELD); break;
				case LIFESTEAL: keywords.add(UnitKeyword.LIFESTEAL); break;
				case POISONOUS: keywords.add(UnitKeyword.POISONOUS); break;
				case RUSH: keywords.add(UnitKeyword.RUSH); break;
				case TAUNT: keywords.add(UnitKeyword.TAUNT); break;
				case STEALTH: keywords.add(UnitKeyword.STEALTH); break;
				case NEX_ASCENSION: keywords.add(UnitKeyword.NEX_ASCENSION); break;
				default: break;
			}
		}
		return keywords;
	}

	private static List<DeathrattleEffect> mapDeathrattles(BattleCard card)
	{
		List<DeathrattleEffect> effects = new ArrayList<>();
		for (CardAbility ability : card.getAbilities())
		{
			DeathrattleEffect.Type type;
			switch (ability.getType())
			{
				case DEATHRATTLE_DAMAGE_HERO: type = DeathrattleEffect.Type.DAMAGE_ENEMY_HERO; break;
				case DEATHRATTLE_DRAW: type = DeathrattleEffect.Type.DRAW_CARD; break;
				case DEATHRATTLE_SUMMON: type = DeathrattleEffect.Type.SUMMON_SPIRIT; break;
				default: continue;
			}
			effects.add(new DeathrattleEffect(type, ability.getNumericParams().get("amount")));
		}
		return effects;
	}

	private static boolean isKeyword(AbilityType type)
	{
		return type == AbilityType.SHIELD || type == AbilityType.LIFESTEAL || type == AbilityType.POISONOUS
			|| type == AbilityType.RUSH || type == AbilityType.TAUNT || type == AbilityType.STEALTH
			|| type == AbilityType.NEX_ASCENSION;
	}

	private static boolean isDeathrattle(AbilityType type)
	{
		return type == AbilityType.DEATHRATTLE_DAMAGE_HERO || type == AbilityType.DEATHRATTLE_DRAW
			|| type == AbilityType.DEATHRATTLE_SUMMON;
	}
}

package com.osrstcgbattles.integration;

import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.catalog.CardAbility;
import com.osrstcgbattles.catalog.Rarity;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.engine.DuelscapeEngine;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Predicate;

/** Deterministic built-in decks. Exact definitions are playable without collection ownership. */
public final class StarterDeckFactory
{
	// IDs are immutable template versions. A changed starter definition must receive a new ID.
	public static final String DEATHRATTLE_ID = "starter-deathrattle-value";
	public static final String RUSH_ID = "starter-rush-swarm";
	public static final String BULWARK_ID = "starter-gielinor-bulwark";

	private final List<BattleCard> cards;
	private final List<Deck> starters;
	private final Map<String, Deck> startersById;

	public StarterDeckFactory(BattleCardCatalog catalog)
	{
		Objects.requireNonNull(catalog, "catalog");
		cards = new ArrayList<>(catalog.getCards());
		cards.sort(Comparator.comparingInt(BattleCard::getManaCost)
			.thenComparing(BattleCard::getId));
		List<Deck> built = new ArrayList<>();
		built.add(deathrattleValue());
		built.add(rushSwarm());
		built.add(gielinorBulwark());
		starters = Collections.unmodifiableList(built);
		Map<String, Deck> byId = new LinkedHashMap<>();
		for (Deck starter : starters) byId.put(starter.getId(), starter);
		startersById = Collections.unmodifiableMap(byId);
	}

	public List<Deck> createStarterDecks()
	{
		return starters;
	}

	public boolean isUnmodifiedStarter(Deck deck)
	{
		return deck != null && deck.equals(startersById.get(deck.getId()));
	}

	public boolean isStarterId(String deckId)
	{
		return deckId != null && startersById.containsKey(deckId);
	}

	public Deck getStarter(String deckId)
	{
		return startersById.get(deckId);
	}

	private Deck deathrattleValue()
	{
		Builder deck = new Builder(DEATHRATTLE_ID, "Starter: Deathrattle Value");
		deck.add(has(AbilityType.GAIN_MANA), 5);
		deck.add(has(AbilityType.DEATHRATTLE_DRAW), 4);
		deck.add(has(AbilityType.DEATHRATTLE_SUMMON), 4);
		deck.add(has(AbilityType.DEATHRATTLE_DAMAGE_HERO), 4);
		deck.add(and(has(AbilityType.SHIELD), costAtMost(3)), 4);
		deck.add(and(has(AbilityType.LIFESTEAL), costAtMost(4)), 4);
		deck.add(and(has(AbilityType.TAUNT), costAtMost(5)), 3);
		deck.add(and(has(AbilityType.VANILLA), costAtMost(3)), 2);
		return deck.finish();
	}

	private Deck rushSwarm()
	{
		Builder deck = new Builder(RUSH_ID, "Starter: Rush Swarm");
		deck.add(has(AbilityType.GAIN_MANA), 5);
		deck.add(has(AbilityType.RUSH), 10);
		deck.add(and(has(AbilityType.POISONOUS), costAtMost(4)), 4);
		deck.add(and(has(AbilityType.STEALTH), costAtMost(4)), 3);
		deck.add(and(has(AbilityType.DEPLOY_DAMAGE), costAtMost(4)), 4);
		deck.add(and(has(AbilityType.VANILLA), costAtMost(3)), 4);
		return deck.finish();
	}

	private Deck gielinorBulwark()
	{
		Builder deck = new Builder(BULWARK_ID, "Starter: Gielinor Bulwark");
		deck.add(has(AbilityType.SHIELD), 8);
		deck.add(has(AbilityType.LIFESTEAL), 6);
		deck.add(has(AbilityType.TAUNT), 8);
		deck.add(has(AbilityType.DEPLOY_BOOST), 4);
		deck.add(has(AbilityType.DEATHRATTLE_DRAW), 2);
		deck.add(has(AbilityType.GAIN_MANA), 2);
		return deck.finish();
	}

	private static Predicate<BattleCard> has(AbilityType type)
	{
		return card -> {
			for (CardAbility ability : card.getAbilities()) if (ability.getType() == type) return true;
			return false;
		};
	}

	private static Predicate<BattleCard> costAtMost(int mana)
	{
		return card -> card.getManaCost() <= mana;
	}

	private static Predicate<BattleCard> and(Predicate<BattleCard> first, Predicate<BattleCard> second)
	{
		return first.and(second);
	}

	private final class Builder
	{
		private final String id;
		private final String name;
		private final Map<String, Integer> quantities = new LinkedHashMap<>();
		private int size;

		private Builder(String id, String name)
		{
			this.id = id;
			this.name = name;
		}

		private void add(Predicate<BattleCard> predicate, int requested)
		{
			int target = Math.min(DuelscapeEngine.DECK_SIZE, size + requested);
			for (BattleCard card : cards)
			{
				if (size >= target) break;
				if (!predicate.test(card) || card.getId().equals("asgarnia-nex")) continue;
				int limit = card.getRarity() == Rarity.LEGENDARY ? 1 : 2;
				int current = quantities.getOrDefault(card.getId(), 0);
				int add = Math.min(limit - current, target - size);
				if (add > 0)
				{
					quantities.put(card.getId(), current + add);
					size += add;
				}
			}
		}

		private Deck finish()
		{
			add(card -> !card.getId().equals("asgarnia-nex"), DuelscapeEngine.DECK_SIZE - size);
			if (size != DuelscapeEngine.DECK_SIZE)
				throw new IllegalStateException("Unable to build starter deck " + name);
			List<DeckEntry> entries = new ArrayList<>();
			for (Map.Entry<String, Integer> entry : quantities.entrySet())
				entries.add(new DeckEntry(entry.getKey(), entry.getValue()));
			return new Deck(id, name, entries);
		}
	}
}

package com.osrstcgbattles.match;

import com.osrstcgbattles.engine.BoardState;
import com.osrstcgbattles.engine.Card;
import com.osrstcgbattles.engine.MatchPhase;
import com.osrstcgbattles.engine.MatchState;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.engine.PlayerState;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Immutable player-scoped projection of a match that excludes hidden opponent cards. */
public final class MatchView
{
	private final PlayerId viewer;
	private final int turnNumber;
	private final PlayerId startingPlayer;
	private final PlayerId activePlayer;
	private final MatchStatus status;
	private final MatchPhase phase;
	private final PlayerId winner;
	private final Map<PlayerId, PlayerView> players;
	private final BoardState board;
	private final List<Card> localHand;
	private final String publicStateHash;

	private MatchView(PlayerId viewer, MatchState state)
	{
		this.viewer = Objects.requireNonNull(viewer, "viewer");
		Objects.requireNonNull(state, "state");
		turnNumber = state.getTurnNumber();
		startingPlayer = state.getStartingPlayer();
		activePlayer = state.getActivePlayer().orElse(null);
		status = state.getStatus();
		phase = state.getPhase();
		winner = state.getWinner().orElse(null);
		EnumMap<PlayerId, PlayerView> projectedPlayers = new EnumMap<>(PlayerId.class);
		for (PlayerId player : PlayerId.values())
		{
			projectedPlayers.put(player, new PlayerView(state.getPlayer(player)));
		}
		players = Collections.unmodifiableMap(projectedPlayers);
		board = state.getBoard();
		localHand = Collections.unmodifiableList(new ArrayList<>(state.getPlayer(viewer).getHand()));
		publicStateHash = state.getPublicStateHash();
	}

	private MatchView(PlayerId viewer, int turnNumber, PlayerId startingPlayer, PlayerId activePlayer,
		MatchStatus status, MatchPhase phase, PlayerId winner, Map<PlayerId, PlayerView> players,
		BoardState board, List<Card> localHand, String publicStateHash)
	{
		this.viewer = Objects.requireNonNull(viewer, "viewer");
		if (turnNumber < 1) throw new IllegalArgumentException("turnNumber must be positive");
		this.turnNumber = turnNumber;
		this.startingPlayer = Objects.requireNonNull(startingPlayer, "startingPlayer");
		this.activePlayer = activePlayer;
		this.status = Objects.requireNonNull(status, "status");
		this.phase = Objects.requireNonNull(phase, "phase");
		this.winner = winner;
		EnumMap<PlayerId, PlayerView> projectedPlayers = new EnumMap<>(PlayerId.class);
		for (PlayerId player : PlayerId.values())
		{
			PlayerView projected = Objects.requireNonNull(players.get(player), "missing player view");
			projectedPlayers.put(player, projected);
		}
		this.players = Collections.unmodifiableMap(projectedPlayers);
		this.board = Objects.requireNonNull(board, "board");
		this.localHand = Collections.unmodifiableList(new ArrayList<>(Objects.requireNonNull(localHand, "localHand")));
		if (this.localHand.contains(null)) throw new IllegalArgumentException("localHand contains null");
		this.publicStateHash = Objects.requireNonNull(publicStateHash, "publicStateHash");
	}

	public static MatchView forPlayer(MatchState state, PlayerId viewer)
	{
		return new MatchView(viewer, state);
	}

	public static MatchView visible(PlayerId viewer, int turnNumber, PlayerId startingPlayer, PlayerId activePlayer,
		MatchStatus status, MatchPhase phase, PlayerId winner, Map<PlayerId, PlayerView> players,
		BoardState board, List<Card> localHand, String publicStateHash)
	{
		return new MatchView(viewer, turnNumber, startingPlayer, activePlayer, status, phase, winner,
			Objects.requireNonNull(players, "players"), board, localHand, publicStateHash);
	}

	public PlayerId getViewer() { return viewer; }
	public int getTurnNumber() { return turnNumber; }
	public PlayerId getStartingPlayer() { return startingPlayer; }
	public Optional<PlayerId> getActivePlayer() { return Optional.ofNullable(activePlayer); }
	public MatchStatus getStatus() { return status; }
	public MatchPhase getPhase() { return phase; }
	public Optional<PlayerId> getWinner() { return Optional.ofNullable(winner); }
	public PlayerView getPlayer(PlayerId player) { return players.get(Objects.requireNonNull(player, "player")); }
	public BoardState getBoard() { return board; }
	public List<Card> getLocalHand() { return localHand; }
	public String getPublicStateHash() { return publicStateHash; }

	/** Public player data. Hands and draw piles are represented only by counts. */
	public static final class PlayerView
	{
		private final int heroHealth;
		private final int mana;
		private final int temporaryMana;
		private final int maximumMana;
		private final int fatigue;
		private final int turnsStarted;
		private final int handSize;
		private final int drawPileSize;
		private final List<Card> graveyard;
		private final int remainingMulligans;
		private final boolean mulliganFinished;

		private PlayerView(PlayerState state)
		{
			heroHealth = state.getHeroHealth();
			mana = state.getMana();
			temporaryMana = state.getTemporaryMana();
			maximumMana = state.getMaximumMana();
			fatigue = state.getFatigue();
			turnsStarted = state.getTurnsStarted();
			handSize = state.getHand().size();
			drawPileSize = state.getDrawPile().size();
			graveyard = Collections.unmodifiableList(new ArrayList<>(state.getGraveyard()));
			remainingMulligans = state.getRemainingMulligans();
			mulliganFinished = state.isMulliganFinished();
		}

		private PlayerView(int heroHealth, int mana, int temporaryMana, int maximumMana, int fatigue,
			int turnsStarted, int handSize, int drawPileSize, List<Card> graveyard, int remainingMulligans,
			boolean mulliganFinished)
		{
			if (heroHealth < 0 || mana < 0 || temporaryMana < 0 || maximumMana < 0 || fatigue < 0
				|| turnsStarted < 0 || handSize < 0 || drawPileSize < 0 || remainingMulligans < 0)
				throw new IllegalArgumentException("visible player values must not be negative");
			this.heroHealth = heroHealth;
			this.mana = mana;
			this.temporaryMana = temporaryMana;
			this.maximumMana = maximumMana;
			this.fatigue = fatigue;
			this.turnsStarted = turnsStarted;
			this.handSize = handSize;
			this.drawPileSize = drawPileSize;
			this.graveyard = Collections.unmodifiableList(new ArrayList<>(Objects.requireNonNull(graveyard, "graveyard")));
			if (this.graveyard.contains(null)) throw new IllegalArgumentException("graveyard contains null");
			this.remainingMulligans = remainingMulligans;
			this.mulliganFinished = mulliganFinished;
		}

		public static PlayerView visible(int heroHealth, int mana, int temporaryMana, int maximumMana,
			int fatigue, int turnsStarted, int handSize, int drawPileSize, List<Card> graveyard,
			int remainingMulligans, boolean mulliganFinished)
		{
			return new PlayerView(heroHealth, mana, temporaryMana, maximumMana, fatigue, turnsStarted,
				handSize, drawPileSize, graveyard, remainingMulligans, mulliganFinished);
		}

		public int getHeroHealth() { return heroHealth; }
		public int getMana() { return mana; }
		public int getTemporaryMana() { return temporaryMana; }
		public int getMaximumMana() { return maximumMana; }
		public int getFatigue() { return fatigue; }
		public int getTurnsStarted() { return turnsStarted; }
		public int getHandSize() { return handSize; }
		public int getDrawPileSize() { return drawPileSize; }
		public List<Card> getGraveyard() { return graveyard; }
		public int getRemainingMulligans() { return remainingMulligans; }
		public boolean isMulliganFinished() { return mulliganFinished; }
	}
}

package com.osrstcgbattles.match;

import com.osrstcgbattles.party.BattlePartyMessageType;
import java.util.Map;

/** Sends an application payload through the party transport's encrypted channel. */
public interface PartyMatchChannel
{
	boolean send(BattlePartyMessageType type, Map<String, ?> payload);
}

package com.osrstcgbattles.match;

import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.collection.OwnedCardCollectionStatus;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.deck.DeckValidator;
import com.osrstcgbattles.engine.AttackCommand;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.CommandResult;
import com.osrstcgbattles.engine.ConcedeCommand;
import com.osrstcgbattles.engine.EndTurnCommand;
import com.osrstcgbattles.engine.DuelscapeEngine;
import com.osrstcgbattles.engine.FinishMulliganCommand;
import com.osrstcgbattles.engine.MatchState;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.MulliganCommand;
import com.osrstcgbattles.engine.PlayCardCommand;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.integration.CatalogCardLookup;
import com.osrstcgbattles.integration.CatalogDeckFactory;
import com.osrstcgbattles.party.BattlePartyEnvelope;
import com.osrstcgbattles.party.BattlePartyMessageType;
import com.osrstcgbattles.party.DeckCommitment;
import com.osrstcgbattles.party.PartyApplicationMessage;
import com.osrstcgbattles.party.PartyDuelSnapshot;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Pure, owner-thread coordinator for deterministic party matches. */
public final class PartyMatchCoordinator
{
	private static final byte[] SEED_DOMAIN = "OSRS-TCG-PARTY-MATCH-SEED-V1".getBytes(StandardCharsets.US_ASCII);
	private static final byte[] SEED_COMMITMENT_DOMAIN =
		"OSRS-TCG-PARTY-MATCH-SEED-COMMITMENT-V1".getBytes(StandardCharsets.US_ASCII);
	private static final long MAX_WIRE_INTEGER = 9_007_199_254_740_991L;
	private static final int MAX_ID_LENGTH = BattlePartyEnvelope.MAX_ID_LENGTH;
	// RuneLite game ticks are roughly 600 ms; allow transient reconnects without waiting forever.
	static final int RETRY_LIMIT = 10;

	private final long localMemberId;
	private final long peerMemberId;
	private final PartyDuelSnapshot duel;
	private final BattleCardCatalog catalog;
	private final DeckValidator validator;
	private final CatalogCardLookup cardLookup;
	private final CatalogDeckFactory deckFactory;
	private final Deck localDeck;
	private final PartyMatchChannel channel;
	private final long localContribution;
	private final PlayerId localSeat;
	private final PlayerId peerSeat;
	private final DuelscapeEngine engine = new DuelscapeEngine();
	private final List<PartyMatchListener> listeners = new ArrayList<>();

	private PartyMatchSnapshot.Status status = PartyMatchSnapshot.Status.WAITING_SETUP;
	private MatchState state;
	private long revision;
	private String peerSeedCommitment;
	private Setup peerSetup;
	private boolean started;
	private Long pendingRevision;
	private String pendingHash;
	private Map<String, Object> pendingActionPayload;
	private final Map<Long, Map<String, Object>> appliedPeerActions = new LinkedHashMap<>();
	private final Map<Long, String> acknowledgedLocalActions = new LinkedHashMap<>();
	private Map<String, Object> lastAckPayload;
	private int setupRetries;
	private int actionRetries;
	private int ackRetries;
	private String userStatus = "Waiting to exchange seed commitments";

	public PartyMatchCoordinator(long localMemberId, PartyDuelSnapshot duel, BattleCardCatalog catalog,
		DeckValidator validator, CatalogCardLookup cardLookup, CatalogDeckFactory deckFactory, Deck localDeck,
		PartyMatchChannel channel, long localSeedContribution)
	{
		if (localMemberId <= 0) throw new IllegalArgumentException("localMemberId must be positive");
		this.duel = Objects.requireNonNull(duel, "duel");
		if (duel.getStatus() != PartyDuelSnapshot.Status.READY) throw new IllegalArgumentException("duel must be READY");
		if (duel.getPeerMemberId() <= 0 || duel.getPeerMemberId() == localMemberId)
			throw new IllegalArgumentException("invalid peer member ID");
		this.localMemberId = localMemberId;
		this.peerMemberId = duel.getPeerMemberId();
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		this.validator = Objects.requireNonNull(validator, "validator");
		this.cardLookup = Objects.requireNonNull(cardLookup, "cardLookup");
		this.deckFactory = Objects.requireNonNull(deckFactory, "deckFactory");
		this.localDeck = canonicalDeck(Objects.requireNonNull(localDeck, "localDeck"));
		this.channel = Objects.requireNonNull(channel, "channel");
		this.localContribution = localSeedContribution;
		this.localSeat = localMemberId < peerMemberId ? PlayerId.PLAYER_ONE : PlayerId.PLAYER_TWO;
		this.peerSeat = localSeat.opponent();
		validateLocalConfiguration();
	}

	public void start()
	{
		if (started || status == PartyMatchSnapshot.Status.DESYNC
			|| status == PartyMatchSnapshot.Status.ABORTED || status == PartyMatchSnapshot.Status.COMPLETE) return;
		started = true;
		sendSilently(BattlePartyMessageType.SNAPSHOT, seedCommitPayload());
		userStatus = "Waiting for opponent seed commitment";
		publish();
	}

	public CommandResult submit(Command command)
	{
		Objects.requireNonNull(command, "command");
		if (status != PartyMatchSnapshot.Status.ACTIVE) throw new IllegalStateException("match is not active");
		if (command.getPlayer() != localSeat) throw new IllegalArgumentException("command actor is not the local seat");
		if (pendingRevision != null) throw new IllegalStateException("local action is awaiting acknowledgement");

		long priorRevision = revision;
		String priorHash = state.getSynchronizationStateHash();
		CommandResult result = engine.execute(state, command);
		if (!result.isAccepted()) return result;

		MatchState nextState = result.getState();
		Map<String, Object> payload = actionPayload(command, priorRevision, priorHash,
			nextState.getSynchronizationStateHash());
		if (!channel.send(BattlePartyMessageType.ACTION, payload))
			throw new IllegalStateException("application transport is unavailable");
		state = nextState;
		revision = priorRevision + 1;
		pendingRevision = revision;
		pendingHash = nextState.getSynchronizationStateHash();
		pendingActionPayload = payload;
		actionRetries = 0;
		lastAckPayload = null;
		updateStatusFromEngine();
		publish();
		return result;
	}

	/** Advances deterministic retry timers by one caller-defined tick. */
	public void onTick()
	{
		if (status == PartyMatchSnapshot.Status.DESYNC || status == PartyMatchSnapshot.Status.ABORTED) return;

		if (pendingActionPayload != null)
		{
			if (actionRetries >= RETRY_LIMIT)
			{
				pendingRevision = null;
				pendingHash = null;
				pendingActionPayload = null;
				timeout();
				return;
			}
			sendSilently(BattlePartyMessageType.ACTION, pendingActionPayload);
			actionRetries++;
		}
		else if (started && peerSetup == null)
		{
			if (setupRetries >= RETRY_LIMIT)
			{
				timeout();
				return;
			}
			sendSilently(BattlePartyMessageType.SNAPSHOT, seedCommitPayload());
			if (peerSeedCommitment != null)
				sendSilently(BattlePartyMessageType.SNAPSHOT, setupPayload(localDeck, localContribution));
			setupRetries++;
		}
		else if (started && setupRetries < RETRY_LIMIT)
		{
			sendSilently(BattlePartyMessageType.SNAPSHOT, seedCommitPayload());
			sendSilently(BattlePartyMessageType.SNAPSHOT, setupPayload(localDeck, localContribution));
			setupRetries++;
		}

		if (lastAckPayload != null && ackRetries < RETRY_LIMIT)
		{
			sendSilently(BattlePartyMessageType.ACTION_ACK, lastAckPayload);
			ackRetries++;
		}
	}

	public void receive(PartyApplicationMessage message)
	{
		if (message == null || status == PartyMatchSnapshot.Status.DESYNC
			|| status == PartyMatchSnapshot.Status.ABORTED) return;
		if (!duel.getMatchId().equals(message.getMatchId()) || message.getPeerMemberId() != peerMemberId)
		{
			fail(message.getType() == BattlePartyMessageType.SNAPSHOT && state == null,
				"Match synchronization failed");
			return;
		}
		try
		{
			switch (message.getType())
			{
				case SNAPSHOT:
					receiveSnapshot(message.getPayload());
					break;
				case ACTION:
					receiveAction(message.getPayload());
					break;
				case ACTION_ACK:
					receiveAck(message.getPayload());
					break;
				default:
					fail(false, "Match synchronization failed");
			}
		}
		catch (RuntimeException exception)
		{
			fail(state == null, state == null ? "Opponent setup was rejected"
				: "Match synchronization failed");
		}
	}

	public void accept(PartyApplicationMessage message)
	{
		receive(message);
	}

	public void onApplicationMessage(PartyApplicationMessage message)
	{
		receive(message);
	}

	public void abort()
	{
		if (status == PartyMatchSnapshot.Status.COMPLETE || status == PartyMatchSnapshot.Status.ABORTED) return;
		status = PartyMatchSnapshot.Status.ABORTED;
		userStatus = "Match aborted";
		publish();
	}

	public PartyMatchSnapshot snapshot()
	{
		return new PartyMatchSnapshot(status, localSeat, peerSeat, revision, state, userStatus);
	}

	public void addListener(PartyMatchListener listener)
	{
		listeners.add(Objects.requireNonNull(listener, "listener"));
	}

	public void removeListener(PartyMatchListener listener)
	{
		listeners.remove(listener);
	}

	private void validateLocalConfiguration()
	{
		if (catalog.getRulesetVersion() != DuelscapeEngine.RULESET_VERSION
			|| duel.getRulesetVersion() != DuelscapeEngine.RULESET_VERSION
			|| !Objects.equals(duel.getCatalogHash(), catalog.getSha256()))
			throw new IllegalArgumentException("duel catalog metadata does not match catalog");
		if (!localDeck.getId().equals(duel.getDeckId())) throw new IllegalArgumentException("selected deck ID does not match READY");
		if (!DeckCommitment.compute(catalog.getSha256(), catalog.getRulesetVersion(), localDeck)
			.equals(duel.getDeckCommitment())) throw new IllegalArgumentException("selected deck does not match READY commitment");
		if (!validator.validate(localDeck, cardLookup, Collections.emptySet(), OwnedCardCollectionStatus.UNKNOWN).isValid())
			throw new IllegalArgumentException("selected deck is invalid");
	}

	private void receiveSnapshot(Map<String, Object> payload)
	{
		String kind = string(payload == null ? null : payload.get("kind"), 1, 16, "kind");
		if ("SEED_COMMIT".equals(kind))
		{
			receiveSeedCommit(payload);
			return;
		}
		if ("SETUP".equals(kind))
		{
			receiveSetup(payload);
			return;
		}
		throw new IllegalArgumentException("invalid snapshot kind");
	}

	private void receiveSeedCommit(Map<String, Object> payload)
	{
		if (!started) throw new IllegalArgumentException("match is not started");
		requireKeys(payload, "commitment", "kind");
		String commitment = hash(payload.get("commitment"), "commitment");
		if (peerSeedCommitment != null)
		{
			if (!peerSeedCommitment.equals(commitment))
				throw new IllegalArgumentException("conflicting seed commitment");
			sendSilently(BattlePartyMessageType.SNAPSHOT, setupPayload(localDeck, localContribution));
			return;
		}
		peerSeedCommitment = commitment;
		setupRetries = 0;
		sendSilently(BattlePartyMessageType.SNAPSHOT, setupPayload(localDeck, localContribution));
		userStatus = "Waiting for opponent setup reveal";
		publish();
	}

	private void receiveSetup(Map<String, Object> payload)
	{
		if (peerSeedCommitment == null) return;
		Setup setup = parseSetup(payload);
		if (!peerSeedCommitment.equals(seedCommitment(peerMemberId, setup.contribution)))
			throw new IllegalArgumentException("seed reveal does not match commitment");
		if (peerSetup != null)
		{
			if (!peerSetup.equals(setup)) fail(false, "Match synchronization failed");
			return;
		}
		if (!setup.deck.getId().equals(duel.getPeerDeckId()))
			throw new IllegalArgumentException("peer deck ID mismatch");
		String commitment = DeckCommitment.compute(catalog.getSha256(), catalog.getRulesetVersion(), setup.deck);
		if (!commitment.equals(duel.getPeerDeckCommitment()))
			throw new IllegalArgumentException("peer deck commitment mismatch");
		if (!validator.validate(setup.deck, cardLookup, Collections.emptySet(), OwnedCardCollectionStatus.UNKNOWN).isValid())
			throw new IllegalArgumentException("peer deck is invalid");

		List<? extends com.osrstcgbattles.engine.Card> localCards = deckFactory.create(localDeck);
		List<? extends com.osrstcgbattles.engine.Card> peerCards = deckFactory.create(setup.deck);
		long seed = deriveSeed(duel.getMatchId(), localMemberId, localContribution, peerMemberId, setup.contribution);
		state = localSeat == PlayerId.PLAYER_ONE ? engine.newMatchWithMulligan(localCards, peerCards, seed)
			: engine.newMatchWithMulligan(peerCards, localCards, seed);
		peerSetup = setup;
		setupRetries = 0;
		status = PartyMatchSnapshot.Status.ACTIVE;
		userStatus = "Match active";
		publish();
	}

	private void receiveAction(Map<String, Object> payload)
	{
		requirePresent(payload, "actor", "command", "priorHash", "priorRevision", "resultingHash");
		long wireRevision = integer(payload.get("priorRevision"), 0, MAX_WIRE_INTEGER, "priorRevision");
		String priorHash = hash(payload.get("priorHash"), "priorHash");
		String resultingHash = hash(payload.get("resultingHash"), "resultingHash");
		String actor = string(payload.get("actor"), 1, 32, "actor");
		Map<String, Object> applied = appliedPeerActions.get(wireRevision);
		if (applied != null && applied.equals(payload))
		{
			sendAck(wireRevision + 1, resultingHash);
			return;
		}
		if (status != PartyMatchSnapshot.Status.ACTIVE) throw new IllegalArgumentException("match is not active");
		if (!peerSeat.name().equals(actor) || wireRevision != revision
			|| !state.getSynchronizationStateHash().equals(priorHash))
		{
			fail(false, "Match synchronization failed");
			return;
		}

		Command command = parseCommand(payload, peerSeat);
		CommandResult result = engine.execute(state, command);
		if (!result.isAccepted() || !result.getState().getSynchronizationStateHash().equals(resultingHash))
		{
			fail(false, "Match synchronization failed");
			return;
		}
		MatchState nextState = result.getState();
		long nextRevision = revision + 1;
		state = nextState;
		revision = nextRevision;
		appliedPeerActions.put(wireRevision, immutableCopy(payload));
		sendAck(nextRevision, nextState.getSynchronizationStateHash());
		updateStatusFromEngine();
		publish();
	}

	private void receiveAck(Map<String, Object> payload)
	{
		if (state == null || (status != PartyMatchSnapshot.Status.ACTIVE
			&& status != PartyMatchSnapshot.Status.COMPLETE)) throw new IllegalArgumentException("match is not initialized");
		requireKeys(payload, "hash", "revision");
		long acknowledged = integer(payload.get("revision"), 0, MAX_WIRE_INTEGER, "revision");
		String acknowledgedHash = hash(payload.get("hash"), "hash");
		if (pendingRevision == null)
		{
			if (acknowledgedHash.equals(acknowledgedLocalActions.get(acknowledged))) return;
			fail(false, "Match synchronization failed");
			return;
		}
		if (acknowledged != pendingRevision || !pendingHash.equals(acknowledgedHash))
		{
			fail(false, "Match synchronization failed");
			return;
		}
		acknowledgedLocalActions.put(acknowledged, acknowledgedHash);
		pendingRevision = null;
		pendingHash = null;
		pendingActionPayload = null;
	}

	private Command parseCommand(Map<String, Object> payload, PlayerId actor)
	{
		String type = string(payload.get("command"), 1, 16, "command");
		switch (type)
		{
			case "END_TURN":
				requireKeys(payload, "actor", "command", "priorHash", "priorRevision", "resultingHash");
				return new EndTurnCommand(actor);
			case "CONCEDE":
				requireKeys(payload, "actor", "command", "priorHash", "priorRevision", "resultingHash");
				return new ConcedeCommand(actor);
			case "KEEP":
			case "FINISH_MULLIGAN":
				requireKeys(payload, "actor", "command", "priorHash", "priorRevision", "resultingHash");
				return new FinishMulliganCommand(actor);
			case "MULLIGAN":
				requireKeys(payload, "actor", "cardId", "command", "priorHash", "priorRevision", "resultingHash");
				return new MulliganCommand(actor, string(payload.get("cardId"), 1, MAX_ID_LENGTH, "cardId"));
			case "PLAY":
				Set<String> allowed = new HashSet<>();
				Collections.addAll(allowed, "actor", "command", "priorHash", "priorRevision", "resultingHash",
					"cardId", "target");
				if (!allowed.containsAll(payload.keySet()) || !payload.keySet().containsAll(
					java.util.Arrays.asList("actor", "command", "priorHash", "priorRevision", "resultingHash", "cardId")))
					throw new IllegalArgumentException("invalid PLAY fields");
				String cardId = string(payload.get("cardId"), 1, MAX_ID_LENGTH, "cardId");
				String target = payload.containsKey("target")
					? string(payload.get("target"), 1, MAX_ID_LENGTH, "target") : null;
				return new PlayCardCommand(actor, cardId, target);
			case "ATTACK":
				Set<String> attackAllowed = new HashSet<>();
				Collections.addAll(attackAllowed, "actor", "command", "priorHash", "priorRevision", "resultingHash",
					"attacker", "target");
				if (!attackAllowed.containsAll(payload.keySet()) || !payload.keySet().containsAll(
					java.util.Arrays.asList("actor", "command", "priorHash", "priorRevision", "resultingHash", "attacker")))
					throw new IllegalArgumentException("invalid ATTACK fields");
				String attacker = string(payload.get("attacker"), 1, MAX_ID_LENGTH, "attacker");
				String attackTarget = payload.containsKey("target")
					? string(payload.get("target"), 1, MAX_ID_LENGTH, "target") : null;
				return new AttackCommand(actor, attacker, attackTarget);
			default:
				throw new IllegalArgumentException("unknown command");
		}
	}

	private Map<String, Object> actionPayload(Command command, long priorRevision, String priorHash, String resultHash)
	{
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("actor", command.getPlayer().name());
		payload.put("priorRevision", priorRevision);
		payload.put("priorHash", priorHash);
		payload.put("resultingHash", resultHash);
		if (command instanceof PlayCardCommand)
		{
			PlayCardCommand play = (PlayCardCommand) command;
			payload.put("command", "PLAY");
			payload.put("cardId", play.getCardId());
			play.getTargetInstanceId().ifPresent(target -> payload.put("target", target));
		}
		else if (command instanceof AttackCommand)
		{
			AttackCommand attack = (AttackCommand) command;
			payload.put("command", "ATTACK");
			payload.put("attacker", attack.getAttackerInstanceId());
			attack.getTargetInstanceId().ifPresent(target -> payload.put("target", target));
		}
		else if (command instanceof EndTurnCommand) payload.put("command", "END_TURN");
		else if (command instanceof ConcedeCommand) payload.put("command", "CONCEDE");
		else if (command instanceof MulliganCommand)
		{
			payload.put("command", "MULLIGAN");
			payload.put("cardId", ((MulliganCommand) command).getCardId());
		}
		else if (command instanceof FinishMulliganCommand) payload.put("command", "FINISH_MULLIGAN");
		else throw new IllegalArgumentException("unsupported command");
		return Collections.unmodifiableMap(payload);
	}

	private Map<String, Object> ackPayload(long acknowledgedRevision, String acknowledgedHash)
	{
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("revision", acknowledgedRevision);
		payload.put("hash", acknowledgedHash);
		return Collections.unmodifiableMap(payload);
	}

	private void sendAck(long acknowledgedRevision, String acknowledgedHash)
	{
		lastAckPayload = ackPayload(acknowledgedRevision, acknowledgedHash);
		ackRetries = 0;
		sendSilently(BattlePartyMessageType.ACTION_ACK, lastAckPayload);
	}

	private Map<String, Object> setupPayload(Deck deck, long contribution)
	{
		List<Map<String, Object>> cards = new ArrayList<>();
		for (DeckEntry entry : deck.getEntries())
		{
			Map<String, Object> card = new LinkedHashMap<>();
			card.put("cardId", entry.getCardId());
			card.put("count", entry.getCount());
			cards.add(Collections.unmodifiableMap(card));
		}
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("kind", "SETUP");
		payload.put("deckId", deck.getId());
		payload.put("cards", Collections.unmodifiableList(cards));
		payload.put("seedContribution", String.format("%016x", contribution));
		return Collections.unmodifiableMap(payload);
	}

	private Map<String, Object> seedCommitPayload()
	{
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("kind", "SEED_COMMIT");
		payload.put("commitment", seedCommitment(localMemberId, localContribution));
		return Collections.unmodifiableMap(payload);
	}

	private Setup parseSetup(Map<String, Object> payload)
	{
		requireKeys(payload, "cards", "deckId", "kind", "seedContribution");
		if (!"SETUP".equals(string(payload.get("kind"), 1, 16, "kind")))
			throw new IllegalArgumentException("invalid snapshot kind");
		String deckId = string(payload.get("deckId"), 1, MAX_ID_LENGTH, "deckId");
		String seed = string(payload.get("seedContribution"), 16, 16, "seedContribution");
		if (!seed.matches("[0-9a-f]{16}")) throw new IllegalArgumentException("invalid seed contribution");
		Object cardsValue = payload.get("cards");
		if (!(cardsValue instanceof List)) throw new IllegalArgumentException("cards must be a list");
		List<?> cards = (List<?>) cardsValue;
		if (cards.isEmpty() || cards.size() > DeckValidator.MAX_CARDS)
			throw new IllegalArgumentException("invalid card entry count");
		List<DeckEntry> entries = new ArrayList<>();
		String previous = null;
		for (Object value : cards)
		{
			if (!(value instanceof Map)) throw new IllegalArgumentException("card entry must be an object");
			@SuppressWarnings("unchecked") Map<String, Object> card = (Map<String, Object>) value;
			requireKeys(card, "cardId", "count");
			String cardId = string(card.get("cardId"), 1, MAX_ID_LENGTH, "cardId");
			if (previous != null && previous.compareTo(cardId) >= 0)
				throw new IllegalArgumentException("card entries are not canonical");
			int count = (int) integer(card.get("count"), 1, DeckValidator.MAX_CARDS, "count");
			entries.add(new DeckEntry(cardId, count));
			previous = cardId;
		}
		return new Setup(new Deck(deckId, "Peer deck", entries), Long.parseUnsignedLong(seed, 16));
	}

	private void updateStatusFromEngine()
	{
		if (state.getStatus() == MatchStatus.COMPLETE)
		{
			status = PartyMatchSnapshot.Status.COMPLETE;
			userStatus = "Match complete";
		}
		else
		{
			status = PartyMatchSnapshot.Status.ACTIVE;
			userStatus = "Match active";
		}
	}

	private void fail(boolean setupFailure, String safeStatus)
	{
		if (status == PartyMatchSnapshot.Status.COMPLETE || status == PartyMatchSnapshot.Status.DESYNC
			|| status == PartyMatchSnapshot.Status.ABORTED) return;
		status = setupFailure ? PartyMatchSnapshot.Status.ABORTED : PartyMatchSnapshot.Status.DESYNC;
		userStatus = safeStatus;
		publish();
	}

	private void timeout()
	{
		if (status == PartyMatchSnapshot.Status.COMPLETE) return;
		status = PartyMatchSnapshot.Status.ABORTED;
		userStatus = "Match synchronization timed out";
		publish();
	}

	private boolean sendSilently(BattlePartyMessageType type, Map<String, ?> payload)
	{
		try
		{
			return channel.send(type, payload);
		}
		catch (RuntimeException exception)
		{
			return false;
		}
	}

	private static Map<String, Object> immutableCopy(Map<String, Object> payload)
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(payload));
	}

	private void publish()
	{
		PartyMatchSnapshot current = snapshot();
		for (PartyMatchListener listener : new ArrayList<>(listeners)) listener.onPartyMatchSnapshotChanged(current);
	}

	private static Deck canonicalDeck(Deck deck)
	{
		List<DeckEntry> entries = new ArrayList<>(deck.getEntries());
		entries.sort(Comparator.comparing(DeckEntry::getCardId));
		return new Deck(deck.getId(), deck.getName(), entries);
	}

	private static long deriveSeed(String matchId, long firstMember, long firstContribution,
		long secondMember, long secondContribution)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			updateBytes(digest, SEED_DOMAIN);
			updateBytes(digest, matchId.getBytes(StandardCharsets.UTF_8));
			if (firstMember < secondMember)
			{
				updatePair(digest, firstMember, firstContribution);
				updatePair(digest, secondMember, secondContribution);
			}
			else
			{
				updatePair(digest, secondMember, secondContribution);
				updatePair(digest, firstMember, firstContribution);
			}
			return ByteBuffer.wrap(digest.digest()).getLong();
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}

	private String seedCommitment(long memberId, long contribution)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			updateBytes(digest, SEED_COMMITMENT_DOMAIN);
			updateBytes(digest, duel.getMatchId().getBytes(StandardCharsets.UTF_8));
			digest.update(ByteBuffer.allocate(Long.BYTES * 2).putLong(memberId).putLong(contribution).array());
			return hex(digest.digest());
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}

	private static String hex(byte[] bytes)
	{
		StringBuilder result = new StringBuilder(bytes.length * 2);
		for (byte value : bytes)
		{
			result.append(Character.forDigit((value >>> 4) & 0xf, 16));
			result.append(Character.forDigit(value & 0xf, 16));
		}
		return result.toString();
	}

	private static void updateBytes(MessageDigest digest, byte[] value)
	{
		digest.update(ByteBuffer.allocate(Integer.BYTES).putInt(value.length).array());
		digest.update(value);
	}

	private static void updatePair(MessageDigest digest, long member, long contribution)
	{
		digest.update(ByteBuffer.allocate(Long.BYTES * 2).putLong(member).putLong(contribution).array());
	}

	private static void requireKeys(Map<String, ?> map, String... keys)
	{
		if (map == null || map.size() != keys.length) throw new IllegalArgumentException("invalid payload fields");
		for (String key : keys) if (!map.containsKey(key)) throw new IllegalArgumentException("missing payload field");
	}

	private static void requirePresent(Map<String, ?> map, String... keys)
	{
		if (map == null) throw new IllegalArgumentException("payload is required");
		for (String key : keys) if (!map.containsKey(key)) throw new IllegalArgumentException("missing payload field");
	}

	private static String string(Object value, int min, int max, String name)
	{
		if (!(value instanceof String)) throw new IllegalArgumentException(name + " must be a string");
		String text = (String) value;
		if (text.length() < min || text.length() > max) throw new IllegalArgumentException(name + " is out of bounds");
		return text;
	}

	private static String hash(Object value, String name)
	{
		String text = string(value, 64, 64, name);
		if (!text.matches("[0-9a-f]{64}")) throw new IllegalArgumentException(name + " is invalid");
		return text;
	}

	private static long integer(Object value, long min, long max, String name)
	{
		if (!(value instanceof Number)) throw new IllegalArgumentException(name + " must be an integer");
		double number = ((Number) value).doubleValue();
		if (!Double.isFinite(number) || number != Math.rint(number) || number < min || number > max)
			throw new IllegalArgumentException(name + " is out of bounds");
		return (long) number;
	}

	private static final class Setup
	{
		private final Deck deck;
		private final long contribution;

		private Setup(Deck deck, long contribution)
		{
			this.deck = deck;
			this.contribution = contribution;
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof Setup)) return false;
			Setup that = (Setup) other;
			return contribution == that.contribution && deck.getId().equals(that.deck.getId())
				&& deck.getEntries().equals(that.deck.getEntries());
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(deck.getId(), deck.getEntries(), contribution);
		}
	}
}

package com.osrstcgbattles.match;

public interface PartyMatchListener
{
	void onPartyMatchSnapshotChanged(PartyMatchSnapshot snapshot);
}

package com.osrstcgbattles.match;

import com.osrstcgbattles.engine.MatchState;
import com.osrstcgbattles.engine.PlayerId;
import java.util.Objects;
import java.util.Optional;

/** Immutable view of a synchronized party match. */
public final class PartyMatchSnapshot
{
	public enum Status
	{
		WAITING_SETUP, ACTIVE, COMPLETE, DESYNC, ABORTED
	}

	private final Status status;
	private final PlayerId localSeat;
	private final PlayerId peerSeat;
	private final long revision;
	private final MatchState matchState;
	private final String userStatus;

	PartyMatchSnapshot(Status status, PlayerId localSeat, PlayerId peerSeat, long revision,
		MatchState matchState, String userStatus)
	{
		this.status = Objects.requireNonNull(status, "status");
		this.localSeat = Objects.requireNonNull(localSeat, "localSeat");
		this.peerSeat = Objects.requireNonNull(peerSeat, "peerSeat");
		this.revision = revision;
		this.matchState = matchState;
		this.userStatus = Objects.requireNonNull(userStatus, "userStatus");
	}

	public Status getStatus() { return status; }
	public PlayerId getLocalSeat() { return localSeat; }
	public PlayerId getPeerSeat() { return peerSeat; }
	public long getRevision() { return revision; }
	public MatchState getMatchState() { return matchState; }
	public Optional<MatchState> getInitializedMatchState() { return Optional.ofNullable(matchState); }
	public String getUserStatus() { return userStatus; }

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof PartyMatchSnapshot)) return false;
		PartyMatchSnapshot that = (PartyMatchSnapshot) other;
		return status == that.status && localSeat == that.localSeat && peerSeat == that.peerSeat
			&& revision == that.revision && Objects.equals(matchState, that.matchState)
			&& userStatus.equals(that.userStatus);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(status, localSeat, peerSeat, revision, matchState, userStatus);
	}
}

package com.osrstcgbattles.online;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.osrstcgbattles.auth.DeviceKeyStore;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.engine.AttackCommand;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.ConcedeCommand;
import com.osrstcgbattles.engine.EndTurnCommand;
import com.osrstcgbattles.engine.FinishMulliganCommand;
import com.osrstcgbattles.engine.MulliganCommand;
import com.osrstcgbattles.engine.PlayCardCommand;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.util.Base64;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/** Thread-safe RuneLite adapter for the versioned Duelscape WebSocket protocol. */
@Singleton
public final class OnlineBattleClient
{
	private static final int MAX_MESSAGE_BYTES = 64 * 1024;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();
	private final ScheduledExecutorService reconnectExecutor = Executors.newSingleThreadScheduledExecutor(runnable ->
	{
		Thread thread = new Thread(runnable, "duelscape-reconnect");
		thread.setDaemon(true);
		return thread;
	});
	private WebSocket socket;
	private long generation;
	private String displayName;
	private BattleCardCatalog catalog;
	private DeviceKeyStore deviceKey;
	private String reconnectToken;
	private String reconnectServerUrl;
	private boolean rankedAuthenticated;
	private Deck pendingRankedDeck;
	private WaitingState waitingState = WaitingState.NONE;
	private Status status = Status.DISCONNECTED;

	@Inject
	public OnlineBattleClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = Objects.requireNonNull(httpClient, "httpClient");
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public synchronized void start(String serverUrl, String displayName, BattleCardCatalog catalog,
		DeviceKeyStore deviceKey)
	{
		if (serverUrl == null || !serverUrl.startsWith("wss://"))
			throw new IllegalArgumentException("online server must use wss://");
		stopSocket();
		if (!serverUrl.equals(reconnectServerUrl)) reconnectToken = null;
		reconnectServerUrl = serverUrl;
		this.displayName = required(displayName, 32, "displayName");
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		this.deviceKey = Objects.requireNonNull(deviceKey, "deviceKey");
		rankedAuthenticated = false;
		pendingRankedDeck = null;
		waitingState = WaitingState.NONE;
		long activeGeneration = ++generation;
		status = Status.CONNECTING;
		publishStatus(generation, null);
		Request request = new Request.Builder().url(serverUrl).build();
		socket = httpClient.newWebSocket(request, new SocketListener(activeGeneration, 0));
	}

	public synchronized void stop()
	{
		generation++;
		stopSocket();
		reconnectToken = null;
		reconnectServerUrl = null;
		rankedAuthenticated = false;
		pendingRankedDeck = null;
		waitingState = WaitingState.NONE;
		status = Status.DISCONNECTED;
		publishStatus(generation, null);
	}

	public synchronized boolean createLobby(Deck deck)
	{
		JsonObject payload = new JsonObject();
		payload.add("deck", deckPayload(deck));
		return send(OnlineMessageType.LOBBY_CREATE, payload);
	}

	public synchronized boolean joinLobby(String code, Deck deck)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("code", required(code, 6, "code"));
		payload.add("deck", deckPayload(deck));
		return send(OnlineMessageType.LOBBY_JOIN, payload);
	}

	public synchronized boolean leaveLobby()
	{
		return send(OnlineMessageType.LOBBY_LEAVE, new JsonObject());
	}

	public synchronized boolean joinCasualQueue(Deck deck)
	{
		JsonObject payload = new JsonObject();
		payload.add("deck", deckPayload(deck));
		return send(OnlineMessageType.QUEUE_JOIN, payload);
	}

	public synchronized boolean leaveQueue()
	{
		if (pendingRankedDeck != null)
		{
			pendingRankedDeck = null;
			if (status == Status.AUTHENTICATING) status = Status.READY;
			publishStatus(generation, null);
			return true;
		}
		if (waitingState == WaitingState.LOBBY) return leaveLobby();
		if (waitingState == WaitingState.RANKED_QUEUE) return leaveRankedQueue();
		return send(OnlineMessageType.QUEUE_LEAVE, new JsonObject());
	}

	public synchronized boolean joinRankedQueue(Deck deck)
	{
		if (status != Status.READY || socket == null) return false;
		if (!rankedAuthenticated)
		{
			if (pendingRankedDeck != null) return false;
			pendingRankedDeck = Objects.requireNonNull(deck, "deck");
			status = Status.AUTHENTICATING;
			if (!sendAuthenticationBegin(socket))
			{
				pendingRankedDeck = null;
				status = Status.READY;
			}
			publishStatus(generation, null);
			return pendingRankedDeck != null;
		}
		JsonObject payload = new JsonObject();
		payload.add("deck", deckPayload(deck));
		return send(OnlineMessageType.RANKED_QUEUE_JOIN, payload);
	}

	public synchronized boolean leaveRankedQueue()
	{
		if (pendingRankedDeck != null)
		{
			pendingRankedDeck = null;
			if (status == Status.AUTHENTICATING) status = Status.READY;
			publishStatus(generation, null);
			return true;
		}
		return send(OnlineMessageType.RANKED_QUEUE_LEAVE, new JsonObject());
	}

	public synchronized boolean acknowledgeMatch(String matchId, boolean terminal)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("matchId", required(matchId, 64, "matchId"));
		payload.addProperty("terminal", terminal);
		return send(OnlineMessageType.MATCH_ACK, payload);
	}

	public synchronized boolean abandonMatch(String matchId)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("matchId", required(matchId, 64, "matchId"));
		return send(OnlineMessageType.MATCH_ABANDON, payload);
	}

	public synchronized boolean sendCommand(String matchId, long revision, Command command)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("matchId", required(matchId, 64, "matchId"));
		payload.addProperty("commandId", UUID.randomUUID().toString());
		payload.addProperty("expectedRevision", revision);
		payload.add("command", commandPayload(command));
		return send(OnlineMessageType.MATCH_COMMAND, payload);
	}

	public Status getStatus()
	{
		synchronized (this) { return status; }
	}

	public synchronized long getGeneration() { return generation; }
	public synchronized boolean canStartWaiting()
	{
		return status == Status.READY && waitingState == WaitingState.NONE && pendingRankedDeck == null;
	}
	public synchronized boolean canCancelWaiting()
	{
		return pendingRankedDeck != null || waitingState != WaitingState.NONE;
	}

	public void addListener(Listener listener)
	{
		listeners.addIfAbsent(Objects.requireNonNull(listener, "listener"));
	}

	public void removeListener(Listener listener)
	{
		listeners.remove(listener);
	}

	private synchronized boolean send(OnlineMessageType type, JsonObject payload)
	{
		return status == Status.READY && socket != null
			&& socket.send(gson.toJson(new OnlineEnvelope(UUID.randomUUID().toString(), type, payload)));
	}

	private boolean sendAuthenticationBegin(WebSocket webSocket)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("ign", displayName);
		payload.addProperty("publicKey", deviceKey.getPublicKeyBase64Url());
		return webSocket.send(gson.toJson(new OnlineEnvelope(UUID.randomUUID().toString(),
			OnlineMessageType.AUTH_BEGIN, payload)));
	}

	private synchronized void stopSocket()
	{
		WebSocket active = socket;
		socket = null;
		if (active != null) active.close(1000, "plugin stopped");
	}

	private JsonObject deckPayload(Deck deck)
	{
		Objects.requireNonNull(deck, "deck");
		JsonObject payload = new JsonObject();
		payload.addProperty("deckId", required(deck.getId(), 64, "deck ID"));
		JsonArray cards = new JsonArray();
		for (DeckEntry entry : deck.getEntries())
		{
			JsonObject card = new JsonObject();
			card.addProperty("cardId", entry.getCardId());
			card.addProperty("count", entry.getCount());
			cards.add(card);
		}
		payload.add("cards", cards);
		return payload;
	}

	private static JsonObject commandPayload(Command command)
	{
		Objects.requireNonNull(command, "command");
		JsonObject payload = new JsonObject();
		if (command instanceof PlayCardCommand)
		{
			PlayCardCommand play = (PlayCardCommand) command;
			payload.addProperty("type", "PLAY");
			payload.addProperty("cardId", play.getCardId());
			play.getTargetInstanceId().ifPresent(target -> payload.addProperty("target", target));
		}
		else if (command instanceof AttackCommand)
		{
			AttackCommand attack = (AttackCommand) command;
			payload.addProperty("type", "ATTACK");
			payload.addProperty("attacker", attack.getAttackerInstanceId());
			attack.getTargetInstanceId().ifPresent(target -> payload.addProperty("target", target));
		}
		else if (command instanceof EndTurnCommand) payload.addProperty("type", "END_TURN");
		else if (command instanceof ConcedeCommand) payload.addProperty("type", "CONCEDE");
		else if (command instanceof MulliganCommand)
		{
			payload.addProperty("type", "MULLIGAN");
			payload.addProperty("cardId", ((MulliganCommand) command).getCardId());
		}
		else if (command instanceof FinishMulliganCommand) payload.addProperty("type", "FINISH_MULLIGAN");
		else throw new IllegalArgumentException("unsupported command");
		return payload;
	}

	private void publishStatus(long eventGeneration, String message)
	{
		Status current;
		synchronized (this) { current = status; }
		reconnectExecutor.execute(() ->
		{
			for (Listener listener : listeners)
			{
				try { listener.onStatusChanged(eventGeneration, current, message); }
				catch (RuntimeException ignored) { }
			}
		});
	}

	private void publishMessage(long eventGeneration, OnlineEnvelope envelope)
	{
		reconnectExecutor.execute(() ->
		{
			for (Listener listener : listeners)
			{
				try { listener.onMessage(eventGeneration, envelope); }
				catch (RuntimeException ignored) { }
			}
		});
	}

	private static String required(String value, int maximum, String name)
	{
		if (value == null || value.trim().isEmpty() || value.trim().length() > maximum)
			throw new IllegalArgumentException(name + " is invalid");
		return value.trim();
	}

	private final class SocketListener extends WebSocketListener
	{
		private final long listenerGeneration;
		private final int reconnectAttempt;

		private SocketListener(long listenerGeneration, int reconnectAttempt)
		{
			this.listenerGeneration = listenerGeneration;
			this.reconnectAttempt = reconnectAttempt;
		}

		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			synchronized (OnlineBattleClient.this)
			{
				if (listenerGeneration != generation || socket != webSocket) return;
				if (reconnectToken != null)
				{
					JsonObject payload = new JsonObject();
					payload.addProperty("reconnectToken", reconnectToken);
					webSocket.send(gson.toJson(new OnlineEnvelope(UUID.randomUUID().toString(),
						OnlineMessageType.RESUME, payload)));
					return;
				}
				sendHello(webSocket);
			}
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			if (text == null || text.getBytes(StandardCharsets.UTF_8).length > MAX_MESSAGE_BYTES) return;
			synchronized (OnlineBattleClient.this)
			{
				if (listenerGeneration != generation || socket != webSocket) return;
			}
			OnlineEnvelope envelope;
			try
			{
				envelope = gson.fromJson(text, OnlineEnvelope.class);
				if (envelope == null) return;
				envelope.validate();
			}
			catch (JsonParseException | IllegalArgumentException exception)
			{
				return;
			}
			String welcomeToken = null;
			boolean resumedAuthenticated = false;
			boolean compatibleWelcome = true;
			if (envelope.getType() == OnlineMessageType.WELCOME)
			{
				try
				{
					welcomeToken = required(envelope.getPayload().get("reconnectToken").getAsString(), 64,
						"reconnect token");
					resumedAuthenticated = envelope.getPayload().has("authenticated")
						&& envelope.getPayload().get("authenticated").getAsBoolean();
					compatibleWelcome = catalog.getSha256().equals(
						required(envelope.getPayload().get("catalogHash").getAsString(), 64, "catalog hash"))
						&& envelope.getPayload().get("rulesetVersion").getAsInt() == catalog.getRulesetVersion();
				}
				catch (RuntimeException exception) { return; }
			}
			if (envelope.getType() == OnlineMessageType.AUTH_CHALLENGE)
			{
				synchronized (OnlineBattleClient.this)
				{
					if (listenerGeneration != generation || socket != webSocket) return;
					try { sendAuthenticationResponse(webSocket, envelope.getPayload()); }
					catch (GeneralSecurityException | RuntimeException exception)
					{
						pendingRankedDeck = null;
						status = Status.READY;
						publishStatus(listenerGeneration, "Could not sign ranked authentication challenge");
					}
				}
				return;
			}
			synchronized (OnlineBattleClient.this)
			{
				if (listenerGeneration != generation || socket != webSocket) return;
				if (envelope.getType() == OnlineMessageType.WELCOME)
				{
					if (!compatibleWelcome)
					{
						reconnectToken = null;
						status = Status.ERROR;
						webSocket.close(1002, "incompatible server");
						return;
					}
					reconnectToken = welcomeToken;
					rankedAuthenticated = resumedAuthenticated;
					status = Status.READY;
					if (pendingRankedDeck != null)
					{
						if (rankedAuthenticated)
						{
							Deck pending = pendingRankedDeck;
							pendingRankedDeck = null;
							JsonObject payload = new JsonObject();
							payload.add("deck", deckPayload(pending));
							send(OnlineMessageType.RANKED_QUEUE_JOIN, payload);
						}
						else
						{
							status = Status.AUTHENTICATING;
							if (!sendAuthenticationBegin(webSocket))
							{
								pendingRankedDeck = null;
								status = Status.READY;
							}
						}
					}
				}
				else if (envelope.getType() == OnlineMessageType.AUTHENTICATED)
				{
					rankedAuthenticated = true;
					status = Status.READY;
					Deck pending = pendingRankedDeck;
					pendingRankedDeck = null;
					if (pending != null)
					{
						JsonObject payload = new JsonObject();
						payload.add("deck", deckPayload(pending));
						send(OnlineMessageType.RANKED_QUEUE_JOIN, payload);
					}
				}
				else if (envelope.getType() == OnlineMessageType.ERROR && status == Status.CONNECTING
					&& reconnectToken != null)
				{
					reconnectToken = null;
					waitingState = WaitingState.NONE;
					pendingRankedDeck = null;
					sendHello(webSocket);
					return;
				}
				else if (envelope.getType() == OnlineMessageType.ERROR && status == Status.AUTHENTICATING)
				{
					pendingRankedDeck = null;
					status = Status.READY;
				}
				updateWaitingState(envelope);
			}
			synchronized (OnlineBattleClient.this)
			{
				if (listenerGeneration != generation || socket != webSocket) return;
				if (envelope.getType() == OnlineMessageType.WELCOME
					|| envelope.getType() == OnlineMessageType.AUTHENTICATED) publishStatus(listenerGeneration, null);
				publishMessage(listenerGeneration, envelope);
			}
		}

		private void sendAuthenticationResponse(WebSocket webSocket, JsonObject challenge)
			throws GeneralSecurityException
		{
			String challengeId = required(challenge.get("challengeId").getAsString(), 64, "challenge ID");
			byte[] nonce = Base64.getUrlDecoder().decode(required(challenge.get("nonce").getAsString(), 128, "nonce"));
			byte[] publicKey = Base64.getUrlDecoder().decode(deviceKey.getPublicKeyBase64Url());
			byte[] signature = deviceKey.sign(RankedAuthentication.challenge(reconnectServerUrl, challengeId, nonce,
				displayName, publicKey));
			JsonObject payload = new JsonObject();
			payload.addProperty("challengeId", challengeId);
			payload.addProperty("signature", Base64.getUrlEncoder().withoutPadding().encodeToString(signature));
			webSocket.send(gson.toJson(new OnlineEnvelope(UUID.randomUUID().toString(),
				OnlineMessageType.AUTH_RESPONSE, payload)));
		}

		private void sendHello(WebSocket webSocket)
		{
			JsonObject payload = new JsonObject();
			payload.addProperty("displayName", displayName);
			payload.addProperty("catalogHash", catalog.getSha256());
			payload.addProperty("rulesetVersion", catalog.getRulesetVersion());
			webSocket.send(gson.toJson(new OnlineEnvelope(UUID.randomUUID().toString(),
				OnlineMessageType.HELLO, payload)));
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable error, Response response)
		{
			long failedGeneration;
			synchronized (OnlineBattleClient.this)
			{
				if (listenerGeneration != generation || socket != webSocket) return;
				socket = null;
				status = Status.DISCONNECTED;
				if (waitingState == WaitingState.CASUAL_QUEUE || waitingState == WaitingState.RANKED_QUEUE)
					waitingState = WaitingState.NONE;
				failedGeneration = generation;
			}
			publishStatus(listenerGeneration, error == null ? "Connection failed" : error.getMessage());
			scheduleReconnect(failedGeneration, reconnectAttempt + 1);
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			onFailure(webSocket, null, null);
		}
	}

	private synchronized void updateWaitingState(OnlineEnvelope envelope)
	{
		JsonObject payload = envelope.getPayload();
		switch (envelope.getType())
		{
			case LOBBY_CREATED: waitingState = WaitingState.LOBBY; break;
			case LOBBY_LEAVE: waitingState = WaitingState.NONE; break;
			case QUEUE_STATUS:
				waitingState = "WAITING".equals(optionalString(payload, "status"))
					? WaitingState.CASUAL_QUEUE : WaitingState.NONE;
				break;
			case RANKED_QUEUE_STATUS:
				waitingState = "WAITING".equals(optionalString(payload, "status"))
					? WaitingState.RANKED_QUEUE : WaitingState.NONE;
				break;
			case MATCH_FOUND: waitingState = WaitingState.NONE; break;
			default: break;
		}
	}

	private void scheduleReconnect(long failedGeneration, int attempt)
	{
		if (attempt > 7) return;
		long delaySeconds = Math.min(15L, 1L << Math.min(4, attempt - 1));
		reconnectExecutor.schedule(() -> reconnect(failedGeneration, attempt), delaySeconds, TimeUnit.SECONDS);
	}

	private synchronized void reconnect(long failedGeneration, int attempt)
	{
		if (generation != failedGeneration || status != Status.DISCONNECTED
			|| reconnectServerUrl == null || displayName == null || catalog == null || deviceKey == null) return;
		long activeGeneration = ++generation;
		status = Status.CONNECTING;
		publishStatus(generation, "Reconnecting");
		Request request = new Request.Builder().url(reconnectServerUrl).build();
		socket = httpClient.newWebSocket(request, new SocketListener(activeGeneration, attempt));
	}

	private static String optionalString(JsonObject payload, String key)
	{
		return payload != null && payload.has(key) && payload.get(key).isJsonPrimitive()
			? payload.get(key).getAsString() : null;
	}

	public enum Status { DISCONNECTED, CONNECTING, AUTHENTICATING, READY, ERROR }
	private enum WaitingState { NONE, LOBBY, CASUAL_QUEUE, RANKED_QUEUE }

	public interface Listener
	{
		void onStatusChanged(long generation, Status status, String message);
		void onMessage(long generation, OnlineEnvelope envelope);
	}
}

package com.osrstcgbattles.online;

import com.google.gson.JsonObject;
import java.util.Objects;

/** Bounded, versioned envelope used for every online WebSocket message. */
public final class OnlineEnvelope
{
	public static final int PROTOCOL_VERSION = 3;
	public static final int MAX_REQUEST_ID_LENGTH = 64;

	private final int protocolVersion;
	private final String requestId;
	private final OnlineMessageType type;
	private final JsonObject payload;

	public OnlineEnvelope(String requestId, OnlineMessageType type, JsonObject payload)
	{
		this(PROTOCOL_VERSION, requestId, type, payload);
	}

	public OnlineEnvelope(int protocolVersion, String requestId, OnlineMessageType type, JsonObject payload)
	{
		if (protocolVersion != PROTOCOL_VERSION) throw new IllegalArgumentException("unsupported protocol version");
		if (requestId == null || requestId.isEmpty() || requestId.length() > MAX_REQUEST_ID_LENGTH)
			throw new IllegalArgumentException("invalid request ID");
		this.protocolVersion = protocolVersion;
		this.requestId = requestId;
		this.type = Objects.requireNonNull(type, "type");
		this.payload = payload == null ? new JsonObject() : payload.deepCopy();
	}

	public int getProtocolVersion() { return protocolVersion; }
	public String getRequestId() { return requestId; }
	public OnlineMessageType getType() { return type; }
	public JsonObject getPayload() { return payload == null ? new JsonObject() : payload.deepCopy(); }

	public void validate()
	{
		if (protocolVersion != PROTOCOL_VERSION) throw new IllegalArgumentException("unsupported protocol version");
		if (requestId == null || requestId.isEmpty() || requestId.length() > MAX_REQUEST_ID_LENGTH)
			throw new IllegalArgumentException("invalid request ID");
		if (type == null) throw new IllegalArgumentException("message type is required");
	}
}

package com.osrstcgbattles.online;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.ConcedeCommand;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.match.MatchView;
import java.util.Objects;
import java.util.concurrent.CopyOnWriteArrayList;

/** Client-side state holder; all authoritative transitions remain on the backend. */
public final class OnlineMatchCoordinator
{
	private final OnlineBattleClient client;
	private final Gson gson;
	private final BattleCardCatalog catalog;
	private final String matchId;
	private final PlayerId localSeat;
	private final String opponentDisplayName;
	private final CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();
	private volatile OnlineMatchSnapshot snapshot;
	private boolean commandInFlight;
	private boolean terminalEventAccepted;

	public OnlineMatchCoordinator(OnlineBattleClient client, Gson gson, BattleCardCatalog catalog,
		OnlineEnvelope matchFound)
	{
		this.client = Objects.requireNonNull(client, "client");
		this.gson = Objects.requireNonNull(gson, "gson");
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		if (matchFound == null || matchFound.getType() != OnlineMessageType.MATCH_FOUND)
			throw new IllegalArgumentException("MATCH_FOUND is required");
		JsonObject payload = matchFound.getPayload();
		matchId = text(payload, "matchId");
		localSeat = PlayerId.valueOf(text(payload, "seat"));
		opponentDisplayName = text(payload, "opponentDisplayName");
		long revision = revision(payload);
		snapshot = new OnlineMatchSnapshot(OnlineMatchSnapshot.Status.WAITING_STATE, matchId, localSeat,
			opponentDisplayName, revision, null, "Waiting for authoritative match state");
	}

	public ReceiveResult receive(OnlineEnvelope envelope)
	{
		if (envelope == null) return ReceiveResult.IGNORED;
		OnlineMatchSnapshot updated = null;
		ReceiveResult result = ReceiveResult.IGNORED;
		synchronized (this)
		{
			if (envelope.getType() == OnlineMessageType.MATCH_STATE
				|| envelope.getType() == OnlineMessageType.MATCH_COMPLETE)
			{
				JsonObject payload = envelope.getPayload();
				if (!matchId.equals(text(payload, "matchId"))) return ReceiveResult.IGNORED;
				long nextRevision = revision(payload);
				OnlineMatchSnapshot current = snapshot;
				if (terminalEventAccepted
					|| nextRevision < current.getRevision()
					|| nextRevision == current.getRevision() && current.getView() != null)
					return ReceiveResult.IGNORED;
				if (payload.get("view") == null || !payload.get("view").isJsonObject())
					throw new IllegalArgumentException("missing view");
				WireMatchView wire = gson.fromJson(payload.get("view"), WireMatchView.class);
				MatchView view = wire.toMatchView(catalog);
				if (view.getViewer() != localSeat) throw new IllegalArgumentException("match viewer does not match local seat");
				boolean terminal = envelope.getType() == OnlineMessageType.MATCH_COMPLETE;
				if (terminal != (view.getStatus() == MatchStatus.COMPLETE))
					throw new IllegalArgumentException("match event does not match view status");
				OnlineMatchSnapshot.Status status = terminal
					? OnlineMatchSnapshot.Status.COMPLETE : OnlineMatchSnapshot.Status.ACTIVE;
				snapshot = new OnlineMatchSnapshot(status, matchId, localSeat, opponentDisplayName,
					nextRevision, view, terminal ? "Match complete" : "Match active");
				commandInFlight = false;
				terminalEventAccepted = terminal;
				updated = snapshot;
				result = terminal ? ReceiveResult.TERMINAL_ACCEPTED : ReceiveResult.UPDATED;
			}
			else if (envelope.getType() == OnlineMessageType.MATCH_REJECTED)
			{
				JsonObject payload = envelope.getPayload();
				if (!matchId.equals(text(payload, "matchId"))) return ReceiveResult.IGNORED;
				OnlineMatchSnapshot current = snapshot;
				long nextRevision = revision(payload);
				if (terminalEventAccepted
					|| nextRevision < current.getRevision()) return ReceiveResult.IGNORED;
				OnlineMatchSnapshot.Status status = current.getView() == null ? OnlineMatchSnapshot.Status.ERROR
					: OnlineMatchSnapshot.Status.ACTIVE;
				snapshot = new OnlineMatchSnapshot(status, matchId, localSeat,
					opponentDisplayName, nextRevision, current.getView(), "Command rejected: " + text(payload, "reason"));
				commandInFlight = false;
				updated = snapshot;
				result = ReceiveResult.UPDATED;
			}
			else if (envelope.getType() == OnlineMessageType.MATCH_ABORTED)
			{
				JsonObject payload = envelope.getPayload();
				if (!matchId.equals(text(payload, "matchId"))) return ReceiveResult.IGNORED;
				OnlineMatchSnapshot current = snapshot;
				if (terminalEventAccepted) return ReceiveResult.IGNORED;
				snapshot = new OnlineMatchSnapshot(OnlineMatchSnapshot.Status.ERROR, matchId, localSeat,
					opponentDisplayName, current.getRevision(), current.getView(), text(payload, "reason"));
				commandInFlight = false;
				terminalEventAccepted = true;
				updated = snapshot;
				result = ReceiveResult.TERMINAL_ACCEPTED;
			}
		}
		if (updated != null) publish(updated);
		return result;
	}

	public boolean submit(Command command)
	{
		long revision;
		synchronized (this)
		{
			OnlineMatchSnapshot current = snapshot;
			if (commandInFlight || current.getStatus() != OnlineMatchSnapshot.Status.ACTIVE) return false;
			commandInFlight = true;
			revision = current.getRevision();
		}
		boolean sent = client.sendCommand(matchId, revision, command);
		if (!sent) synchronized (this) { commandInFlight = false; }
		return sent;
	}

	public boolean concede()
	{
		long revision;
		synchronized (this)
		{
			OnlineMatchSnapshot current = snapshot;
			if (commandInFlight || (current.getStatus() != OnlineMatchSnapshot.Status.ACTIVE
				&& current.getStatus() != OnlineMatchSnapshot.Status.WAITING_STATE)) return false;
			commandInFlight = true;
			revision = current.getRevision();
		}
		boolean sent = client.sendCommand(matchId, revision, new ConcedeCommand(localSeat));
		if (!sent) synchronized (this) { commandInFlight = false; }
		return sent;
	}

	public OnlineMatchSnapshot snapshot() { return snapshot; }
	public void addListener(Listener listener) { listeners.addIfAbsent(Objects.requireNonNull(listener, "listener")); }
	public void removeListener(Listener listener) { listeners.remove(listener); }

	public String getMatchId() { return matchId; }

	public synchronized void transportDisconnected() { commandInFlight = false; }

	public void sessionLost(String reason)
	{
		OnlineMatchSnapshot updated;
		synchronized (this)
		{
			if (terminalEventAccepted) return;
			OnlineMatchSnapshot current = snapshot;
			snapshot = new OnlineMatchSnapshot(OnlineMatchSnapshot.Status.ERROR, matchId, localSeat,
				opponentDisplayName, current.getRevision(), current.getView(), reason);
			commandInFlight = false;
			terminalEventAccepted = true;
			updated = snapshot;
		}
		publish(updated);
	}

	private void publish(OnlineMatchSnapshot current)
	{
		for (Listener listener : listeners)
		{
			try { listener.onOnlineMatchChanged(current); }
			catch (RuntimeException ignored) { }
		}
	}

	private static long revision(JsonObject payload)
	{
		if (payload == null || !payload.has("revision") || !payload.get("revision").isJsonPrimitive()
			|| !payload.get("revision").getAsJsonPrimitive().isNumber())
			throw new IllegalArgumentException("missing revision");
		try
		{
			long value = payload.get("revision").getAsBigDecimal().longValueExact();
			if (value < 0) throw new IllegalArgumentException("invalid revision");
			return value;
		}
		catch (ArithmeticException | NumberFormatException exception)
		{
			throw new IllegalArgumentException("invalid revision", exception);
		}
	}

	private static String text(JsonObject payload, String key)
	{
		if (payload == null || !payload.has(key) || !payload.get(key).isJsonPrimitive())
			throw new IllegalArgumentException("missing " + key);
		String value = payload.get(key).getAsString();
		if (value.isEmpty()) throw new IllegalArgumentException("invalid " + key);
		return value;
	}

	public interface Listener
	{
		void onOnlineMatchChanged(OnlineMatchSnapshot snapshot);
	}

	public enum ReceiveResult { IGNORED, UPDATED, TERMINAL_ACCEPTED }
}

package com.osrstcgbattles.online;

