package com.osrstcgbattles.party;

import com.google.gson.Gson;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserPart;

/** Live RuneLite adapter for the pure battle-party protocol coordinator. */
@Singleton
public final class BattlePartyService
{
	private static final int MAX_QUEUED_APPLICATIONS = 128;

	private final PartyService partyService;
	private final WSClient wsClient;
	private final EventBus eventBus;
	private final ClientThread clientThread;
	private final Gson gson;
	private final CanonicalPartyJsonCodec applicationCodec;
	private final Deque<QueuedApplication> applicationQueue = new ArrayDeque<>();
	private final CopyOnWriteArrayList<BattlePartyListener> listeners = new CopyOnWriteArrayList<>();
	private volatile PartyDuelSnapshot snapshot = PartyDuelSnapshot.idle();
	private volatile List<PartyOpponent> eligibleOpponents = Collections.emptyList();
	private volatile boolean started;
	private BattlePartyCoordinator coordinator;
	private boolean submissionPending;

	@Inject
	public BattlePartyService(PartyService partyService, WSClient wsClient, EventBus eventBus, ClientThread clientThread,
		Gson gson)
	{
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.eventBus = eventBus;
		this.clientThread = clientThread;
		this.gson = gson;
		this.applicationCodec = new CanonicalPartyJsonCodec(gson);
	}

	public synchronized void start()
	{
		if (started) return;
		wsClient.registerMessage(BattlePartyEnvelope.class);
		try
		{
			eventBus.register(this);
			started = true;
		}
		catch (RuntimeException exception)
		{
			wsClient.unregisterMessage(BattlePartyEnvelope.class);
			throw exception;
		}
		clientThread.invoke(this::refreshPartyContext);
	}

	public synchronized void stop()
	{
		if (!started) return;
		started = false;
		submissionPending = false;
		applicationQueue.clear();
		try
		{
			eventBus.unregister(this);
		}
		finally
		{
			wsClient.unregisterMessage(BattlePartyEnvelope.class);
		}
		clientThread.invoke(() ->
		{
			if (started) return;
			coordinator = null;
			eligibleOpponents = Collections.emptyList();
			publish(PartyDuelSnapshot.idle());
		});
	}

	public boolean invite(long recipientMemberId, String catalogHash, int rulesetVersion, String deckId,
		String deckCommitment)
	{
		synchronized (this)
		{
			if (!started || submissionPending) return false;
			submissionPending = true;
		}
		PartyDuelMetadata metadata = new PartyDuelMetadata(catalogHash, rulesetVersion, deckId, deckCommitment);
		try
		{
			clientThread.invoke(() ->
			{
				try
				{
					if (!started) throw new IllegalStateException("party service is stopped");
					PartyMember local = requireLocalMember();
					PartyMember peer = requireEligiblePeer(recipientMemberId, local.getMemberId());
					ensureCoordinator(local.getMemberId()).invite(peer.getMemberId(), peer.getDisplayName(), metadata,
						System.nanoTime());
					flushAndPublish();
				}
				catch (RuntimeException exception)
				{
					notifyOperationFailed("Unable to send the party duel invitation");
				}
				finally
				{
					synchronized (BattlePartyService.this) { submissionPending = false; }
				}
			});
		}
		catch (RuntimeException exception)
		{
			synchronized (this) { submissionPending = false; }
			return false;
		}
		return true;
	}

	public boolean accept(String catalogHash, int rulesetVersion, String deckId, String deckCommitment)
	{
		synchronized (this)
		{
			if (!started || submissionPending) return false;
			submissionPending = true;
		}
		PartyDuelMetadata metadata = new PartyDuelMetadata(catalogHash, rulesetVersion, deckId, deckCommitment);
		try
		{
			clientThread.invoke(() ->
			{
				try
				{
					if (!started || coordinator == null) throw new IllegalStateException("no invitation to accept");
					coordinator.accept(metadata);
					flushAndPublish();
				}
				catch (RuntimeException exception)
				{
					notifyOperationFailed("Unable to accept the party duel invitation");
				}
				finally
				{
					synchronized (BattlePartyService.this) { submissionPending = false; }
				}
			});
		}
		catch (RuntimeException exception)
		{
			synchronized (this) { submissionPending = false; }
			return false;
		}
		return true;
	}

	public void decline()
	{
		clientThread.invoke(() ->
		{
			if (!started || coordinator == null) return;
			coordinator.decline();
			flushAndPublish();
		});
	}

	public void abort()
	{
		clientThread.invoke(() ->
		{
			if (!started || coordinator == null) return;
			coordinator.abort("Party duel aborted");
			flushAndPublish();
		});
	}

	public boolean queueApplication(BattlePartyMessageType type, Map<String, ?> payload)
	{
		if (!PartyApplicationMessage.isAllowedType(type))
			throw new IllegalArgumentException("unsupported application message type");
		synchronized (this)
		{
			if (!applicationTransportAvailable()) return false;
		}
		Map<String, Object> canonical = applicationCodec.decodeMap(applicationCodec.encodeMap(payload));
		synchronized (this)
		{
			if (!applicationTransportAvailable() || applicationQueue.size() >= MAX_QUEUED_APPLICATIONS) return false;
			applicationQueue.addLast(new QueuedApplication(type, canonical));
		}
		try
		{
			clientThread.invoke(this::drainApplicationQueue);
		}
		catch (RuntimeException ignored)
		{
			// GameTick is the fallback drain; the accepted entry remains queued.
		}
		return true;
	}

	public void sendApplication(BattlePartyMessageType type, Map<String, ?> payload)
	{
		if (!queueApplication(type, payload))
			throw new IllegalStateException("application transport is unavailable");
	}

	public PartyDuelSnapshot getSnapshot() { return snapshot; }
	public List<PartyOpponent> getEligibleOpponents() { return eligibleOpponents; }
	public long getLocalMemberId()
	{
		PartyMember local = partyService.getLocalMember();
		return local == null || !local.isLoggedIn() ? 0L : local.getMemberId();
	}
	public void addListener(BattlePartyListener listener)
	{
		if (listener == null) throw new IllegalArgumentException("listener is required");
		listeners.addIfAbsent(listener);
	}
	public void removeListener(BattlePartyListener listener) { listeners.remove(listener); }

	private void notifyOperationFailed(String message)
	{
		for (BattlePartyListener listener : listeners)
		{
			try { listener.onPartyOperationFailed(message); }
			catch (RuntimeException ignored) { /* A listener must not break service processing. */ }
		}
	}

	@Subscribe
	public void onBattlePartyEnvelope(BattlePartyEnvelope message)
	{
		clientThread.invoke(() -> processEnvelope(message));
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		clientThread.invoke(() ->
		{
			if (!started) return;
			if (coordinator != null) coordinator.onUserPart(event.getMemberId());
			refreshEligibleOpponents();
			flushAndPublish();
		});
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		clientThread.invoke(this::refreshPartyContext);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		clientThread.invoke(() ->
		{
			if (!started) return;
			refreshEligibleOpponents();
			if (coordinator != null) coordinator.onTick(System.nanoTime());
			drainApplicationQueue();
			flushAndPublish();
		});
	}

	private void processEnvelope(BattlePartyEnvelope message)
	{
		if (!started || !partyService.isInParty()) return;
		PartyMember local = partyService.getLocalMember();
		PartyMember sender = partyService.getMemberById(message.getMemberId());
		if (local == null || !local.isLoggedIn() || sender == null) return;
		BattlePartyCoordinator active = ensureCoordinator(local.getMemberId());
		active.receive(message.getMemberId(), sender.getDisplayName(), sender.isLoggedIn(), message, System.nanoTime());
		// A later envelope can race or arrive before a retransmission. Leave the session open so the
		// sender can retransmit the missing authenticated envelope with its original sequence.
		flushAndPublish();
	}

	private BattlePartyCoordinator ensureCoordinator(long localMemberId)
	{
		if (coordinator == null || coordinator.getLocalMemberId() != localMemberId)
		{
			coordinator = new BattlePartyCoordinator(localMemberId, gson);
		}
		return coordinator;
	}

	private PartyMember requireLocalMember()
	{
		PartyMember local = partyService.getLocalMember();
		if (!partyService.isInParty() || local == null || !local.isLoggedIn())
			throw new IllegalStateException("not logged into a RuneLite party");
		return local;
	}

	private PartyMember requireEligiblePeer(long memberId, long localMemberId)
	{
		PartyMember peer = partyService.getMemberById(memberId);
		if (memberId == localMemberId || peer == null || !peer.isLoggedIn())
			throw new IllegalArgumentException("opponent is not an eligible party member");
		return peer;
	}

	private void refreshPartyContext()
	{
		if (!started) return;
		PartyMember local = partyService.getLocalMember();
		if (!partyService.isInParty() || local == null || !local.isLoggedIn())
		{
			if (coordinator != null)
			{
				coordinator.abort("RuneLite party is unavailable");
				coordinator.drainOutbound();
			}
			eligibleOpponents = Collections.emptyList();
			publish(coordinator == null ? PartyDuelSnapshot.idle() : coordinator.snapshot());
			return;
		}
		ensureCoordinator(local.getMemberId());
		refreshEligibleOpponents();
		flushAndPublish();
	}

	private void refreshEligibleOpponents()
	{
		PartyMember local = partyService.getLocalMember();
		if (!partyService.isInParty() || local == null)
		{
			eligibleOpponents = Collections.emptyList();
			return;
		}
		List<PartyOpponent> choices = new ArrayList<>();
		for (PartyMember member : partyService.getMembers())
		{
			if (member.getMemberId() != local.getMemberId() && member.isLoggedIn())
				choices.add(new PartyOpponent(member.getMemberId(), member.getDisplayName()));
		}
		choices.sort(Comparator.comparing(PartyOpponent::getDisplayName, String.CASE_INSENSITIVE_ORDER)
			.thenComparingLong(PartyOpponent::getMemberId));
		eligibleOpponents = Collections.unmodifiableList(choices);
	}

	private void flushAndPublish()
	{
		if (coordinator == null) return;
		for (BattlePartyEnvelope message : coordinator.drainOutbound())
		{
			if (partyService.isInParty()) partyService.send(message);
		}
		for (PartyApplicationMessage message : coordinator.drainInboundApplication())
		{
			for (BattlePartyListener listener : listeners)
			{
				try { listener.onPartyApplicationMessage(message); }
				catch (RuntimeException ignored) { /* A listener must not break transport processing. */ }
			}
		}
		publish(coordinator.snapshot());
	}

	private boolean applicationTransportAvailable()
	{
		return started && coordinator != null && snapshot.getStatus() == PartyDuelSnapshot.Status.READY;
	}

	private void drainApplicationQueue()
	{
		while (true)
		{
			synchronized (this)
			{
				if (!applicationTransportAvailable())
				{
					applicationQueue.clear();
					return;
				}
				QueuedApplication next = applicationQueue.peekFirst();
				if (next == null) return;
				try
				{
					if (!partyService.isInParty())
						throw new IllegalStateException("RuneLite party is unavailable");
					coordinator.sendApplication(next.type, next.payload);
					flushAndPublish();
					applicationQueue.removeFirst();
				}
				catch (RuntimeException exception)
				{
					applicationQueue.clear();
					try
					{
						coordinator.abort("Application transport failed");
						flushAndPublish();
					}
					catch (RuntimeException ignored)
					{
						publish(coordinator.snapshot());
					}
					return;
				}
			}
		}
	}

	private void publish(PartyDuelSnapshot next)
	{
		if (next.equals(snapshot)) return;
		snapshot = next;
		for (BattlePartyListener listener : listeners)
		{
			try { listener.onPartyDuelSnapshotChanged(next); }
			catch (RuntimeException ignored) { /* A UI listener must not break transport processing. */ }
		}
	}

	private static final class QueuedApplication
	{
		private final BattlePartyMessageType type;
		private final Map<String, Object> payload;

		private QueuedApplication(BattlePartyMessageType type, Map<String, Object> payload)
		{
			this.type = type;
			this.payload = payload;
		}
	}
}

package com.osrstcgbattles.party;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Bounded canonical JSON for protocol DTOs; it never accepts a runtime type discriminator. */
public final class CanonicalPartyJsonCodec
{
	public static final int MAX_JSON_BYTES = 16 * 1024;
	private static final int MAX_DEPTH = 16;
	private static final int MAX_CONTAINER_ENTRIES = 256;
	private static final int MAX_STRING_LENGTH = 4096;
	private final Gson gson;

	public CanonicalPartyJsonCodec(Gson gson)
	{
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public String encodeMap(Map<String, ?> payload)
	{
		Objects.requireNonNull(payload, "payload");
		return encodeElement(gson.toJsonTree(payload, Map.class));
	}

	public Map<String, Object> decodeMap(String json)
	{
		JsonElement root = parseBounded(json);
		if (!root.isJsonObject())
		{
			throw new IllegalArgumentException("payload must be a JSON object");
		}
		@SuppressWarnings("unchecked")
		Map<String, Object> decoded = gson.fromJson(root, LinkedHashMap.class);
		return immutableMap(decoded);
	}

	private static Map<String, Object> immutableMap(Map<String, Object> source)
	{
		Map<String, Object> copy = new LinkedHashMap<>();
		for (Map.Entry<String, Object> entry : source.entrySet())
		{
			copy.put(entry.getKey(), immutableValue(entry.getValue()));
		}
		return Collections.unmodifiableMap(copy);
	}

	private static Object immutableValue(Object value)
	{
		if (value instanceof Map)
		{
			@SuppressWarnings("unchecked")
			Map<String, Object> map = (Map<String, Object>) value;
			return immutableMap(map);
		}
		if (value instanceof List)
		{
			List<Object> copy = new ArrayList<>();
			for (Object child : (List<?>) value) copy.add(immutableValue(child));
			return Collections.unmodifiableList(copy);
		}
		return value;
	}

	private String encodeElement(JsonElement element)
	{
		validateElement(element, 0);
		String encoded = canonicalize(element).toString();
		checkByteLength(encoded);
		return encoded;
	}

	private JsonElement parseBounded(String json)
	{
		if (json == null)
		{
			throw new IllegalArgumentException("json is required");
		}
		checkByteLength(json);
		try
		{
			JsonElement element = gson.fromJson(json, JsonElement.class);
			if (element == null)
			{
				throw new IllegalArgumentException("json is empty");
			}
			validateElement(element, 0);
			return element;
		}
		catch (JsonParseException exception)
		{
			throw new IllegalArgumentException("invalid json", exception);
		}
	}

	private static JsonElement canonicalize(JsonElement element)
	{
		if (element.isJsonObject())
		{
			JsonObject result = new JsonObject();
			List<String> names = new ArrayList<>();
			for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
			{
				names.add(entry.getKey());
			}
			Collections.sort(names);
			for (String name : names)
			{
				result.add(name, canonicalize(element.getAsJsonObject().get(name)));
			}
			return result;
		}
		if (element.isJsonArray())
		{
			JsonArray result = new JsonArray();
			for (JsonElement child : element.getAsJsonArray())
			{
				result.add(canonicalize(child));
			}
			return result;
		}
		return element.deepCopy();
	}

	private static void validateElement(JsonElement element, int depth)
	{
		if (depth > MAX_DEPTH)
		{
			throw new IllegalArgumentException("JSON nesting is too deep");
		}
		if (element.isJsonObject())
		{
			if (element.getAsJsonObject().size() > MAX_CONTAINER_ENTRIES)
			{
				throw new IllegalArgumentException("JSON object has too many fields");
			}
			for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet())
			{
				if (entry.getKey().length() > 128)
				{
					throw new IllegalArgumentException("JSON field name is too long");
				}
				validateElement(entry.getValue(), depth + 1);
			}
		}
		else if (element.isJsonArray())
		{
			if (element.getAsJsonArray().size() > MAX_CONTAINER_ENTRIES)
			{
				throw new IllegalArgumentException("JSON array has too many entries");
			}
			for (JsonElement child : element.getAsJsonArray())
			{
				validateElement(child, depth + 1);
			}
		}
		else if (element.isJsonPrimitive() && element.getAsJsonPrimitive().isString()
			&& element.getAsString().length() > MAX_STRING_LENGTH)
		{
			throw new IllegalArgumentException("JSON string is too long");
		}
	}

	private static void checkByteLength(String json)
	{
		if (json.getBytes(StandardCharsets.UTF_8).length > MAX_JSON_BYTES)
		{
			throw new IllegalArgumentException("JSON payload is too large");
		}
	}
}

package com.osrstcgbattles.party;

import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** Creates the public, deterministic commitment used by the party duel handshake. */
public final class DeckCommitment
{
	private static final byte[] DOMAIN = "OSRS-TCG-DECK-COMMITMENT-V1".getBytes(StandardCharsets.US_ASCII);

	private DeckCommitment()
	{
	}

	public static String compute(String catalogHash, int rulesetVersion, Deck deck)
	{
		Objects.requireNonNull(catalogHash, "catalogHash");
		Objects.requireNonNull(deck, "deck");
		if (rulesetVersion <= 0)
		{
			throw new IllegalArgumentException("rulesetVersion must be positive");
		}

		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			updateBytes(digest, DOMAIN);
			updateString(digest, catalogHash);
			updateInt(digest, rulesetVersion);
			updateString(digest, deck.getId());
			List<DeckEntry> entries = new ArrayList<>(deck.getEntries());
			entries.sort(Comparator.comparing(DeckEntry::getCardId).thenComparingInt(DeckEntry::getCount));
			updateInt(digest, entries.size());
			for (DeckEntry entry : entries)
			{
				updateString(digest, entry.getCardId());
				updateInt(digest, entry.getCount());
			}
			return toHex(digest.digest());
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}

	private static void updateString(MessageDigest digest, String value)
	{
		updateBytes(digest, Objects.requireNonNull(value, "value").getBytes(StandardCharsets.UTF_8));
	}

	private static void updateBytes(MessageDigest digest, byte[] value)
	{
		updateInt(digest, value.length);
		digest.update(value);
	}

	private static void updateInt(MessageDigest digest, int value)
	{
		digest.update(ByteBuffer.allocate(Integer.BYTES).putInt(value).array());
	}

	private static String toHex(byte[] bytes)
	{
		StringBuilder result = new StringBuilder(bytes.length * 2);
		for (byte value : bytes)
		{
			result.append(Character.forDigit((value >>> 4) & 0xf, 16));
			result.append(Character.forDigit(value & 0xf, 16));
		}
		return result.toString();
	}
}

package com.osrstcgbattles.party;

import java.util.Arrays;

public final class EncryptedPartyPayload
{
	private final byte[] nonce;
	private final byte[] ciphertext;

	public EncryptedPartyPayload(byte[] nonce, byte[] ciphertext)
	{
		this.nonce = Arrays.copyOf(nonce, nonce.length);
		this.ciphertext = Arrays.copyOf(ciphertext, ciphertext.length);
	}

	public byte[] getNonce()
	{
		return Arrays.copyOf(nonce, nonce.length);
	}

	public byte[] getCiphertext()
	{
		return Arrays.copyOf(ciphertext, ciphertext.length);
	}
}

package com.osrstcgbattles.party;

import java.util.Map;
import java.util.Objects;

/** An authenticated application payload received from the current party peer. */
public final class PartyApplicationMessage
{
	private final BattlePartyMessageType type;
	private final String matchId;
	private final long peerMemberId;
	private final long sequence;
	private final Map<String, Object> payload;

	public PartyApplicationMessage(BattlePartyMessageType type, String matchId, long peerMemberId, long sequence,
		Map<String, ?> payload, CanonicalPartyJsonCodec codec)
	{
		if (!isAllowedType(type)) throw new IllegalArgumentException("unsupported application message type");
		if (matchId == null || matchId.isEmpty() || matchId.length() > BattlePartyEnvelope.MAX_ID_LENGTH)
			throw new IllegalArgumentException("invalid matchId");
		if (peerMemberId <= 0) throw new IllegalArgumentException("peerMemberId must be positive");
		if (sequence <= 0 || sequence > BattlePartyEnvelope.MAX_SEQUENCE)
			throw new IllegalArgumentException("sequence is out of bounds");
		Objects.requireNonNull(payload, "payload");
		this.type = type;
		this.matchId = matchId;
		this.peerMemberId = peerMemberId;
		this.sequence = sequence;
		this.payload = codec.decodeMap(codec.encodeMap(payload));
	}

	static boolean isAllowedType(BattlePartyMessageType type)
	{
		return type == BattlePartyMessageType.ACTION || type == BattlePartyMessageType.ACTION_ACK
			|| type == BattlePartyMessageType.SNAPSHOT;
	}

	public BattlePartyMessageType getType() { return type; }
	public String getMatchId() { return matchId; }
	public long getPeerMemberId() { return peerMemberId; }
	public long getSequence() { return sequence; }
	public Map<String, Object> getPayload() { return payload; }
}

package com.osrstcgbattles.party;

import java.util.Objects;
import java.util.regex.Pattern;

/** Validated metadata exchanged only inside the encrypted READY message. */
public final class PartyDuelMetadata
{
	private static final Pattern SHA256 = Pattern.compile("[0-9a-fA-F]{64}");
	private final String catalogHash;
	private final int rulesetVersion;
	private final String deckId;
	private final String deckCommitment;

	public PartyDuelMetadata(String catalogHash, int rulesetVersion, String deckId, String deckCommitment)
	{
		if (!isSha256(catalogHash) || rulesetVersion <= 0 || rulesetVersion > 1_000_000
			|| !isBoundedId(deckId) || !isSha256(deckCommitment))
		{
			throw new IllegalArgumentException("invalid duel metadata");
		}
		this.catalogHash = catalogHash.toLowerCase(java.util.Locale.ROOT);
		this.rulesetVersion = rulesetVersion;
		this.deckId = Objects.requireNonNull(deckId, "deckId");
		this.deckCommitment = deckCommitment.toLowerCase(java.util.Locale.ROOT);
	}

	private static boolean isSha256(String value) { return value != null && SHA256.matcher(value).matches(); }
	private static boolean isBoundedId(String value)
	{
		if (value == null || value.isEmpty() || value.length() > BattlePartyEnvelope.MAX_ID_LENGTH) return false;
		for (int i = 0; i < value.length(); i++) if (value.charAt(i) < 0x21 || value.charAt(i) > 0x7e) return false;
		return true;
	}

	public String getCatalogHash() { return catalogHash; }
	public int getRulesetVersion() { return rulesetVersion; }
	public String getDeckId() { return deckId; }
	public String getDeckCommitment() { return deckCommitment; }
}

package com.osrstcgbattles.party;

import java.util.Objects;

/** Immutable, secret-free view of the current party transport session. */
public final class PartyDuelSnapshot
{
	public enum Status
	{
		IDLE, OUTBOUND_INVITE, INBOUND_INVITE, HANDSHAKE, READY, TERMINAL
	}

	private static final PartyDuelSnapshot IDLE = new PartyDuelSnapshot(Status.IDLE, null, 0, null,
		"No party duel in progress", false, false, false, null, 0, null, null);

	private final Status status;
	private final String matchId;
	private final long peerMemberId;
	private final String peerDisplayName;
	private final String userStatus;
	private final boolean canAccept;
	private final boolean canDecline;
	private final boolean canAbort;
	private final String catalogHash;
	private final int rulesetVersion;
	private final String deckId;
	private final String deckCommitment;
	private final String peerDeckId;
	private final String peerDeckCommitment;

	PartyDuelSnapshot(Status status, String matchId, long peerMemberId, String peerDisplayName,
		String userStatus, boolean canAccept, boolean canDecline, boolean canAbort, String catalogHash,
		int rulesetVersion, String deckId, String deckCommitment)
	{
		this(status, matchId, peerMemberId, peerDisplayName, userStatus, canAccept, canDecline, canAbort,
			catalogHash, rulesetVersion, deckId, deckCommitment, null, null);
	}

	PartyDuelSnapshot(Status status, String matchId, long peerMemberId, String peerDisplayName,
		String userStatus, boolean canAccept, boolean canDecline, boolean canAbort, String catalogHash,
		int rulesetVersion, String deckId, String deckCommitment, String peerDeckId, String peerDeckCommitment)
	{
		this.status = Objects.requireNonNull(status, "status");
		this.matchId = matchId;
		this.peerMemberId = peerMemberId;
		this.peerDisplayName = peerDisplayName;
		this.userStatus = Objects.requireNonNull(userStatus, "userStatus");
		this.canAccept = canAccept;
		this.canDecline = canDecline;
		this.canAbort = canAbort;
		this.catalogHash = catalogHash;
		this.rulesetVersion = rulesetVersion;
		this.deckId = deckId;
		this.deckCommitment = deckCommitment;
		this.peerDeckId = peerDeckId;
		this.peerDeckCommitment = peerDeckCommitment;
	}

	public static PartyDuelSnapshot idle() { return IDLE; }
	public Status getStatus() { return status; }
	public String getMatchId() { return matchId; }
	public long getPeerMemberId() { return peerMemberId; }
	public String getPeerDisplayName() { return peerDisplayName; }
	public String getUserStatus() { return userStatus; }
	public boolean canAccept() { return canAccept; }
	public boolean canDecline() { return canDecline; }
	public boolean canAbort() { return canAbort; }
	public boolean isAcceptAvailable() { return canAccept; }
	public boolean isDeclineAvailable() { return canDecline; }
	public boolean isAbortAvailable() { return canAbort; }
	public String getCatalogHash() { return catalogHash; }
	public int getRulesetVersion() { return rulesetVersion; }
	public String getDeckId() { return deckId; }
	public String getDeckCommitment() { return deckCommitment; }
	public String getPeerDeckId() { return peerDeckId; }
	public String getPeerDeckCommitment() { return peerDeckCommitment; }

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof PartyDuelSnapshot)) return false;
		PartyDuelSnapshot that = (PartyDuelSnapshot) other;
		return status == that.status && peerMemberId == that.peerMemberId && rulesetVersion == that.rulesetVersion
			&& canAccept == that.canAccept && canDecline == that.canDecline && canAbort == that.canAbort
			&& Objects.equals(matchId, that.matchId) && Objects.equals(peerDisplayName, that.peerDisplayName)
			&& userStatus.equals(that.userStatus) && Objects.equals(catalogHash, that.catalogHash)
			&& Objects.equals(deckId, that.deckId) && Objects.equals(deckCommitment, that.deckCommitment)
			&& Objects.equals(peerDeckId, that.peerDeckId)
			&& Objects.equals(peerDeckCommitment, that.peerDeckCommitment);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(status, matchId, peerMemberId, peerDisplayName, userStatus, canAccept, canDecline,
			canAbort, catalogHash, rulesetVersion, deckId, deckCommitment, peerDeckId, peerDeckCommitment);
	}
}

