package com.osrstcgbattles.party;

import java.util.Objects;

/** Pure protocol ordering and handshake state; transport and cryptography are deliberately external. */
public final class PartySessionStateMachine
{
	public enum State
	{
		NEW, INVITE_SENT, INVITE_RECEIVED, INVITE_ACKNOWLEDGED, ACCEPTED, KEY_EXCHANGED, READY,
		DECLINED, ABORTED
	}

	public enum Result
	{
		ACCEPTED, DUPLICATE, STALE, GAP, WRONG_PEER, WRONG_MATCH, WRONG_RECIPIENT, INVALID_MESSAGE,
		INVALID_STATE, TERMINAL
	}

	private final String matchId;
	private final long localMemberId;
	private final long peerMemberId;
	private final RecentMessageIds recentMessageIds;
	private long nextInboundSequence = 1;
	private State state = State.NEW;
	private boolean localKey;
	private boolean peerKey;
	private boolean localReady;
	private boolean peerReady;

	public PartySessionStateMachine(String matchId, long localMemberId, long peerMemberId, int replayCapacity)
	{
		this.matchId = Objects.requireNonNull(matchId, "matchId");
		if (matchId.isEmpty() || matchId.length() > BattlePartyEnvelope.MAX_ID_LENGTH
			|| localMemberId <= 0 || peerMemberId <= 0 || localMemberId == peerMemberId)
		{
			throw new IllegalArgumentException("invalid session identity");
		}
		this.localMemberId = localMemberId;
		this.peerMemberId = peerMemberId;
		this.recentMessageIds = new RecentMessageIds(replayCapacity);
	}

	public Result acceptIncoming(long senderMemberId, BattlePartyEnvelope message)
	{
		if (senderMemberId != peerMemberId)
		{
			return Result.WRONG_PEER;
		}
		if (message == null)
		{
			return Result.INVALID_MESSAGE;
		}
		if (!matchId.equals(message.getMatchId()))
		{
			return Result.WRONG_MATCH;
		}
		if (message.getRecipientMemberId() != localMemberId)
		{
			return Result.WRONG_RECIPIENT;
		}
		try
		{
			message.validate();
		}
		catch (IllegalArgumentException exception)
		{
			return Result.INVALID_MESSAGE;
		}
		if (recentMessageIds.contains(message.getMessageId()))
		{
			return Result.DUPLICATE;
		}
		if (message.getSequence() < nextInboundSequence)
		{
			return Result.STALE;
		}
		if (message.getSequence() > nextInboundSequence)
		{
			return Result.GAP;
		}
		Result transition = transition(message.getMessageType(), false);
		if (transition == Result.ACCEPTED)
		{
			recentMessageIds.add(message.getMessageId());
			nextInboundSequence++;
		}
		return transition;
	}

	public Result recordLocal(BattlePartyMessageType type)
	{
		return transition(Objects.requireNonNull(type, "type"), true);
	}

	private Result transition(BattlePartyMessageType type, boolean local)
	{
		if (isTerminal())
		{
			return Result.TERMINAL;
		}
		if (type == BattlePartyMessageType.DECLINE)
		{
			state = State.DECLINED;
			return Result.ACCEPTED;
		}
		if (type == BattlePartyMessageType.ABORT)
		{
			state = State.ABORTED;
			return Result.ACCEPTED;
		}
		switch (type)
		{
			case INVITE:
				if (state != State.NEW) return Result.INVALID_STATE;
				state = local ? State.INVITE_SENT : State.INVITE_RECEIVED;
				return Result.ACCEPTED;
			case INVITE_ACK:
				if ((local && state != State.INVITE_RECEIVED) || (!local && state != State.INVITE_SENT))
					return Result.INVALID_STATE;
				state = State.INVITE_ACKNOWLEDGED;
				return Result.ACCEPTED;
			case ACCEPT:
				if (state != State.INVITE_ACKNOWLEDGED) return Result.INVALID_STATE;
				state = State.ACCEPTED;
				return Result.ACCEPTED;
			case KEY:
				if (state != State.ACCEPTED && state != State.KEY_EXCHANGED) return Result.INVALID_STATE;
				if (local) localKey = true; else peerKey = true;
				if (localKey && peerKey) state = State.KEY_EXCHANGED;
				return Result.ACCEPTED;
			case READY:
				if (state != State.KEY_EXCHANGED && state != State.READY) return Result.INVALID_STATE;
				if (local) localReady = true; else peerReady = true;
				if (localReady && peerReady) state = State.READY;
				return Result.ACCEPTED;
			case ACTION:
			case ACTION_ACK:
			case SNAPSHOT:
				return state == State.READY ? Result.ACCEPTED : Result.INVALID_STATE;
			default:
				return Result.INVALID_STATE;
		}
	}

	public State getState() { return state; }
	public long getNextInboundSequence() { return nextInboundSequence; }
	public boolean isTerminal()
	{
		return state == State.DECLINED || state == State.ABORTED;
	}
}

package com.osrstcgbattles.party;

import java.util.LinkedHashMap;
import java.util.Map;

/** Fixed-capacity insertion-ordered replay cache. */
public final class RecentMessageIds
{
	private final int capacity;
	private final Map<String, Boolean> ids;

	public RecentMessageIds(int capacity)
	{
		if (capacity <= 0 || capacity > 65_536)
		{
			throw new IllegalArgumentException("capacity is out of bounds");
		}
		this.capacity = capacity;
		this.ids = new LinkedHashMap<>();
	}

	/** Returns false when the ID was already present. */
	public synchronized boolean add(String messageId)
	{
		if (messageId == null || messageId.isEmpty() || messageId.length() > BattlePartyEnvelope.MAX_ID_LENGTH)
		{
			throw new IllegalArgumentException("invalid messageId");
		}
		if (ids.containsKey(messageId))
		{
			return false;
		}
		ids.put(messageId, Boolean.TRUE);
		if (ids.size() > capacity)
		{
			String oldest = ids.keySet().iterator().next();
			ids.remove(oldest);
		}
		return true;
	}

	public synchronized boolean contains(String messageId)
	{
		return ids.containsKey(messageId);
	}

	public synchronized int size()
	{
		return ids.size();
	}
}

package com.osrstcgbattles.persist;

import com.osrstcgbattles.deck.Deck;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/** Immutable collection of decks and the deck selected in the active RuneLite profile. */
public final class DeckProfile
{
	private final List<Deck> decks;
	private final String selectedDeckId;

	public DeckProfile(List<Deck> decks, String selectedDeckId)
	{
		this.decks = Collections.unmodifiableList(new ArrayList<>(Objects.requireNonNull(decks, "decks")));
		if (this.decks.contains(null))
		{
			throw new NullPointerException("decks must not contain null");
		}

		Set<String> ids = new HashSet<>();
		for (Deck deck : this.decks)
		{
			if (!ids.add(deck.getId()))
			{
				throw new IllegalArgumentException("Duplicate deck id: " + deck.getId());
			}
		}
		if (selectedDeckId != null && !ids.contains(selectedDeckId))
		{
			throw new IllegalArgumentException("Selected deck does not exist: " + selectedDeckId);
		}
		this.selectedDeckId = selectedDeckId;
	}

	public static DeckProfile empty()
	{
		return new DeckProfile(Collections.emptyList(), null);
	}

	public List<Deck> getDecks()
	{
		return decks;
	}

	public Optional<String> getSelectedDeckId()
	{
		return Optional.ofNullable(selectedDeckId);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof DeckProfile))
		{
			return false;
		}
		DeckProfile that = (DeckProfile) other;
		return decks.equals(that.decks) && Objects.equals(selectedDeckId, that.selectedDeckId);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(decks, selectedDeckId);
	}
}

package com.osrstcgbattles.persist;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.deck.DeckValidator;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/** Versioned JSON codec containing only non-sensitive deck data. */
public final class DeckProfileCodec
{
	public static final int CURRENT_VERSION = 1;
	public static final int MAX_DECKS = 100;
	public static final int MAX_ENTRIES_PER_DECK = 100;
	public static final int MAX_JSON_BYTES = 1024 * 1024;

	private final Gson gson;

	public DeckProfileCodec(Gson gson)
	{
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public String encode(DeckProfile profile)
	{
		Objects.requireNonNull(profile, "profile");
		if (profile.getDecks().size() > MAX_DECKS)
		{
			throw new IllegalArgumentException("Profile contains too many decks");
		}
		StoredProfile stored = new StoredProfile();
		stored.version = CURRENT_VERSION;
		stored.selectedDeckId = profile.getSelectedDeckId().orElse(null);
		stored.decks = new ArrayList<>();
		for (Deck deck : profile.getDecks())
		{
			validateDeck(deck);
			StoredDeck storedDeck = new StoredDeck();
			storedDeck.id = deck.getId();
			storedDeck.name = deck.getName();
			storedDeck.entries = new ArrayList<>();
			for (DeckEntry entry : deck.getEntries())
			{
				StoredEntry storedEntry = new StoredEntry();
				storedEntry.cardId = entry.getCardId();
				storedEntry.count = entry.getCount();
				storedDeck.entries.add(storedEntry);
			}
			stored.decks.add(storedDeck);
		}
		String json = gson.toJson(stored);
		if (utf8Length(json) > MAX_JSON_BYTES)
		{
			throw new IllegalArgumentException("Encoded profile is too large");
		}
		return json;
	}

	public Optional<DeckProfile> decode(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return Optional.empty();
		}
		if (utf8Length(json) > MAX_JSON_BYTES)
		{
			return Optional.empty();
		}
		try
		{
			StoredProfile stored = gson.fromJson(json, StoredProfile.class);
			if (stored == null || stored.version != CURRENT_VERSION || stored.decks == null
				|| stored.decks.size() > MAX_DECKS)
			{
				return Optional.empty();
			}
			List<Deck> decks = new ArrayList<>();
			for (StoredDeck storedDeck : stored.decks)
			{
				if (storedDeck == null || isBlank(storedDeck.id) || isBlank(storedDeck.name)
					|| storedDeck.entries == null || storedDeck.entries.size() > MAX_ENTRIES_PER_DECK)
				{
					return Optional.empty();
				}
				List<DeckEntry> entries = new ArrayList<>();
				Set<String> cardIds = new HashSet<>();
				for (StoredEntry storedEntry : storedDeck.entries)
				{
					if (storedEntry == null || isBlank(storedEntry.cardId)
						|| storedEntry.count <= 0 || storedEntry.count > DeckValidator.MAX_CARDS
						|| !cardIds.add(storedEntry.cardId))
					{
						return Optional.empty();
					}
					entries.add(new DeckEntry(storedEntry.cardId, storedEntry.count));
				}
				decks.add(new Deck(storedDeck.id, storedDeck.name, entries));
			}
			return Optional.of(new DeckProfile(decks, stored.selectedDeckId));
		}
		catch (JsonParseException | IllegalArgumentException | NullPointerException exception)
		{
			return Optional.empty();
		}
	}

	private static void validateDeck(Deck deck)
	{
		if (isBlank(deck.getId()) || isBlank(deck.getName()))
		{
			throw new IllegalArgumentException("Deck id and name must not be blank");
		}
		if (deck.getEntries().size() > MAX_ENTRIES_PER_DECK)
		{
			throw new IllegalArgumentException("Deck contains too many entries");
		}
		for (DeckEntry entry : deck.getEntries())
		{
			if (isBlank(entry.getCardId()) || entry.getCount() <= 0 || entry.getCount() > DeckValidator.MAX_CARDS)
			{
				throw new IllegalArgumentException("Deck contains an invalid entry");
			}
		}
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.isBlank();
	}

	private static int utf8Length(String value)
	{
		if (value.length() > MAX_JSON_BYTES)
		{
			return value.length();
		}
		return value.getBytes(StandardCharsets.UTF_8).length;
	}

	private static final class StoredProfile
	{
		private int version;
		private List<StoredDeck> decks;
		private String selectedDeckId;
	}

	private static final class StoredDeck
	{
		private String id;
		private String name;
		private List<StoredEntry> entries;
	}

	private static final class StoredEntry
	{
		private String cardId;
		private int count;
	}
}

package com.osrstcgbattles.persist;

import java.util.Objects;
import java.util.Optional;
import net.runelite.client.config.ConfigManager;

/** Stores deck state in the active RuneLite configuration profile. */
public final class DeckProfileRepository
{
	public static final String CONFIG_GROUP = "osrsTcgBattlesDecks";
	public static final String CONFIG_KEY = "profileJson";

	private final ConfigManager configManager;
	private final DeckProfileCodec codec;
	private DeckProfile current = DeckProfile.empty();

	public DeckProfileRepository(ConfigManager configManager, DeckProfileCodec codec)
	{
		this.configManager = Objects.requireNonNull(configManager, "configManager");
		this.codec = Objects.requireNonNull(codec, "codec");
	}

	public synchronized DeckProfile getCurrent()
	{
		return current;
	}

	/**
	 * Loads the active profile. Invalid JSON is ignored, leaving the last valid state untouched.
	 *
	 * @return true when stored data was present and successfully decoded
	 */
	public synchronized boolean reload()
	{
		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY);
		Optional<DeckProfile> decoded = codec.decode(json);
		if (!decoded.isPresent())
		{
			return false;
		}
		current = decoded.get();
		return true;
	}

	public synchronized void save(DeckProfile profile)
	{
		Objects.requireNonNull(profile, "profile");
		String json = codec.encode(profile);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, json);
		current = profile;
	}
}

package com.osrstcgbattles.ui;

import com.osrstcgbattles.catalog.BattleCard;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.util.Objects;
import java.util.function.IntFunction;
import javax.swing.JComponent;
import javax.swing.JList;

/** Consistent, privacy-safe card rules tooltips for battle and deck-building views. */
public final class BattleCardTooltips
{
	private BattleCardTooltips()
	{
	}

	public static void install(JComponent component, BattleCard card)
	{
		component.setToolTipText(format(card));
	}

	public static String format(BattleCard card)
	{
		Objects.requireNonNull(card, "card");
		String stats = card.getCategory().name().equals("UNIT")
			? card.getAttack() + " attack  |  " + card.getHealth() + " health  |  " : "";
		String tags = card.getTags().isEmpty() ? "" : "<br><font color='#9f9685'>"
			+ escapeHtml(String.join("  /  ", card.getTags())) + "</font>";
		return "<html><div style='width:260px;padding:4px'><b><font color='#f1d58a'>"
			+ escapeHtml(card.getDisplayName()) + "</font></b><br><font color='#b9ad98'>"
			+ escapeHtml(card.getRarity().name()) + " " + escapeHtml(card.getCategory().name())
			+ "  |  " + stats + card.getManaCost() + " mana</font><hr>"
			+ escapeHtml(card.getRulesText()) + tags + "</div></html>";
	}

	public static void install(JList<?> list, IntFunction<BattleCard> cardAtIndex)
	{
		Objects.requireNonNull(list, "list");
		Objects.requireNonNull(cardAtIndex, "cardAtIndex");
		list.addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent event)
			{
				int index = list.locationToIndex(event.getPoint());
				Rectangle bounds = index < 0 ? null : list.getCellBounds(index, index);
				BattleCard card = bounds != null && bounds.contains(event.getPoint()) ? cardAtIndex.apply(index) : null;
				list.setToolTipText(card == null ? null : format(card));
			}
		});
		list.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseExited(MouseEvent event)
			{
				list.setToolTipText(null);
			}
		});
	}

	static String escapeHtml(String value)
	{
		return value == null ? "" : value.replace("&", "&amp;").replace("<", "&lt;")
			.replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;");
	}
}

