package com.osrstcgbattles.ui;

import com.osrstcgbattles.deck.DeckValidationResult;
import java.util.Objects;

/** One readiness result shared by the builder, sidebar, and match setup. */
public final class DeckReadiness
{
	public enum Status
	{
		BUILT_IN_STARTER,
		READY,
		OWNERSHIP_PENDING,
		INVALID
	}

	private final Status status;
	private final DeckValidationResult validation;

	public DeckReadiness(Status status, DeckValidationResult validation)
	{
		this.status = Objects.requireNonNull(status, "status");
		this.validation = Objects.requireNonNull(validation, "validation");
	}

	public Status getStatus()
	{
		return status;
	}

	public DeckValidationResult getValidation()
	{
		return validation;
	}

	public boolean isPlayable()
	{
		return status == Status.BUILT_IN_STARTER || status == Status.READY;
	}

	public String getLabel()
	{
		switch (status)
		{
			case BUILT_IN_STARTER:
				return "Built-in starter - ready";
			case READY:
				return "Ready to play";
			case OWNERSHIP_PENDING:
				return "Ownership check pending";
			default:
				int errors = validation.getErrors().size();
				return errors + (errors == 1 ? " deck error" : " deck errors");
		}
	}
}

package com.osrstcgbattles.ui;

import com.osrstcgbattles.art.CardArtProvider;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.CommandResult;
import com.osrstcgbattles.engine.ConcedeCommand;
import com.osrstcgbattles.engine.DuelscapeEngine;
import com.osrstcgbattles.engine.MatchState;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.match.MatchView;
import com.osrstcgbattles.ui.board.BattleBoardView;
import com.osrstcgbattles.ui.board.BattlePlayerIdentity;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.lang.reflect.InvocationTargetException;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import javax.swing.JFrame;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;

/**
 * Hot-seat battle window. Holds one {@link BattleBoardView} per seat in a {@link CardLayout} and
 * only ever shows the currently active seat's view, so the inactive player's hand is never on
 * screen -- there is no shared view whose contents could momentarily leak the wrong hand.
 */
public final class LocalBattleWindow
{
	private static final int DEFAULT_WIDTH = 1100;
	private static final int DEFAULT_HEIGHT = 750;
	private static final int MIN_WIDTH = 760;
	private static final int MIN_HEIGHT = 560;

	private final DuelscapeEngine engine;
	private MatchState state;
	private final Map<PlayerId, BattleBoardView> views = new EnumMap<>(PlayerId.class);
	private JFrame frame;
	private JPanel seatPanel;
	private CardLayout seatLayout;
	private PlayerId shownSeat = PlayerId.PLAYER_ONE;
	private boolean concedeConfirmationOpen;

	public LocalBattleWindow(DuelscapeEngine engine, MatchState initialState, BattleCardCatalog catalog,
		CardArtProvider art)
	{
		this.engine = Objects.requireNonNull(engine, "engine");
		this.state = Objects.requireNonNull(initialState, "initialState");
		Objects.requireNonNull(catalog, "catalog");
		Objects.requireNonNull(art, "art");
		runOnEdtAndWait(() -> initialize(catalog, art));
	}

	public void showWindow()
	{
		SwingUtilities.invokeLater(() -> {
			render();
			frame.setVisible(true);
			frame.toFront();
		});
	}

	public void dispose()
	{
		SwingUtilities.invokeLater(() -> frame.dispose());
	}

	private void initialize(BattleCardCatalog catalog, CardArtProvider art)
	{
		frame = new JFrame("Duelscape TCG Local Battle");
		frame.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		frame.setMinimumSize(new Dimension(MIN_WIDTH, MIN_HEIGHT));
		frame.setSize(DEFAULT_WIDTH, DEFAULT_HEIGHT);
		frame.setLocationByPlatform(true);

		seatLayout = new CardLayout();
		seatPanel = new JPanel(seatLayout);
		BattlePlayerIdentity playerOne = new BattlePlayerIdentity("Player 1", null, "Player 1");
		BattlePlayerIdentity playerTwo = new BattlePlayerIdentity("Player 2", null, "Player 2");
		for (PlayerId player : PlayerId.values())
		{
			BattleBoardView view = new BattleBoardView(player, catalog, art);
			view.setPlayerIdentities(playerOne, playerTwo);
			view.setCommandListener(command -> onCommand(player, command));
			view.setCloseListener(this::dispose);
			views.put(player, view);
			seatPanel.add(view.getComponent(), player.name());
		}
		frame.setContentPane(seatPanel);
		render();
	}

	private void onCommand(PlayerId seat, Command command)
	{
		if (command instanceof ConcedeCommand)
		{
			if (state == null || state.getStatus() == MatchStatus.COMPLETE || concedeConfirmationOpen) return;
			concedeConfirmationOpen = true;
			int choice;
			try
			{
				choice = JOptionPane.showConfirmDialog(frame,
					BattleUiFormatters.player(seat) + " will lose the match. Concede now?",
					"Concede match", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
			}
			finally
			{
				concedeConfirmationOpen = false;
			}
			if (choice != JOptionPane.OK_OPTION)
			{
				return;
			}
		}
		execute(command);
	}

	private void execute(Command command)
	{
		CommandResult result = engine.execute(state, command);
		state = result.getState();
		String banner = result.isAccepted() ? " "
			: "Command rejected: " + result.getRejectionReason().map(LocalBattleWindow::readable).orElse("Unknown");
		for (BattleBoardView view : views.values())
		{
			view.setBanner(banner);
		}
		render();
	}

	private void render()
	{
		for (Map.Entry<PlayerId, BattleBoardView> entry : views.entrySet())
		{
			entry.getValue().setState(MatchView.forPlayer(state, entry.getKey()));
		}

		// render() runs last on every path that can end a match (execute(), showWindow(), the
		// constructor's initial render), so setting the summary banner here -- after execute()'s
		// rejection/accepted banner -- is what stops it from being clobbered: nothing runs after
		// render() to overwrite it, and every render() call re-asserts the summary for as long as
		// the match stays complete.
		if (state.getStatus() == MatchStatus.COMPLETE)
		{
			String summary = matchSummary();
			for (BattleBoardView view : views.values())
			{
				view.setBanner(summary);
			}
		}

		state.getActivePlayer().ifPresent(active -> shownSeat = active);
		for (Map.Entry<PlayerId, BattleBoardView> entry : views.entrySet())
		{
			entry.getValue().setControlsEnabled(entry.getKey() == shownSeat);
		}
		seatLayout.show(seatPanel, shownSeat.name());
	}

	private String matchSummary()
	{
		String outcome = state.getWinner()
			.map(winner -> BattleUiFormatters.player(winner) + " wins")
			.orElse("Draw");
		return "Match complete: " + outcome + " | Turns played: " + state.getTurnNumber();
	}

	private static String readable(Object value)
	{
		return value.toString().toLowerCase(Locale.ROOT).replace('_', ' ');
	}

	private static void runOnEdtAndWait(Runnable action)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			action.run();
			return;
		}
		try
		{
			SwingUtilities.invokeAndWait(action);
		}
		catch (InterruptedException ex)
		{
			throw new IllegalStateException("Interrupted while creating local battle", ex);
		}
		catch (InvocationTargetException ex)
		{
			throw new IllegalStateException("Could not create local battle", ex.getCause());
		}
	}
}

package com.osrstcgbattles.ui;

import com.osrstcgbattles.art.CardArtProvider;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.ConcedeCommand;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.match.MatchView;
import com.osrstcgbattles.online.OnlineMatchCoordinator;
import com.osrstcgbattles.online.OnlineMatchSnapshot;
import com.osrstcgbattles.ui.board.BattleBoardView;
import com.osrstcgbattles.ui.board.BattlePlayerIdentity;
import java.awt.Dimension;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.lang.reflect.InvocationTargetException;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.JFrame;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;

/** Battle window backed exclusively by server-projected match views. */
public final class OnlineBattleWindow
{
	private final OnlineMatchCoordinator coordinator;
	private final Runnable closeAction;
	private final OnlineMatchCoordinator.Listener listener;
	private final AtomicBoolean disposed = new AtomicBoolean();
	private volatile OnlineMatchSnapshot snapshot;
	private JFrame frame;
	private BattleBoardView view;
	private boolean concedeConfirmationOpen;
	private boolean closeAfterCompletion;

	public OnlineBattleWindow(OnlineMatchCoordinator coordinator, BattleCardCatalog catalog,
		CardArtProvider art, Runnable closeAction)
	{
		this.coordinator = Objects.requireNonNull(coordinator, "coordinator");
		this.snapshot = coordinator.snapshot();
		this.closeAction = Objects.requireNonNull(closeAction, "closeAction");
		this.listener = updated -> SwingUtilities.invokeLater(() -> accept(updated));
		coordinator.addListener(listener);
		try
		{
			runOnEdtAndWait(() -> initialize(catalog, art));
		}
		catch (RuntimeException exception)
		{
			coordinator.removeListener(listener);
			throw exception;
		}
	}

	public void showWindow()
	{
		SwingUtilities.invokeLater(() -> {
			if (disposed.get()) return;
			render();
			frame.setVisible(true);
			frame.toFront();
		});
	}

	public void dispose()
	{
		if (!disposed.compareAndSet(false, true)) return;
		coordinator.removeListener(listener);
		SwingUtilities.invokeLater(() -> frame.dispose());
	}

	private void initialize(BattleCardCatalog catalog, CardArtProvider art)
	{
		frame = new JFrame("Duelscape TCG Online Battle");
		frame.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
		frame.setMinimumSize(new Dimension(760, 560));
		frame.setSize(1100, 750);
		frame.setLocationByPlatform(true);
		frame.addWindowListener(new WindowAdapter()
		{
			@Override public void windowClosing(WindowEvent event) { closeFromWindow(); }
			@Override public void windowClosed(WindowEvent event) { dispose(); }
		});
		PlayerId localSeat = snapshot.getLocalSeat();
		view = new BattleBoardView(localSeat, catalog, art);
		BattlePlayerIdentity local = new BattlePlayerIdentity("You", null, "You");
		BattlePlayerIdentity opponent = new BattlePlayerIdentity(snapshot.getOpponentDisplayName(), null, "Opponent");
		view.setPlayerIdentities(localSeat == PlayerId.PLAYER_ONE ? local : opponent,
			localSeat == PlayerId.PLAYER_ONE ? opponent : local);
		view.setCommandListener(this::submit);
		view.setCloseListener(this::finishClose);
		frame.setContentPane(view.getComponent());
		render();
	}

	private void accept(OnlineMatchSnapshot updated)
	{
		if (disposed.get()) return;
		snapshot = updated;
		render();
		if (closeAfterCompletion && (updated.getStatus() == OnlineMatchSnapshot.Status.COMPLETE
			|| updated.getStatus() == OnlineMatchSnapshot.Status.ERROR)) finishClose();
	}

	private void render()
	{
		OnlineMatchSnapshot current = snapshot;
		MatchView state = current.getView();
		if (state != null) view.setState(state);
		boolean activeTurn = current.getStatus() == OnlineMatchSnapshot.Status.ACTIVE && state != null
			&& state.getStatus() == MatchStatus.ACTIVE
			&& state.getActivePlayer().filter(current.getLocalSeat()::equals).isPresent();
		view.setControlsEnabled(activeTurn);
		view.setBanner(current.getMessage());
	}

	private void submit(Command command)
	{
		if (command instanceof ConcedeCommand)
		{
			if (concedeConfirmationOpen) return;
			concedeConfirmationOpen = true;
			int choice;
			try
			{
				choice = JOptionPane.showConfirmDialog(frame, "Concede this online match?", "Concede match",
					JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
			}
			finally { concedeConfirmationOpen = false; }
			if (choice != JOptionPane.OK_OPTION) return;
		}
		if (!coordinator.submit(command)) view.setBanner("Unable to send command");
	}

	private void closeFromWindow()
	{
		if (snapshot.getStatus() != OnlineMatchSnapshot.Status.COMPLETE
			&& snapshot.getStatus() != OnlineMatchSnapshot.Status.ERROR
			&& JOptionPane.showConfirmDialog(frame, "Leave this online battle?", "Close online battle",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) != JOptionPane.OK_OPTION) return;
		if (snapshot.getStatus() == OnlineMatchSnapshot.Status.ACTIVE
			|| snapshot.getStatus() == OnlineMatchSnapshot.Status.WAITING_STATE)
		{
			if (!coordinator.concede())
			{
				view.setBanner("Unable to leave while a command is pending");
				return;
			}
			closeAfterCompletion = true;
			view.setBanner("Conceding match...");
			return;
		}
		finishClose();
	}

	private void finishClose()
	{
		if (!disposed.compareAndSet(false, true)) return;
		coordinator.removeListener(listener);
		frame.dispose();
		closeAction.run();
	}

	private static void runOnEdtAndWait(Runnable action)
	{
		if (SwingUtilities.isEventDispatchThread()) { action.run(); return; }
		try { SwingUtilities.invokeAndWait(action); }
		catch (InterruptedException exception)
		{
			throw new IllegalStateException("Interrupted while creating online battle", exception);
		}
		catch (InvocationTargetException exception)
		{
			throw new IllegalStateException("Could not create online battle", exception.getCause());
		}
	}
}

