/**
 * State-in/command-out adapter for the cohesive battle surface. Engine and network ownership stay
 * entirely with the hosting window.
 */
public final class BattleBoardView
{
	static final String NO_LEGAL_TARGETS_MESSAGE = "There are no legal targets for this card.";
	private static final String CANCEL_ACTION_KEY = "osrstcgbattles.cancelSelection";

	private final PlayerId localSeat;
	private final BattleInteraction interaction;
	private final BattleBoardPanel root;
	private final BoardPanel boardPanel;
	private final HandPanel handPanel;
	private final HandPanel opponentHandPanel;
	private final TurnButton endTurnButton;
	private final JButton concedeButton;
	private final JButton keepHandButton;

	private Consumer<Command> commandListener = command -> { };
	private MatchView state;
	private boolean handHidden;
	private boolean controlsEnabled = true;
	private String banner = " ";
	private boolean hasPreviousState;
	private String draggedAttackerId;

	public BattleBoardView(PlayerId localSeat, BattleCardCatalog catalog, CardArtProvider art)
	{
		this.localSeat = Objects.requireNonNull(localSeat, "localSeat");
		Objects.requireNonNull(catalog, "catalog");
		Objects.requireNonNull(art, "art");
		interaction = new BattleInteraction(localSeat);
		root = new BattleBoardPanel(catalog, art);
		boardPanel = root.getBoardPanel();
		handPanel = root.getLocalHand();
		opponentHandPanel = root.getOpponentHand();
		endTurnButton = root.getEndTurnButton();
		concedeButton = root.getConcedeButton();
		keepHandButton = root.getKeepHandButton();

		endTurnButton.addActionListener(event -> endTurn());
		root.getOpponentHero().setClickListener(this::onEnemyHeroClicked);
		concedeButton.addActionListener(event -> concede());
		keepHandButton.addActionListener(event -> keepHand());
		boardPanel.setUnitClickListener(this::onUnitClicked);
		boardPanel.setUnitDragListener(new BoardPanel.UnitDragListener()
		{
			@Override
			public void onUnitDragged(String instanceId, Point battleSurfacePoint)
			{
				BattleBoardView.this.onUnitDragged(instanceId, battleSurfacePoint);
			}

			@Override
			public void onUnitDropped(String instanceId, Point battleSurfacePoint)
			{
				BattleBoardView.this.onUnitDropped(instanceId, battleSurfacePoint);
			}
		});
		boardPanel.setCancelListener(this::cancelSelection);
		handPanel.setCardClickListener(this::onHandCardClicked);
		handPanel.setCardDragListener(new HandPanel.CardDragListener()
		{
			@Override
			public void onCardDragged(String cardId, Point boardPoint)
			{
				boolean valid = controlsEnabled && state != null && state.getPhase() == MatchPhase.PLAY
					&& boardPanel.getBounds().contains(boardPoint) && interaction.isHandCardPlayable(cardId);
				root.showCardDrag(cardId, boardPoint, valid);
			}

			@Override
			public void onCardDropped(String cardId, Point boardPoint)
			{
				root.hideCardDrag();
				onHandCardDropped(cardId, boardPoint);
			}
		});
		handPanel.setCancelListener(this::cancelSelection);
		opponentHandPanel.setCancelListener(this::cancelSelection);
		installCancelKeyBinding();
	}

	public JComponent getComponent()
	{
		return root;
	}

	/** Maps engine-seat identities onto this view's local and opponent hero positions. */
	public void setPlayerIdentities(BattlePlayerIdentity playerOne, BattlePlayerIdentity playerTwo)
	{
		BattlePlayerIdentity local = shownLocalIdentity(localSeat, playerOne, playerTwo);
		BattlePlayerIdentity opponent = shownOpponentIdentity(localSeat, playerOne, playerTwo);
		root.getLocalHero().setIdentity(local.getDisplayName(), local.getAvatar());
		root.getOpponentHero().setIdentity(opponent.getDisplayName(), opponent.getAvatar());
	}

	static BattlePlayerIdentity shownLocalIdentity(PlayerId localSeat, BattlePlayerIdentity playerOne,
		BattlePlayerIdentity playerTwo)
	{
		Objects.requireNonNull(localSeat, "localSeat");
		return localSeat == PlayerId.PLAYER_ONE
			? Objects.requireNonNull(playerOne, "playerOne") : Objects.requireNonNull(playerTwo, "playerTwo");
	}

	static BattlePlayerIdentity shownOpponentIdentity(PlayerId localSeat, BattlePlayerIdentity playerOne,
		BattlePlayerIdentity playerTwo)
	{
		Objects.requireNonNull(localSeat, "localSeat");
		return localSeat == PlayerId.PLAYER_ONE
			? Objects.requireNonNull(playerTwo, "playerTwo") : Objects.requireNonNull(playerOne, "playerOne");
	}

	/** Adopts a new authoritative match state and drops any half-finished local selection. */
	public void setState(MatchView state)
	{
		clearUnitDrag();
		MatchView next = Objects.requireNonNull(state, "state");
		if (next.getViewer() != localSeat) throw new IllegalArgumentException("match view is for a different player");
		recordStateChanges(this.state, next);
		PlayerId previousActive = this.state == null ? null : this.state.getActivePlayer().orElse(null);
		if (TurnBanner.shouldShow(hasPreviousState,
			this.state == null ? null : this.state.getStatus(),
			this.state == null ? null : this.state.getPhase(), previousActive,
			next.getStatus(), next.getPhase(), next.getActivePlayer().orElse(null)))
		{
			root.getTurnBanner().showTurn(next.getActivePlayer().filter(localSeat::equals).isPresent());
		}
		this.state = next;
		hasPreviousState = true;
		if (state.getStatus() == MatchStatus.COMPLETE)
		{
			root.getTurnBanner().hideBanner();
			root.getResultOverlay().showResult(localSeat, state.getWinner().orElse(null), state.getTurnNumber());
		}
		else
		{
			if (state.getPhase() == MatchPhase.MULLIGAN) root.getTurnBanner().hideBanner();
			root.getResultOverlay().setVisible(false);
		}
		interaction.update(state);
		boardPanel.setState(state.getBoard(), localSeat);
		refreshHand();
		refreshHighlighting();
		refreshHud();
		refreshControls();
	}

	public void setBanner(String message)
	{
		banner = message == null ? " " : message;
		refreshStatus();
	}

	public void setHandHidden(boolean hidden)
	{
		handHidden = hidden;
		refreshHand();
	}

	public void setCommandListener(Consumer<Command> listener)
	{
		commandListener = listener == null ? command -> { } : listener;
	}

	public void setCloseListener(Runnable listener)
	{
		root.getResultOverlay().setCloseListener(listener);
	}

	public void setControlsEnabled(boolean enabled)
	{
		controlsEnabled = enabled;
		if (!enabled) clearUnitDrag();
		refreshHighlighting();
	}

	void endTurn()
	{
		if (!controlsEnabled || state == null || state.getPhase() != MatchPhase.PLAY
			|| !state.getActivePlayer().filter(localSeat::equals).isPresent())
		{
			return;
		}
		emit(new EndTurnCommand(localSeat));
	}

	void concede()
	{
		// Concede remains independent of turn controls so a stalled opponent cannot trap this seat.
		if (state != null && state.getStatus() == MatchStatus.ACTIVE)
		{
			emit(new ConcedeCommand(localSeat));
		}
	}

	void keepHand()
	{
		if (controlsEnabled)
		{
			emit(new FinishMulliganCommand(localSeat));
		}
	}

	void onUnitClicked(String instanceId)
	{
		if (!controlsEnabled)
		{
			return;
		}
		Optional<Command> command = interaction.clickUnit(instanceId);
		if (command.isPresent())
		{
			emit(command.get());
		}
		else
		{
			refreshHighlighting();
		}
	}

	void onEnemyHeroClicked()
	{
		if (controlsEnabled)
		{
			interaction.clickEnemyHero().ifPresent(this::emit);
		}
	}

	private void onUnitDragged(String instanceId, Point battleSurfacePoint)
	{
		if (!controlsEnabled || state == null || battleSurfacePoint == null) return;
		if (!instanceId.equals(draggedAttackerId))
		{
			interaction.cancel();
			interaction.clickUnit(instanceId);
			if (!interaction.getSelectedAttackerId().filter(instanceId::equals).isPresent()) return;
			draggedAttackerId = instanceId;
			refreshHighlighting();
		}
		BoardUnit attacker = boardUnit(instanceId);
		if (attacker == null) return;
		root.showCardDrag(attacker.getDefinition().getId(), battleSurfacePoint,
			legalUnitAt(battleSurfacePoint) != null || legalHeroAt(battleSurfacePoint));
	}

	private void onUnitDropped(String instanceId, Point battleSurfacePoint)
	{
		root.hideCardDrag();
		if (!controlsEnabled || state == null || !instanceId.equals(draggedAttackerId)
			|| !interaction.getSelectedAttackerId().filter(instanceId::equals).isPresent())
		{
			clearUnitDrag();
			return;
		}
		String target = legalUnitAt(battleSurfacePoint);
		boolean hero = target == null && legalHeroAt(battleSurfacePoint);
		draggedAttackerId = null;
		Optional<Command> command = target != null ? interaction.clickUnit(target)
			: hero ? interaction.clickEnemyHero() : Optional.empty();
		if (command.isPresent()) emit(command.get());
		else cancelSelection();
	}

	private String legalUnitAt(Point battleSurfacePoint)
	{
		if (battleSurfacePoint == null) return null;
		Point boardPoint = SwingUtilities.convertPoint(root, battleSurfacePoint, boardPanel);
		String target = boardPanel.unitAt(boardPoint);
		if (target == null) return null;
		for (BoardUnit unit : interaction.targetableUnits())
		{
			if (unit.getInstanceId().equals(target)) return target;
		}
		return null;
	}

	private boolean legalHeroAt(Point battleSurfacePoint)
	{
		return battleSurfacePoint != null && root.getOpponentHero().getBounds().contains(battleSurfacePoint)
			&& interaction.isEnemyHeroTargetable();
	}

	private BoardUnit boardUnit(String instanceId)
	{
		if (state == null) return null;
		for (PlayerId player : PlayerId.values())
		{
			for (BoardUnit unit : state.getBoard().getUnits(player))
			{
				if (unit.getInstanceId().equals(instanceId)) return unit;
			}
		}
		return null;
	}

	private void clearUnitDrag()
	{
		draggedAttackerId = null;
		root.hideCardDrag();
	}

	void onHandCardClicked(String cardId)
	{
		if (!controlsEnabled || state == null)
		{
			return;
		}
		if (state.getPhase() == MatchPhase.MULLIGAN)
		{
			interaction.clickHandCardForMulligan(cardId).ifPresent(this::emit);
			return;
		}
		selectCardForPlay(cardId);
	}

	void onHandCardDropped(String cardId, Point boardPoint)
	{
		if (!controlsEnabled || state == null || state.getPhase() != MatchPhase.PLAY
			|| boardPoint == null || !boardPanel.getBounds().contains(boardPoint))
		{
			return;
		}
		selectCardForPlay(cardId);
	}

	private void selectCardForPlay(String cardId)
	{
		if (interaction.selectHandCard(cardId))
		{
			Optional<Command> command = interaction.commit();
			if (command.isPresent())
			{
				emit(command.get());
				return;
			}
			cancelIfNoLegalTargets();
		}
		refreshHighlighting();
	}

	void cancelSelection()
	{
		interaction.cancel();
		refreshHighlighting();
	}

	private void cancelIfNoLegalTargets()
	{
		if (interaction.isTargetPending() && interaction.targetableUnits().isEmpty())
		{
			interaction.cancel();
			setBanner(NO_LEGAL_TARGETS_MESSAGE);
		}
	}

	private void installCancelKeyBinding()
	{
		root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
			.put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), CANCEL_ACTION_KEY);
		root.getActionMap().put(CANCEL_ACTION_KEY, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent event)
			{
				cancelSelection();
			}
		});
	}

	private void emit(Command command)
	{
		recordCommand(command);
		interaction.cancel();
		refreshHighlighting();
		commandListener.accept(command);
	}

	private void recordCommand(Command command)
	{
		if (command instanceof AttackCommand)
		{
			AttackCommand attack = (AttackCommand) command;
			BoardUnit attacker = boardUnit(attack.getAttackerInstanceId());
			String attackerName = attacker == null ? "Unit" : attacker.getDefinition().getName();
			String targetName = attack.getTargetInstanceId().map(id -> {
				BoardUnit target = boardUnit(id);
				return target == null ? "enemy unit" : target.getDefinition().getName();
			}).orElse("enemy hero");
			root.appendBattleLog("You attacked " + targetName + " with " + attackerName + ".");
		}
		else if (command instanceof PlayCardCommand && state != null)
		{
			String cardId = ((PlayCardCommand) command).getCardId();
			for (Card card : state.getLocalHand())
			{
				if (card.getId().equals(cardId) && card instanceof SpecialCard)
				{
					root.appendBattleLog("You played " + card.getName() + ".");
					break;
				}
			}
		}
		else if (command instanceof ConcedeCommand)
		{
			root.appendBattleLog("You conceded the battle.");
		}
	}

	private void recordStateChanges(MatchView previous, MatchView next)
	{
		if (previous == null)
		{
			root.appendBattleLog("Opening hands drawn.");
			return;
		}
		if (previous.getPhase() == MatchPhase.MULLIGAN && next.getPhase() == MatchPhase.PLAY)
		{
			root.appendBattleLog("The battle begins.");
		}
		PlayerId previousActive = previous.getActivePlayer().orElse(null);
		PlayerId nextActive = next.getActivePlayer().orElse(null);
		if (next.getPhase() == MatchPhase.PLAY && nextActive != null && nextActive != previousActive)
		{
			root.appendBattleLog("Turn " + next.getTurnNumber() + ": "
				+ (nextActive == localSeat ? "your turn." : "opponent's turn."));
		}
		for (PlayerId player : PlayerId.values())
		{
			for (BoardUnit unit : next.getBoard().getUnits(player))
			{
				if (findUnit(previous, unit.getInstanceId()) == null)
				{
					root.appendBattleLog((player == localSeat ? "You summoned " : "Opponent summoned ")
						+ unit.getDefinition().getName() + ".");
				}
			}
			for (BoardUnit unit : previous.getBoard().getUnits(player))
			{
				if (findUnit(next, unit.getInstanceId()) == null)
				{
					root.appendBattleLog(unit.getDefinition().getName() + " was defeated.");
				}
			}
			int oldHealth = previous.getPlayer(player).getHeroHealth();
			int newHealth = next.getPlayer(player).getHeroHealth();
			if (newHealth < oldHealth)
			{
				root.appendBattleLog((player == localSeat ? "You took " : "Opponent took ")
					+ (oldHealth - newHealth) + " damage.");
			}
			else if (newHealth > oldHealth)
			{
				root.appendBattleLog((player == localSeat ? "You recovered " : "Opponent recovered ")
					+ (newHealth - oldHealth) + " health.");
			}
		}
		if (previous.getStatus() != MatchStatus.COMPLETE && next.getStatus() == MatchStatus.COMPLETE)
		{
			root.appendBattleLog(next.getWinner().map(winner -> winner == localSeat ? "You won the battle."
				: "Opponent won the battle.").orElse("The battle ended in a draw."));
		}
	}

	private static BoardUnit findUnit(MatchView state, String instanceId)
	{
		for (PlayerId player : PlayerId.values())
		{
			for (BoardUnit unit : state.getBoard().getUnits(player))
			{
				if (unit.getInstanceId().equals(instanceId)) return unit;
			}
		}
		return null;
	}

	private void refreshHighlighting()
	{
		boolean mulligan = state != null && state.getPhase() == MatchPhase.MULLIGAN;
		boardPanel.setSelectableAttackers(!controlsEnabled || mulligan
			? Collections.emptyList() : interaction.selectableAttackers());
		boardPanel.setTargetable(!controlsEnabled || mulligan
			? Collections.emptyList() : interaction.targetableUnits());
		boardPanel.setSelectedAttacker(interaction.getSelectedAttackerId().orElse(null));
		boardPanel.setInteractionPending(interaction.isTargetPending()
			|| interaction.getSelectedAttackerId().isPresent());
		handPanel.setSelected(interaction.getSelectedCardId().orElse(null));
		root.setTargetPrompt(interaction.targetPrompt().orElse(null));
		refreshHandPlayability();
		refreshControls();
	}

	private void refreshHandPlayability()
	{
		if (state == null)
		{
			handPanel.setPlayableCardIds(Collections.emptySet());
			return;
		}
		HashSet<String> playable = new HashSet<>();
		boolean localTurn = controlsEnabled && state.getStatus() == MatchStatus.ACTIVE
			&& state.getActivePlayer().filter(localSeat::equals).isPresent();
		for (Card card : state.getLocalHand())
		{
			if (state.getPhase() == MatchPhase.MULLIGAN
				? localTurn && state.getPlayer(localSeat).getRemainingMulligans() > 0
				: controlsEnabled && interaction.isHandCardPlayable(card.getId()))
			{
				playable.add(card.getId());
			}
		}
		handPanel.setPlayableCardIds(playable);
	}

	private void refreshHand()
	{
		if (state == null)
		{
			return;
		}
		List<Card> hand = state.getLocalHand();
		if (handHidden)
		{
			handPanel.setFaceDownCount(hand.size());
		}
		else
		{
			handPanel.setHand(hand);
		}
		// The opponent rendering boundary is intentionally count-only.
		opponentHandPanel.setFaceDownCount(state.getPlayer(localSeat.opponent()).getHandSize());
	}

	private void refreshHud()
	{
		if (state == null)
		{
			return;
		}
		MatchView.PlayerView opponent = state.getPlayer(localSeat.opponent());
		MatchView.PlayerView local = state.getPlayer(localSeat);
		root.getOpponentHero().setStats(opponent.getHeroHealth(), opponent.getMana(), opponent.getMaximumMana());
		root.getLocalHero().setStats(local.getHeroHealth(), local.getMana(), local.getMaximumMana());
		root.getOpponentDeck().setValues(opponent.getDrawPileSize(), opponent.getFatigue());
		root.getLocalDeck().setValues(local.getDrawPileSize(), local.getFatigue());
		refreshStatus();
	}

	private void refreshStatus()
	{
		if (state == null)
		{
			root.setStatus(" ", " ", banner);
			return;
		}
		String turnNumber = state.getStatus() == MatchStatus.COMPLETE ? "Match complete"
			: "Turn " + state.getTurnNumber() + (state.getPhase() == MatchPhase.MULLIGAN ? " (mulligan)" : "");
		String turn = state.getActivePlayer().map(active -> active == localSeat ? "Your turn" : "Opponent's turn")
			.orElse("Match finished");
		root.setStatus(turnNumber, turn, banner);
	}

	private void refreshControls()
	{
		boolean mulligan = state != null && state.getPhase() == MatchPhase.MULLIGAN;
		boolean active = state != null && state.getStatus() == MatchStatus.ACTIVE;
		boolean localTurn = active && state.getActivePlayer().filter(localSeat::equals).isPresent();
		endTurnButton.setVisible(!mulligan);
		keepHandButton.setVisible(mulligan);
		boolean canEndTurn = controlsEnabled && localTurn && !mulligan;
		endTurnButton.setActionable(canEndTurn, active ? "WAITING" : "MATCH OVER");
		keepHandButton.setEnabled(controlsEnabled && localTurn && mulligan);
		concedeButton.setEnabled(active);
		boolean heroTargetable = controlsEnabled && interaction.isEnemyHeroTargetable();
		root.getOpponentHero().setTargetable(heroTargetable);
		root.getOpponentHero().setInactive(!active);
		root.getLocalHero().setInactive(!active || !localTurn);
		refreshHandPlayability();
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;

/** Hero identity/stats presentation, ready for a later supplied avatar. */
public final class BattleHeroPanel extends JPanel
{
	private final ManaDisplay manaDisplay = new ManaDisplay();
	private String identity;
	private Image avatar;
	private int health;
	private int mana;
	private int maximumMana;
	private boolean targetable;
	private boolean hovered;
	private boolean inactive;
	private Runnable clickListener = () -> { };

	public BattleHeroPanel(String identity)
	{
		setLayout(null);
		setOpaque(false);
		setIdentity(identity, null);
		add(manaDisplay);
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				if (targetable)
				{
					hovered = true;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}

			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (targetable && event.getButton() == MouseEvent.BUTTON1)
				{
					clickListener.run();
				}
			}
		};
		addMouseListener(mouse);
		manaDisplay.addMouseListener(mouse);
	}

	public void setIdentity(String identity, Image avatar)
	{
		this.identity = identity == null || identity.trim().isEmpty() ? "Player" : identity.trim();
		this.avatar = avatar;
		refreshTooltip();
		repaint();
	}

	public void setStats(int health, int mana, int maximumMana)
	{
		this.health = health;
		this.mana = mana;
		this.maximumMana = maximumMana;
		manaDisplay.setMana(mana, maximumMana);
		refreshTooltip();
		repaint();
	}

	public void setTargetable(boolean targetable)
	{
		this.targetable = targetable;
		hovered = false;
		setCursor(Cursor.getPredefinedCursor(targetable ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
		manaDisplay.setCursor(getCursor());
		refreshTooltip();
		repaint();
	}

	public void setInactive(boolean inactive)
	{
		this.inactive = inactive;
		repaint();
	}

	public void setClickListener(Runnable listener)
	{
		clickListener = listener == null ? () -> { } : listener;
	}

	private void refreshTooltip()
	{
		setToolTipText(identity + ": " + health + " health, " + mana + " of " + maximumMana + " mana"
			+ (targetable ? ". Click to attack this hero." : ""));
	}

	@Override
	public void doLayout()
	{
		int emblem = Math.max(34, getHeight() - 12);
		manaDisplay.setBounds(emblem + 18, getHeight() - 25, Math.max(50, getWidth() - emblem - 26), 18);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(health <= 0 ? new Color(48, 25, 22, 235)
				: health <= 5 ? new Color(51, 31, 22, 235) : new Color(28, 22, 16, 235));
			g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 14, 14);
			g.setColor(targetable ? (hovered ? BoardTheme.GLOW_TARGET.brighter() : BoardTheme.GLOW_TARGET)
				: health <= 0 ? BoardTheme.HEALTH.darker() : BoardTheme.GOLD.darker());
			g.setStroke(new BasicStroke(targetable ? (hovered ? 4f : 3f) : 2f));
			g.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 14, 14);
			int emblem = Math.max(34, getHeight() - 12);
			int y = (getHeight() - emblem) / 2;
			if (avatar != null)
			{
				g.drawImage(avatar, 6, y, emblem, emblem, this);
			}
			else
			{
				int seed = identity.toUpperCase().hashCode();
				g.setColor(new Color(70 + Math.floorMod(seed, 45), 55 + Math.floorMod(seed / 7, 40), 35));
				g.fillOval(6, y, emblem, emblem);
				g.setColor(BoardTheme.GOLD);
				g.drawOval(6, y, emblem, emblem);
				g.setFont(getFont().deriveFont(Font.BOLD, Math.max(14f, emblem * .38f)));
				String initials = initials(identity);
				g.drawString(initials, 6 + (emblem - g.getFontMetrics().stringWidth(initials)) / 2,
					y + (emblem + g.getFontMetrics().getAscent()) / 2 - 2);
			}
			int textX = emblem + 18;
			g.setColor(BoardTheme.TEXT);
			g.setFont(getFont().deriveFont(Font.BOLD, Math.max(11f, Math.min(14f, getHeight() * .2f))));
			int healthSize = Math.max(22, Math.min(28, getHeight() - 20));
			int healthX = getWidth() - healthSize - 22;
			String shownIdentity = fitText(g.getFontMetrics(), identity, Math.max(0, healthX - textX - 6));
			g.drawString(shownIdentity, textX, Math.max(g.getFontMetrics().getAscent() + 4, getHeight() / 3));
			g.setColor(BoardTheme.HEALTH);
			g.fillOval(healthX, 7, healthSize, healthSize);
			g.setColor(Color.WHITE);
			String value = Integer.toString(health);
			g.setFont(getFont().deriveFont(Font.BOLD, Math.max(11f, healthSize * .45f)));
			g.drawString(value, healthX + (healthSize - g.getFontMetrics().stringWidth(value)) / 2,
				7 + (healthSize - g.getFontMetrics().getHeight()) / 2 + g.getFontMetrics().getAscent());
			if (health <= 0)
			{
				g.setColor(new Color(8, 7, 5, 155));
				g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 14, 14);
				g.setColor(BoardTheme.HEALTH.brighter());
				g.drawString("DEFEATED", textX, getHeight() - 9);
			}
			else if (inactive && !targetable)
			{
				g.setColor(new Color(8, 7, 5, 75));
				g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 14, 14);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	private static String initials(String value)
	{
		String[] words = value.trim().split("\\s+");
		String first = words[0].substring(0, 1);
		return (first + (words.length > 1 ? words[words.length - 1].substring(0, 1) : "")).toUpperCase();
	}

	private static String fitText(FontMetrics metrics, String value, int width)
	{
		if (metrics.stringWidth(value) <= width) return value;
		String suffix = "...";
		int available = width - metrics.stringWidth(suffix);
		if (available <= 0) return "";
		int end = value.length();
		while (end > 0 && metrics.stringWidth(value.substring(0, end)) > available) end--;
		return value.substring(0, end) + suffix;
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.engine.AttackCommand;
import com.osrstcgbattles.engine.BoardUnit;
import com.osrstcgbattles.engine.Card;
import com.osrstcgbattles.engine.Command;
import com.osrstcgbattles.engine.DeployEffect;
import com.osrstcgbattles.engine.DuelscapeEngine;
import com.osrstcgbattles.engine.MatchPhase;
import com.osrstcgbattles.engine.MatchStatus;
import com.osrstcgbattles.engine.MulliganCommand;
import com.osrstcgbattles.engine.PlayCardCommand;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.engine.SpecialCard;
import com.osrstcgbattles.engine.UnitCard;
import com.osrstcgbattles.engine.UnitKeyword;
import com.osrstcgbattles.match.MatchView;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * Turns board clicks into engine commands. Deliberately free of Swing so the legality
 * rules that drive attacker and target highlighting can be unit-tested without a display.
 */
public final class BattleInteraction
{
	private final PlayerId localSeat;

	private MatchView state;
	private String selectedCardId;
	private String selectedAttackerId;
	private boolean targetPending;

	public BattleInteraction(PlayerId localSeat)
	{
		this.localSeat = Objects.requireNonNull(localSeat, "localSeat");
	}

	/** Adopts a new match state and drops any half-finished selection. */
	public void update(MatchView state)
	{
		this.state = Objects.requireNonNull(state, "state");
		cancel();
	}

	public void cancel()
	{
		selectedCardId = null;
		selectedAttackerId = null;
		targetPending = false;
	}

	public Optional<String> getSelectedCardId()
	{
		return Optional.ofNullable(selectedCardId);
	}

	public Optional<String> getSelectedAttackerId()
	{
		return Optional.ofNullable(selectedAttackerId);
	}

	public boolean isTargetPending()
	{
		return targetPending;
	}

	public Optional<String> targetPrompt()
	{
		Card card = selectedCardId == null ? null : findInHand(selectedCardId);
		if (!targetPending || card == null)
		{
			return Optional.empty();
		}
		DeployEffect.Target target = null;
		List<String> descriptions = new ArrayList<>();
		for (DeployEffect effect : effects(card))
		{
			if (effect.getTarget() == DeployEffect.Target.SELF) continue;
			target = effect.getTarget();
			descriptions.add(effect.getType() == DeployEffect.Type.DAMAGE
				? effect.getAmount() + " damage" : "+" + effect.getAmount() + "/+" + effect.getAmount());
		}
		if (target == null)
		{
			return Optional.empty();
		}
		String unit = target == DeployEffect.Target.ALLIED_UNIT ? "an allied unit" : "an enemy unit";
		return Optional.of("Select " + unit + " for " + String.join(" and ", descriptions));
	}

	/** True when the selected card can be played immediately without a deploy target. */
	public boolean isSelectionComplete()
	{
		if (selectedCardId == null)
		{
			return false;
		}
		return findInHand(selectedCardId) != null && !targetPending;
	}

	/** Emits the play for a selection that needs no deploy target. */
	public Optional<Command> commit()
	{
		if (!isSelectionComplete())
		{
			return Optional.empty();
		}
		return emit(new PlayCardCommand(localSeat, selectedCardId));
	}

	public boolean selectHandCard(String cardId)
	{
		cancel();
		if (!isHandCardPlayable(cardId))
		{
			return false;
		}
		Card card = findInHand(cardId);
		if (card == null)
		{
			return false;
		}
		selectedCardId = cardId;
		targetPending = requiresTarget(card);
		return true;
	}

	public List<BoardUnit> targetableUnits()
	{
		Card card = selectedCardId == null ? null : findInHand(selectedCardId);
		if (selectedAttackerId == null && (card == null || !targetPending))
		{
			return Collections.emptyList();
		}
		List<BoardUnit> targets = new ArrayList<>();
		boolean taunt = selectedAttackerId != null && state.getBoard().getUnits(localSeat.opponent()).stream()
			.anyMatch(unit -> unit.hasKeyword(UnitKeyword.TAUNT) && !unit.isStealthed());
		for (PlayerId owner : PlayerId.values())
		{
			for (BoardUnit unit : state.getBoard().getUnits(owner))
			{
				if (selectedAttackerId != null
					? owner == localSeat.opponent() && !unit.isStealthed()
						&& (!taunt || unit.hasKeyword(UnitKeyword.TAUNT))
					: isLegalTarget(card, owner) && (owner != localSeat.opponent() || !unit.isStealthed()))
				{
					targets.add(unit);
				}
			}
		}
		return Collections.unmodifiableList(targets);
	}

	public Optional<Command> clickUnit(String instanceId)
	{
		if (!canAct() || state.getPhase() != MatchPhase.PLAY || instanceId == null)
		{
			return Optional.empty();
		}
		if (targetPending)
		{
			if (contains(targetableUnits(), instanceId))
			{
				return emit(new PlayCardCommand(localSeat, selectedCardId, instanceId));
			}
			return Optional.empty();
		}

		BoardUnit unit = findOnBoard(instanceId);
		if (unit == null)
		{
			return Optional.empty();
		}
		if (isOwnedBy(unit, localSeat))
		{
			if (unit.isReady())
			{
				selectedCardId = null;
				targetPending = false;
				selectedAttackerId = instanceId.equals(selectedAttackerId) ? null : instanceId;
			}
			return Optional.empty();
		}
		if (selectedAttackerId != null && contains(targetableUnits(), instanceId))
		{
			return emit(new AttackCommand(localSeat, selectedAttackerId, instanceId));
		}
		return Optional.empty();
	}

	public Optional<Command> clickEnemyHero()
	{
		if (!isEnemyHeroTargetable())
		{
			return Optional.empty();
		}
		return emit(new AttackCommand(localSeat, selectedAttackerId));
	}

	public boolean isEnemyHeroTargetable()
	{
		if (!canAct() || state.getPhase() != MatchPhase.PLAY || selectedAttackerId == null)
		{
			return false;
		}
		if (!state.getBoard().getUnits(localSeat.opponent()).isEmpty())
		{
			return false;
		}
		BoardUnit attacker = findOnBoard(selectedAttackerId);
		return attacker != null && attacker.isReady() && !attacker.isRushRestricted()
			&& isOwnedBy(attacker, localSeat);
	}

	/** Mirrors only the engine's inexpensive, target-independent checks for starting a play. */
	public boolean isHandCardPlayable(String cardId)
	{
		if (!canAct() || state.getPhase() != MatchPhase.PLAY)
		{
			return false;
		}
		Card card = findInHand(cardId);
		if (card == null || state.getPlayer(localSeat).getMana() < card.getManaCost())
		{
			return false;
		}
		if (card instanceof UnitCard
			&& state.getBoard().getUnits(localSeat).size() >= DuelscapeEngine.BATTLEFIELD_LIMIT)
		{
			return false;
		}
		if (card instanceof UnitCard && ((UnitCard) card).hasKeyword(UnitKeyword.NEX_ASCENSION)
			&& !DuelscapeEngine.hasNexCommanders(state.getBoard(), localSeat)) return false;
		if (!requiresTarget(card))
		{
			return true;
		}
		for (PlayerId owner : PlayerId.values())
		{
			if (isLegalTarget(card, owner) && state.getBoard().getUnits(owner).stream()
				.anyMatch(unit -> owner != localSeat.opponent() || !unit.isStealthed()))
			{
				return true;
			}
		}
		return false;
	}

	public List<BoardUnit> selectableAttackers()
	{
		if (!canAct() || state.getPhase() != MatchPhase.PLAY || selectedCardId != null)
		{
			return Collections.emptyList();
		}
		List<BoardUnit> attackers = new ArrayList<>();
		for (BoardUnit unit : state.getBoard().getUnits(localSeat))
		{
			if (unit.isReady())
			{
				attackers.add(unit);
			}
		}
		return Collections.unmodifiableList(attackers);
	}

	/** Mulligan phase reuses the same hand tiles: one click replaces one card. */
	public Optional<Command> clickHandCardForMulligan(String cardId)
	{
		if (!canAct() || state.getPhase() != MatchPhase.MULLIGAN || findInHand(cardId) == null
			|| state.getPlayer(localSeat).getRemainingMulligans() <= 0)
		{
			return Optional.empty();
		}
		return Optional.of(new MulliganCommand(localSeat, cardId));
	}

	private Optional<Command> emit(Command command)
	{
		cancel();
		return Optional.of(command);
	}

	private boolean canAct()
	{
		return state != null
			&& state.getStatus() == MatchStatus.ACTIVE
			&& state.getActivePlayer().filter(localSeat::equals).isPresent();
	}

	private Card findInHand(String cardId)
	{
		if (cardId == null || state == null)
		{
			return null;
		}
		for (Card card : state.getLocalHand())
		{
			if (card.getId().equals(cardId))
			{
				return card;
			}
		}
		return null;
	}

	private BoardUnit findOnBoard(String instanceId)
	{
		for (PlayerId owner : PlayerId.values())
		{
			for (BoardUnit unit : state.getBoard().getUnits(owner))
			{
				if (unit.getInstanceId().equals(instanceId))
				{
					return unit;
				}
			}
		}
		return null;
	}

	private boolean isOwnedBy(BoardUnit unit, PlayerId owner)
	{
		return state.getBoard().getUnits(owner).contains(unit);
	}

	private static boolean contains(List<BoardUnit> units, String instanceId)
	{
		for (BoardUnit unit : units)
		{
			if (unit.getInstanceId().equals(instanceId))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isLegalTarget(Card card, PlayerId owner)
	{
		for (DeployEffect effect : effects(card))
		{
			if (effect.getTarget() == DeployEffect.Target.ALLIED_UNIT && owner != localSeat)
			{
				return false;
			}
			if (effect.getTarget() == DeployEffect.Target.ENEMY_UNIT && owner != localSeat.opponent())
			{
				return false;
			}
		}
		return true;
	}

	private static boolean requiresTarget(Card card)
	{
		for (DeployEffect effect : effects(card))
		{
			if (effect.getTarget() == DeployEffect.Target.ALLIED_UNIT
				|| effect.getTarget() == DeployEffect.Target.ENEMY_UNIT)
			{
				return true;
			}
		}
		return false;
	}

	private static List<DeployEffect> effects(Card card)
	{
		if (card instanceof UnitCard)
		{
			return ((UnitCard) card).getDeployEffects();
		}
		if (card instanceof SpecialCard)
		{
			return ((SpecialCard) card).getDeployEffects();
		}
		return Collections.emptyList();
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;

/** Compact in-board history of public battle events. */
final class BattleLogPanel extends JPanel
{
	private static final int MAX_ENTRIES = 80;
	private final JTextArea text = new JTextArea();
	private int entries;

	BattleLogPanel()
	{
		setLayout(new BorderLayout());
		setBackground(new Color(28, 21, 15, 245));
		setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BoardTheme.GOLD.darker()),
			BorderFactory.createEmptyBorder(4, 4, 4, 4)));
		text.setEditable(false);
		text.setFocusable(false);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setForeground(BoardTheme.TEXT);
		text.setBackground(new Color(28, 21, 15));
		text.setFont(text.getFont().deriveFont(10f));
		JScrollPane scroll = new JScrollPane(text);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(12);
		add(scroll, BorderLayout.CENTER);
	}

	void append(String entry)
	{
		if (entry == null || entry.trim().isEmpty()) return;
		if (entries >= MAX_ENTRIES)
		{
			String current = text.getText();
			int newline = current.indexOf('\n');
			text.setText(newline < 0 ? "" : current.substring(newline + 1));
			entries--;
		}
		if (entries > 0) text.append("\n");
		text.append("• " + entry.trim());
		entries++;
		text.setCaretPosition(text.getDocument().getLength());
	}

	String text()
	{
		return text.getText();
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.Image;

/** Immutable identity rendered for one engine seat. */
public final class BattlePlayerIdentity
{
	private final String displayName;
	private final Image avatar;

	public BattlePlayerIdentity(String displayName, Image avatar, String fallbackLabel)
	{
		this.displayName = normalize(displayName, fallbackLabel);
		this.avatar = avatar;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public Image getAvatar()
	{
		return avatar;
	}

	public BattlePlayerIdentity withAvatar(Image avatar)
	{
		return new BattlePlayerIdentity(displayName, avatar, displayName);
	}

	static String normalize(String displayName, String fallbackLabel)
	{
		if (displayName != null && !displayName.trim().isEmpty())
		{
			return displayName.trim();
		}
		return fallbackLabel == null || fallbackLabel.trim().isEmpty() ? "Player" : fallbackLabel.trim();
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.engine.PlayerId;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.SwingConstants;

/** Terminal match presentation which dims and blocks the board until it is closed. */
final class BattleResultOverlay extends JComponent
{
	private final JButton closeButton = new JButton("Close");
	private String title = "DRAW";
	private String finalLine = "The match ended in a draw.";

	BattleResultOverlay()
	{
		setLayout(null);
		setOpaque(false);
		setVisible(false);
		addMouseListener(new MouseAdapter() { });
		closeButton.setForeground(BoardTheme.TEXT);
		closeButton.setBackground(new Color(64, 48, 31));
		closeButton.setFocusPainted(false);
		closeButton.setHorizontalAlignment(SwingConstants.CENTER);
		closeButton.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BoardTheme.GOLD.darker()),
			BorderFactory.createEmptyBorder(4, 18, 4, 18)));
		add(closeButton);
	}

	void setCloseListener(Runnable listener)
	{
		for (java.awt.event.ActionListener existing : closeButton.getActionListeners())
		{
			closeButton.removeActionListener(existing);
		}
		Runnable action = listener == null ? () -> { } : listener;
		closeButton.addActionListener(event -> action.run());
	}

	void showResult(PlayerId localSeat, PlayerId winner, int turns)
	{
		title = resultTitle(localSeat, winner);
		if (winner == null)
		{
			finalLine = "The match ended in a draw after " + turns + " turns.";
		}
		else if (winner == localSeat)
		{
			finalLine = "You won the match in " + turns + " turns.";
		}
		else
		{
			finalLine = "Your opponent won in " + turns + " turns.";
		}
		setVisible(true);
		revalidate();
		repaint();
	}

	@Override
	public void doLayout()
	{
		Rectangle dialog = dialogBounds(getWidth(), getHeight());
		int buttonWidth = Math.max(96, Math.min(150, dialog.width / 3));
		int buttonHeight = Math.max(30, Math.min(40, dialog.height / 5));
		closeButton.setBounds(dialog.x + (dialog.width - buttonWidth) / 2,
			dialog.y + dialog.height - buttonHeight - Math.max(14, dialog.height / 10), buttonWidth, buttonHeight);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(new Color(5, 4, 3, 190));
			g.fillRect(0, 0, getWidth(), getHeight());
			Rectangle dialog = dialogBounds(getWidth(), getHeight());
			int arc = Math.max(16, dialog.height / 10);
			g.setColor(new Color(38, 28, 18, 250));
			g.fillRoundRect(dialog.x, dialog.y, dialog.width, dialog.height, arc, arc);
			g.setColor(BoardTheme.GOLD);
			g.setStroke(new BasicStroke(Math.max(2f, dialog.height / 100f)));
			g.drawRoundRect(dialog.x + 1, dialog.y + 1, dialog.width - 3, dialog.height - 3, arc, arc);

			float titleSize = Math.max(24f, Math.min(42f, dialog.height * .2f));
			g.setFont(getFont().deriveFont(Font.BOLD, titleSize));
			g.setColor("DEFEAT".equals(title) ? BoardTheme.HEALTH.brighter() : BoardTheme.GOLD);
			int titleY = dialog.y + Math.max(50, dialog.height / 3);
			g.drawString(title, dialog.x + (dialog.width - g.getFontMetrics().stringWidth(title)) / 2, titleY);

			g.setFont(getFont().deriveFont(Font.PLAIN, Math.max(12f, Math.min(17f, dialog.height * .075f))));
			g.setColor(BoardTheme.TEXT);
			int lineY = titleY + Math.max(30, dialog.height / 7);
			g.drawString(finalLine, dialog.x + (dialog.width - g.getFontMetrics().stringWidth(finalLine)) / 2, lineY);
		}
		finally
		{
			g.dispose();
		}
	}

	static String resultTitle(PlayerId localSeat, PlayerId winner)
	{
		if (winner == null) return "DRAW";
		return winner == localSeat ? "VICTORY" : "DEFEAT";
	}

	static Rectangle dialogBounds(int width, int height)
	{
		int safeWidth = Math.max(1, width);
		int safeHeight = Math.max(1, height);
		int dialogWidth = Math.max(300, Math.min(520, safeWidth * 3 / 5));
		int dialogHeight = Math.max(190, Math.min(260, safeHeight * 2 / 5));
		dialogWidth = Math.min(dialogWidth, safeWidth);
		dialogHeight = Math.min(dialogHeight, safeHeight);
		return new Rectangle((safeWidth - dialogWidth) / 2, (safeHeight - dialogHeight) / 2,
			dialogWidth, dialogHeight);
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * Lays a container's children out as a single horizontal run, evenly spaced by a fixed gap
 * and centered both horizontally and vertically within the container. Used for the board's
 * row bands and could be reused anywhere else a centered card run is needed.
 */
public class BoardLayout implements LayoutManager
{
	private final int gap;

	public BoardLayout(int gap)
	{
		this.gap = gap;
	}

	@Override
	public void addLayoutComponent(String name, Component comp)
	{
		// No per-child bookkeeping is needed; children are read straight off the container.
	}

	@Override
	public void removeLayoutComponent(Component comp)
	{
		// No per-child bookkeeping is needed; children are read straight off the container.
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			Insets insets = parent.getInsets();
			int count = parent.getComponentCount();
			int width = 0;
			int height = 0;
			for (int i = 0; i < count; i++)
			{
				Dimension size = parent.getComponent(i).getPreferredSize();
				width += size.width;
				if (i > 0)
				{
					width += gap;
				}
				height = Math.max(height, size.height);
			}
			return new Dimension(width + insets.left + insets.right, height + insets.top + insets.bottom);
		}
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		return preferredLayoutSize(parent);
	}

	@Override
	public void layoutContainer(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			int count = parent.getComponentCount();
			if (count == 0)
			{
				return;
			}

			Insets insets = parent.getInsets();
			int availableWidth = parent.getWidth() - insets.left - insets.right;
			int availableHeight = parent.getHeight() - insets.top - insets.bottom;
			Dimension preferred = parent.getComponent(0).getPreferredSize();
			int actualGap = Math.min(gap, Math.max(2, availableWidth / Math.max(1, count * 10)));
			int cardWidth = Math.min(preferred.width,
				Math.max(18, (availableWidth - actualGap * (count - 1)) / count));
			int cardHeight = Math.min(preferred.height,
				Math.max(24, cardWidth * preferred.height / Math.max(1, preferred.width)));
			if (cardHeight > availableHeight)
			{
				cardHeight = Math.max(24, availableHeight);
				cardWidth = Math.max(18, cardHeight * preferred.width / Math.max(1, preferred.height));
			}
			int totalWidth = cardWidth * count + actualGap * (count - 1);
			int x = Math.max(insets.left, insets.left + (availableWidth - totalWidth) / 2);

			for (int i = 0; i < count; i++)
			{
				Component child = parent.getComponent(i);
				int y = Math.max(insets.top, insets.top + (availableHeight - cardHeight) / 2);
				child.setBounds(x, y, cardWidth, cardHeight);
				x += cardWidth + actualGap;
			}
		}
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.art.CardArtProvider;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.engine.BoardState;
import com.osrstcgbattles.engine.BoardUnit;
import com.osrstcgbattles.engine.PlayerId;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.GridLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.BorderFactory;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;

/**
 * The opponent and local player's flat battlefield bands, each containing at most seven units. Board
 * state is rebuilt into fresh {@link CardTile}s on every {@link #setState} call rather than
 * diffed against the previous layout.
 *
 * Card bounds are adapted by {@link BoardLayout}, allowing both rows to remain centered without a
 * scroll pane when the battle window is narrowed.
 */
@Slf4j
public class BoardPanel extends JPanel
{
	private final BattleCardCatalog catalog;
	private final CardArtProvider art;

	private final Map<PlayerId, JPanel> bands = new HashMap<>();
	private final Map<String, CardTile> tilesByInstanceId = new HashMap<>();

	private Set<String> selectableAttackerIds = Collections.emptySet();
	private Set<String> targetableInstanceIds = Collections.emptySet();
	private String selectedAttackerId;
	private boolean interactionPending;
	private Consumer<String> unitClickListener = instanceId -> { };
	private UnitDragListener unitDragListener;
	private Runnable cancelListener = () -> { };
	private PlayerId viewSeat;

	public BoardPanel(BattleCardCatalog catalog, CardArtProvider art)
	{
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		this.art = Objects.requireNonNull(art, "art");
		setOpaque(false);
		setLayout(new GridLayout(BoardTheme.BOARD_BAND_COUNT, 1, 0, BoardTheme.ROW_GAP));

		// Right-click cancels a pending selection from anywhere on the board, including empty space
		// between/around the battlefield bands; addBand() wires the same gesture onto each band and
		// tile so it also fires when the click lands on one of those instead of this panel's background.
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isRightMouseButton(e))
				{
					cancelListener.run();
				}
			}
		});
	}

	@Override
	public Dimension getPreferredSize()
	{
		if (isPreferredSizeSet())
		{
			return super.getPreferredSize();
		}
		return new Dimension(BoardTheme.BOARD_WIDTH, BoardTheme.BOARD_HEIGHT);
	}

	public void setState(BoardState state, PlayerId localSeat)
	{
		Objects.requireNonNull(state, "state");
		Objects.requireNonNull(localSeat, "localSeat");
		PlayerId opponentSeat = localSeat.opponent();
		viewSeat = localSeat;

		removeAll();
		bands.clear();
		tilesByInstanceId.clear();

		// A rebuild throws away every tile from the previous state, so any highlighting the
		// caller set for that state (an attacker or a unit that can be targeted) is
		// now meaningless: the tiles it referred to no longer exist. Dropping both here means a
		// caller that forgets to re-issue the highlighting after a state change gets a
		// board with no stale highlights, rather than a card that silently looks playable when
		// the new turn no longer allows it.
		selectableAttackerIds = Collections.emptySet();
		targetableInstanceIds = Collections.emptySet();
		selectedAttackerId = null;
		interactionPending = false;

		addBand(state, opponentSeat);
		addBand(state, localSeat);

		applyTargetableHighlighting();
		revalidate();
		repaint();
	}

	public void setSelectableAttackers(List<BoardUnit> units)
	{
		this.selectableAttackerIds = instanceIds(units);
		applyTargetableHighlighting();
	}

	public void setTargetable(List<BoardUnit> units)
	{
		this.targetableInstanceIds = instanceIds(units);
		applyTargetableHighlighting();
	}

	public void setSelectedAttacker(String instanceId)
	{
		this.selectedAttackerId = instanceId;
		applyTargetableHighlighting();
	}

	public void setInteractionPending(boolean pending)
	{
		interactionPending = pending;
		applyTargetableHighlighting();
	}

	public void setUnitClickListener(Consumer<String> listener)
	{
		this.unitClickListener = listener == null ? instanceId -> { } : listener;
	}

	public void setUnitDragListener(UnitDragListener listener)
	{
		unitDragListener = listener;
	}

	/** Right-click anywhere on the board -- a band, a tile, or empty space -- cancels a selection. */
	public void setCancelListener(Runnable listener)
	{
		this.cancelListener = listener == null ? () -> { } : listener;
	}

	private void addBand(BoardState state, PlayerId owner)
	{
		JPanel band = new JPanel(new BoardLayout(BoardTheme.ROW_GAP));
		band.setOpaque(false);
		band.setBorder(BorderFactory.createEmptyBorder(BoardTheme.BAND_TOP_INSET, 6,
			BoardTheme.BAND_BOTTOM_INSET, 6));

		for (BoardUnit unit : state.getUnits(owner))
		{
			Optional<BattleCard> found = catalog.findBoardCardById(unit.getDefinition().getId());
			if (!found.isPresent())
			{
				log.warn("Duelscape TCG: board unit '{}' has no catalog entry, skipping tile",
					unit.getDefinition().getId());
				continue;
			}
			CardTile tile = new CardTile(found.get(), art);
			tile.setCurrentStats(unit.getCurrentAttack(), unit.getCurrentHealth());
			tile.setShielded(unit.isShielded());
			tile.setStealthed(unit.isStealthed());
			// Enemy readiness does not affect whether that unit is a legal attack target.
			tile.setExhausted(owner == viewSeat && !unit.isReady());
			String instanceId = unit.getInstanceId();
			tilesByInstanceId.put(instanceId, tile);
			// Attached once, for the tile's whole lifetime, rather than added/removed on every
			// highlight refresh. Every tile remains clickable so ready allies can be selected and
			// highlighted enemies can be attacked; right-click always cancels either selection.
			MouseAdapter mouse = new MouseAdapter()
			{
				private Point pressed;
				private boolean dragged;

				@Override
				public void mousePressed(MouseEvent event)
				{
					if (owner == viewSeat && SwingUtilities.isLeftMouseButton(event))
					{
						pressed = event.getPoint();
						dragged = false;
					}
				}

				@Override
				public void mouseDragged(MouseEvent event)
				{
					if (pressed == null || unitDragListener == null) return;
					if (!dragged && pressed.distance(event.getPoint()) < 5) return;
					dragged = true;
					unitDragListener.onUnitDragged(instanceId, pointOnBattleSurface(tile, event.getPoint()));
				}

				@Override
				public void mouseReleased(MouseEvent event)
				{
					if (dragged && unitDragListener != null)
					{
						Point drop = pointOnBattleSurface(tile, event.getPoint());
						UnitDragListener listener = unitDragListener;
						SwingUtilities.invokeLater(() -> listener.onUnitDropped(instanceId, drop));
					}
					pressed = null;
				}

				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (SwingUtilities.isRightMouseButton(e))
					{
						cancelListener.run();
					}
					else if (!dragged)
					{
						unitClickListener.accept(instanceId);
					}
				}
			};
			tile.addMouseListener(mouse);
			tile.addMouseMotionListener(mouse);
			band.add(tile);
		}

		band.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isRightMouseButton(e))
				{
					cancelListener.run();
				}
			}
		});

		bands.put(owner, band);
		add(band);
	}

	private static Set<String> instanceIds(List<BoardUnit> units)
	{
		Set<String> ids = new HashSet<String>();
		if (units != null)
		{
			for (BoardUnit unit : units)
			{
				ids.add(unit.getInstanceId());
			}
		}
		return ids;
	}

	String unitAt(Point point)
	{
		if (point == null) return null;
		for (String instanceId : tilesByInstanceId.keySet())
		{
			Rectangle bounds = tileBoundsOnBoard(instanceId);
			if (bounds != null && bounds.contains(point)) return instanceId;
		}
		return null;
	}

	private Point pointOnBattleSurface(CardTile tile, Point point)
	{
		return getParent() == null ? new Point(point) : SwingUtilities.convertPoint(tile, point, getParent());
	}

	interface UnitDragListener
	{
		void onUnitDragged(String instanceId, Point battleSurfacePoint);

		void onUnitDropped(String instanceId, Point battleSurfacePoint);
	}

	private void applyTargetableHighlighting()
	{
		for (Map.Entry<String, CardTile> entry : tilesByInstanceId.entrySet())
		{
			String instanceId = entry.getKey();
			CardTile tile = entry.getValue();
			if (targetableInstanceIds.contains(instanceId))
			{
				tile.setState(CardTile.State.TARGETABLE);
			}
			else if (instanceId.equals(selectedAttackerId))
			{
				tile.setState(CardTile.State.SELECTED);
			}
			else if (selectableAttackerIds.contains(instanceId))
			{
				tile.setState(CardTile.State.PLAYABLE);
			}
			else if (interactionPending)
			{
				tile.setState(CardTile.State.DIMMED);
			}
			else
			{
				tile.setState(CardTile.State.IDLE);
			}
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D graphics = (Graphics2D) g;
		for (PlayerId player : PlayerId.values())
		{
			JPanel band = bands.get(player);
			if (band == null)
			{
				continue;
			}
			Rectangle bounds = band.getBounds();
			graphics.setColor(player == viewSeat ? BoardTheme.GOLD : BoardTheme.TEXT_DIM);
			graphics.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 14, 14);
			graphics.setFont(graphics.getFont().deriveFont(java.awt.Font.BOLD, 10f));
			graphics.drawString(player == viewSeat ? "YOUR BATTLEFIELD" : "OPPONENT",
				bounds.x + 10, bounds.y + 15);
		}

		super.paintComponent(g);
	}

	/**
	 * Package-private test seam: a tile's bounds in this panel's own coordinate space (the
	 * band's bounds plus the tile's bounds within the band). Not part of the public API.
	 */
	Rectangle tileBoundsOnBoard(String instanceId)
	{
		CardTile tile = tilesByInstanceId.get(instanceId);
		if (tile == null)
		{
			return null;
		}
		Rectangle bandBounds = ((JPanel) tile.getParent()).getBounds();
		Rectangle tileBounds = tile.getBounds();
		return new Rectangle(bandBounds.x + tileBounds.x, bandBounds.y + tileBounds.y,
			tileBounds.width, tileBounds.height);
	}

	/** Package-private test seam: a battlefield band's bounds in this panel's own coordinate space. */
	Rectangle bandBounds(PlayerId player)
	{
		JPanel band = bands.get(player);
		return band == null ? null : band.getBounds();
	}

	/** Package-private test seam: the tile for a board unit, so tests can read its render state. */
	CardTile tileFor(String instanceId)
	{
		return tilesByInstanceId.get(instanceId);
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.catalog.Faction;
import com.osrstcgbattles.catalog.Rarity;
import com.osrstcgbattles.engine.DuelscapeEngine;
import com.osrstcgbattles.engine.PlayerId;
import java.awt.Color;
import java.util.EnumMap;
import java.util.Map;

/** Every color, font, and metric the board uses. */
public final class BoardTheme
{
	public static final int CARD_WIDTH = 82;
	public static final int CARD_HEIGHT = 112;
	public static final int CARD_ARC = 8;
	public static final int ROW_GAP = 6;
	public static final int HAND_OVERLAP = 30;
	public static final int BAND_TOP_INSET = 16;
	public static final int BAND_BOTTOM_INSET = 4;

	/** One flat battlefield band per player. */
	public static final int BOARD_BAND_COUNT = PlayerId.values().length;

	/**
	 * The board's own required height: every band stacked at a full {@link #CARD_HEIGHT} with
	 * {@link #ROW_GAP} between them. This is what {@code BoardPanel#getPreferredSize()} reports, so
	 * a {@code JScrollPane} knows to scroll the board rather than let AWT shrink it below the point
	 * where a battlefield band is shorter than a card and tiles start overlapping.
	 */
	public static final int BOARD_HEIGHT = (CARD_HEIGHT + BAND_TOP_INSET + BAND_BOTTOM_INSET) * BOARD_BAND_COUNT
		+ ROW_GAP * (BOARD_BAND_COUNT - 1);

	/**
	 * The board's own required width: a fully-occupied battlefield
	 * ({@link DuelscapeEngine#BATTLEFIELD_LIMIT} units) laid out side by side. This uses the theoretical maximum
	 * rather than however many units happen to be on the board, so the reported size never depends on match
	 * state -- it can never need to grow or shrink out from under the player mid-match. A
	 * lightly-occupied battlefield is simply centered in the same space a full one would use.
	 */
	public static final int BOARD_WIDTH = CARD_WIDTH * DuelscapeEngine.BATTLEFIELD_LIMIT
		+ ROW_GAP * (DuelscapeEngine.BATTLEFIELD_LIMIT - 1);

	public static final Color BACKGROUND = new Color(18, 15, 12);
	public static final Color ROW_BAND = new Color(31, 26, 21);
	public static final Color ROW_BAND_LIGHT = new Color(48, 39, 30);
	public static final Color CARD_INNER = new Color(62, 51, 39);
	public static final Color CARD_PARCHMENT = new Color(218, 197, 155);
	public static final Color MANA = new Color(52, 122, 190);
	public static final Color ATTACK = new Color(196, 139, 48);
	public static final Color HEALTH = new Color(154, 52, 45);
	public static final Color TEXT = new Color(226, 214, 190);
	public static final Color TEXT_DIM = new Color(140, 130, 115);
	public static final Color GOLD = new Color(222, 180, 82);
	public static final Color GLOW_LEGAL = new Color(120, 220, 140);
	public static final Color GLOW_TARGET = new Color(235, 120, 110);
	public static final Color GLOW_SELECTED = new Color(240, 205, 110);

	private static final Map<Faction, Color> FACTION = new EnumMap<>(Faction.class);
	private static final Map<Rarity, Color> RARITY = new EnumMap<>(Rarity.class);

	static
	{
		FACTION.put(Faction.NEUTRAL, new Color(150, 146, 138));
		FACTION.put(Faction.ASGARNIA, new Color(120, 168, 224));
		FACTION.put(Faction.DESERT, new Color(224, 192, 112));
		FACTION.put(Faction.FREMENNIK, new Color(140, 200, 208));
		FACTION.put(Faction.KARAMJA, new Color(224, 140, 96));
		FACTION.put(Faction.KOUREND, new Color(160, 140, 216));
		FACTION.put(Faction.MISTHALIN, new Color(128, 192, 136));
		FACTION.put(Faction.MORYTANIA, new Color(168, 120, 168));
		FACTION.put(Faction.TIRANNWN, new Color(136, 208, 176));
		FACTION.put(Faction.WILDERNESS, new Color(208, 104, 104));

		RARITY.put(Rarity.COMMON, new Color(160, 156, 148));
		RARITY.put(Rarity.UNCOMMON, new Color(128, 192, 136));
		RARITY.put(Rarity.RARE, new Color(120, 168, 224));
		RARITY.put(Rarity.EPIC, new Color(176, 132, 216));
		RARITY.put(Rarity.LEGENDARY, new Color(232, 184, 96));
	}

	private BoardTheme()
	{
	}

	public static Color factionColor(Faction faction)
	{
		Color color = FACTION.get(faction);
		if (color == null)
		{
			throw new IllegalArgumentException("No color for faction " + faction);
		}
		return color;
	}

	public static Color rarityColor(Rarity rarity)
	{
		Color color = RARITY.get(rarity);
		if (color == null)
		{
			throw new IllegalArgumentException("No color for rarity " + rarity);
		}
		return color;
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.art.CardArtProvider;
import com.osrstcgbattles.art.EmblemCardArt;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.CardAbility;
import com.osrstcgbattles.ui.BattleCardTooltips;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Objects;
import javax.swing.JComponent;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Draws one playing card: artwork, frame, mana cost, rarity gem, name, and combat stats.
 * Every color and metric comes from {@link BoardTheme}; nothing is hardcoded here.
 */
public class CardTile extends JComponent
{
	public enum State
	{
		IDLE,
		PLAYABLE,
		SELECTED,
		DIMMED,
		TARGETABLE,
		TARGETED
	}

	private static final float DIMMED_ALPHA = 0.45f;

	private final BattleCard card;

	private State state = State.IDLE;
	private BufferedImage art;
	private boolean faceDown;
	private boolean exhausted;
	private int currentAttack;
	private int currentHealth;
	private boolean shielded;
	private boolean stealthed;

	public CardTile(BattleCard card, CardArtProvider art)
	{
		this.card = Objects.requireNonNull(card, "card");
		this.currentAttack = card.getAttack();
		this.currentHealth = card.getHealth();
		this.shielded = hasAbility(AbilityType.SHIELD);
		this.stealthed = hasAbility(AbilityType.STEALTH);
		setOpaque(false);
		setPreferredSize(new Dimension(BoardTheme.CARD_WIDTH, BoardTheme.CARD_HEIGHT));
		BattleCardTooltips.install(this, card);
		Objects.requireNonNull(art, "art").request(card.getAzCardName(), this::acceptArt);
	}

	public void setState(State state)
	{
		this.state = Objects.requireNonNull(state, "state");
		repaint();
	}

	public State getState()
	{
		return state;
	}

	/** Board tiles show live combat stats; hand tiles retain the card's base stats. */
	public void setCurrentStats(int attack, int health)
	{
		this.currentAttack = attack;
		this.currentHealth = health;
		repaint();
	}

	public void setExhausted(boolean exhausted)
	{
		this.exhausted = exhausted;
		repaint();
	}

	public void setShielded(boolean shielded) { this.shielded = shielded; repaint(); }
	public void setStealthed(boolean stealthed) { this.stealthed = stealthed; repaint(); }

	public void setFaceDown(boolean faceDown)
	{
		this.faceDown = faceDown;
		setToolTipText(faceDown ? null : BattleCardTooltips.format(card));
		repaint();
	}

	private void acceptArt(BufferedImage image)
	{
		this.art = image;
		if (image instanceof AsyncBufferedImage)
		{
			((AsyncBufferedImage) image).onLoaded(this::repaint);
		}
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		int width = getWidth();
		int height = getHeight();
		if (width == 0 || height == 0)
		{
			return;
		}

		Graphics2D graphics = (Graphics2D) g.create();
		try
		{
			Object previousAntialias = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			try
			{
				if (state == State.DIMMED || exhausted)
				{
					Composite previousComposite = graphics.getComposite();
					graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, DIMMED_ALPHA));
					try
					{
						paintTile(graphics, width, height);
					}
					finally
					{
						graphics.setComposite(previousComposite);
					}
					paintStateBorder(graphics, width, height, faceDown
						? BoardTheme.TEXT_DIM : BoardTheme.factionColor(card.getFaction()));
				}
				else
				{
					paintTile(graphics, width, height);
				}
			}
			finally
			{
				if (previousAntialias != null)
				{
					graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, previousAntialias);
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
	}

	private void paintTile(Graphics2D graphics, int width, int height)
	{
		if (faceDown)
		{
			// Faction-neutral: revealing the faction color would leak which faction a hidden
			// opponent card belongs to, narrowing down its identity.
			paintFaceDownFrame(graphics, width, height);
			paintFaceDownPattern(graphics, width, height);
			paintStateBorder(graphics, width, height, BoardTheme.TEXT_DIM);
			return;
		}

		Color faction = BoardTheme.factionColor(card.getFaction());

		paintFrame(graphics, width, height, faction);
		paintArt(graphics, width, height, faction);
		paintNameStrip(graphics, width, height);
		paintManaPip(graphics, width, height);
		paintRarityGem(graphics, width, height);
		paintStatsBadge(graphics, width, height);
		paintKeywordBadges(graphics, width);
		paintStateBorder(graphics, width, height, faction);
	}

	private void paintKeywordBadges(Graphics2D graphics, int width)
	{
		java.util.List<String> labels = new java.util.ArrayList<>();
		if (shielded) labels.add("S");
		if (hasAbility(AbilityType.LIFESTEAL)) labels.add("L");
		if (hasAbility(AbilityType.POISONOUS)) labels.add("P");
		if (hasAbility(AbilityType.RUSH)) labels.add("R");
		if (hasAbility(AbilityType.TAUNT)) labels.add("T");
		if (stealthed) labels.add("ST");
		if (hasAbility(AbilityType.NEX_ASCENSION)) labels.add("N");
		if (hasDeathrattle()) labels.add("D");
		int x = width - 15;
		graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, 8f));
		for (String label : labels)
		{
			int badgeWidth = "ST".equals(label) ? 18 : 13;
			x -= badgeWidth;
			graphics.setColor(new Color(24, 19, 14, 225));
			graphics.fillRoundRect(x, 4, badgeWidth, 13, 6, 6);
			graphics.setColor(BoardTheme.GOLD);
			graphics.drawRoundRect(x, 4, badgeWidth, 13, 6, 6);
			graphics.drawString(label, x + (badgeWidth - graphics.getFontMetrics().stringWidth(label)) / 2, 14);
			x -= 2;
		}
	}

	private boolean hasAbility(AbilityType type)
	{
		for (CardAbility ability : card.getAbilities()) if (ability.getType() == type) return true;
		return false;
	}

	private boolean hasDeathrattle()
	{
		for (CardAbility ability : card.getAbilities())
			if (ability.getType().name().startsWith("DEATHRATTLE_")) return true;
		return false;
	}

	private void paintFrame(Graphics2D graphics, int width, int height, Color faction)
	{
		graphics.setColor(new Color(0, 0, 0, 110));
		graphics.fillRoundRect(3, 4, width - 4, height - 4, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
		graphics.setPaint(new GradientPaint(0, 0, faction.brighter(), width, height, faction.darker().darker()));
		graphics.fillRoundRect(0, 0, width - 2, height - 2, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
		graphics.setColor(BoardTheme.CARD_INNER);
		graphics.fillRoundRect(3, 3, width - 8, height - 8, BoardTheme.CARD_ARC - 2, BoardTheme.CARD_ARC - 2);
		graphics.setColor(new Color(255, 235, 175, 90));
		graphics.drawRoundRect(1, 1, width - 4, height - 4, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
	}

	private void paintArt(Graphics2D graphics, int width, int height, Color faction)
	{
		int margin = Math.max(2, width / 16);
		int artX = margin;
		int artY = margin;
		int artWidth = width - margin * 2;
		int artHeight = height - margin * 2 - height / 5;
		if (artWidth <= 0 || artHeight <= 0)
		{
			return;
		}

		Shape previousClip = graphics.getClip();
		graphics.clip(new RoundRectangle2D.Float(artX, artY, artWidth, artHeight, 7, 7));
		try
		{
			if (art != null)
			{
				graphics.drawImage(art, artX, artY, artWidth, artHeight, null);
			}
			else
			{
				EmblemCardArt.draw(graphics, artX, artY, artWidth, artHeight, faction, card.getDisplayName());
			}
			graphics.setPaint(new GradientPaint(0, artY + artHeight / 2, new Color(0, 0, 0, 0),
				0, artY + artHeight, new Color(8, 6, 4, 190)));
			graphics.fillRect(artX, artY, artWidth, artHeight);
		}
		finally
		{
			graphics.setClip(previousClip);
		}
	}

	private void paintNameStrip(Graphics2D graphics, int width, int height)
	{
		int stripHeight = Math.max(12, height / 6);
		int stripY = height - stripHeight;

		graphics.setPaint(new GradientPaint(0, stripY, BoardTheme.CARD_INNER, 0, height, BoardTheme.BACKGROUND));
		graphics.fillRect(0, stripY, width, stripHeight);

		graphics.setColor(BoardTheme.TEXT);
		Font previousFont = graphics.getFont();
		graphics.setFont(previousFont.deriveFont(Font.BOLD, Math.max(9f, stripHeight * 0.57f)));
		try
		{
			FontMetrics metrics = graphics.getFontMetrics();
			String name = elideToFit(metrics, card.getDisplayName(), width - 6);
			int textX = Math.max(3, (width - metrics.stringWidth(name)) / 2);
			int textY = stripY + (stripHeight + metrics.getAscent() - metrics.getDescent()) / 2;
			graphics.drawString(name, textX, textY);
		}
		finally
		{
			graphics.setFont(previousFont);
		}
	}

	private static String elideToFit(FontMetrics metrics, String text, int maxWidth)
	{
		if (text == null)
		{
			return "";
		}
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String ellipsis = "…";
		StringBuilder builder = new StringBuilder(text);
		while (builder.length() > 0 && metrics.stringWidth(builder.toString() + ellipsis) > maxWidth)
		{
			builder.deleteCharAt(builder.length() - 1);
		}
		return builder.toString() + ellipsis;
	}

	private void paintManaPip(Graphics2D graphics, int width, int height)
	{
		int diameter = Math.max(14, width / 5);
		int x = 2;
		int y = 2;

		graphics.setColor(new Color(7, 30, 55));
		graphics.fillOval(x, y, diameter, diameter);
		graphics.setColor(BoardTheme.MANA.brighter());
		graphics.drawOval(x, y, diameter, diameter);

		String cost = String.valueOf(card.getManaCost());
		Font previousFont = graphics.getFont();
		graphics.setFont(previousFont.deriveFont(Font.BOLD, Math.max(9f, diameter * 0.55f)));
		try
		{
			FontMetrics metrics = graphics.getFontMetrics();
			int textX = x + (diameter - metrics.stringWidth(cost)) / 2;
			int textY = y + (diameter + metrics.getAscent() - metrics.getDescent()) / 2;
			graphics.drawString(cost, textX, textY);
		}
		finally
		{
			graphics.setFont(previousFont);
		}
	}

	private void paintRarityGem(Graphics2D graphics, int width, int height)
	{
		int diameter = Math.max(10, width / 7);
		int x = width - diameter - 2;
		int y = 2;

		graphics.setColor(BoardTheme.rarityColor(card.getRarity()));
		int[] xs = {x + diameter / 2, x + diameter, x + diameter / 2, x};
		int[] ys = {y, y + diameter / 2, y + diameter, y + diameter / 2};
		graphics.fillPolygon(xs, ys, 4);
		graphics.setColor(BoardTheme.BACKGROUND);
		graphics.drawPolygon(xs, ys, 4);
	}

	private void paintStatsBadge(Graphics2D graphics, int width, int height)
	{
		int diameter = Math.max(14, width / 5);
		int stripHeight = Math.max(12, height / 6);
		int x = 3;
		int y = height - stripHeight - diameter + Math.max(2, diameter / 3);
		int healthX = width - diameter - 3;

		paintStatBadge(graphics, x, y, diameter, BoardTheme.ATTACK, currentAttack);
		paintStatBadge(graphics, healthX, y, diameter, BoardTheme.HEALTH, currentHealth);
	}

	private void paintStatBadge(Graphics2D graphics, int x, int y, int diameter, Color color, int value)
	{
		graphics.setColor(new Color(8, 7, 5));
		graphics.fillOval(x - 1, y - 1, diameter + 2, diameter + 2);
		graphics.setColor(color);
		graphics.fillOval(x, y, diameter, diameter);
		graphics.setColor(BoardTheme.TEXT);
		graphics.drawOval(x, y, diameter, diameter);

		String stats = String.valueOf(value);
		Font previousFont = graphics.getFont();
		graphics.setFont(previousFont.deriveFont(Font.BOLD, Math.max(9f, diameter * 0.55f)));
		try
		{
			FontMetrics metrics = graphics.getFontMetrics();
			int textX = x + (diameter - metrics.stringWidth(stats)) / 2;
			int textY = y + (diameter + metrics.getAscent() - metrics.getDescent()) / 2;
			graphics.drawString(stats, textX, textY);
		}
		finally
		{
			graphics.setFont(previousFont);
		}
	}

	private void paintFaceDownFrame(Graphics2D graphics, int width, int height)
	{
		graphics.setPaint(new GradientPaint(0, 0, BoardTheme.ROW_BAND_LIGHT, width, height, BoardTheme.BACKGROUND));
		graphics.fillRoundRect(0, 0, width - 1, height - 1, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
		graphics.setColor(BoardTheme.TEXT_DIM);
		graphics.drawRoundRect(0, 0, width - 1, height - 1, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
	}

	private void paintFaceDownPattern(Graphics2D graphics, int width, int height)
	{
		Color backBase = BoardTheme.BACKGROUND;
		Shape previousClip = graphics.getClip();
		Shape body = new RoundRectangle2D.Float(1, 1, width - 2, height - 2, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
		graphics.clip(body);
		try
		{
			graphics.setColor(backBase);
			graphics.fillRect(0, 0, width, height);

			graphics.setColor(BoardTheme.TEXT_DIM);
			int step = Math.max(6, width / 8);
			for (int diagonal = -height; diagonal < width; diagonal += step)
			{
				graphics.drawLine(diagonal, height, diagonal + height, 0);
			}
		}
		finally
		{
			graphics.setClip(previousClip);
		}
	}

	/** {@code idleColor} is the faction color for a face-up tile, or a neutral color face-down. */
	private void paintStateBorder(Graphics2D graphics, int width, int height, Color idleColor)
	{
		switch (state)
		{
			case SELECTED:
				drawBorder(graphics, width, height, BoardTheme.GLOW_SELECTED, 2);
				break;
			case TARGETED:
				drawBorder(graphics, width, height, BoardTheme.GLOW_TARGET, 2);
				break;
			case PLAYABLE:
				drawBorder(graphics, width, height, BoardTheme.GLOW_LEGAL, 1);
				break;
			case TARGETABLE:
				drawBorder(graphics, width, height, BoardTheme.GLOW_TARGET, 1);
				break;
			case IDLE:
			case DIMMED:
			default:
				drawBorder(graphics, width, height, idleColor.darker().darker(), 1);
				break;
		}
	}

	private void drawBorder(Graphics2D graphics, int width, int height, Color color, int thickness)
	{
		Stroke previousStroke = graphics.getStroke();
		try
		{
			graphics.setStroke(new BasicStroke(thickness));
			graphics.setColor(color);
			int inset = thickness / 2;
			graphics.drawRoundRect(inset, inset, width - 1 - inset * 2, height - 1 - inset * 2,
				BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
		}
		finally
		{
			graphics.setStroke(previousStroke);
		}
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/** Draw-pile stack/count and conditional fatigue indicator. */
public final class DeckDisplay extends JComponent
{
	private int count;
	private int fatigue;

	public void setValues(int count, int fatigue)
	{
		this.count = Math.max(0, count);
		this.fatigue = Math.max(0, fatigue);
		setToolTipText(this.count + " cards remain in the draw pile. "
			+ (this.fatigue > 0 ? "The next empty-deck draw deals at least " + (this.fatigue + 1)
				+ " fatigue damage." : "Drawing from an empty deck causes increasing fatigue damage."));
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int cardWidth = Math.min(38, getWidth() / 2);
			int cardHeight = Math.min(50, getHeight() - 8);
			int y = (getHeight() - cardHeight) / 2;
			for (int i = 2; i >= 0; i--)
			{
				g.setColor(new Color(54 + i * 7, 40 + i * 4, 27));
				g.fillRoundRect(3 + i * 2, y - i * 2, cardWidth, cardHeight, 5, 5);
				g.setColor(BoardTheme.GOLD.darker());
				g.drawRoundRect(3 + i * 2, y - i * 2, cardWidth, cardHeight, 5, 5);
			}
			g.setColor(BoardTheme.TEXT);
			g.setFont(getFont().deriveFont(Font.BOLD, 13f));
			g.drawString(Integer.toString(count), cardWidth + 12, getHeight() / 2);
			if (fatigue > 0)
			{
				g.setColor(BoardTheme.GLOW_TARGET);
				g.setFont(getFont().deriveFont(Font.BOLD, 10f));
				g.drawString("FATIGUE " + fatigue, cardWidth + 12, getHeight() / 2 + 14);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.osrstcgbattles.ui.board;

import com.osrstcgbattles.art.CardArtProvider;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.engine.Card;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;

/** Centered, adaptively overlapping hand for either edge of the battle surface. */
@Slf4j
public class HandPanel extends JPanel
{
	public interface CardDragListener
	{
		void onCardDragged(String cardId, Point boardPoint);

		void onCardDropped(String cardId, Point boardPoint);
	}

	public enum Orientation
	{
		TOP,
		BOTTOM
	}

	private static final int SELECTED_RAISE = 10;
	private static final int HOVER_RAISE = 10;
	private static final int HOVER_GROW = 8;
	private static final int MIN_STEP = 13;

	private final BattleCardCatalog catalog;
	private final CardArtProvider art;
	private final Orientation orientation;
	private final List<JComponent> tiles = new ArrayList<>();
	private final List<String> cardIds = new ArrayList<>();

	private String selectedCardId;
	private JComponent hoveredTile;
	private Consumer<String> cardClickListener = cardId -> { };
	private CardDragListener cardDragListener;
	private Runnable cancelListener = () -> { };
	private boolean faceDown;
	private Set<String> playableCardIds = Collections.emptySet();

	public HandPanel(BattleCardCatalog catalog, CardArtProvider art)
	{
		this(catalog, art, Orientation.BOTTOM);
	}

	public HandPanel(BattleCardCatalog catalog, CardArtProvider art, Orientation orientation)
	{
		this.catalog = Objects.requireNonNull(catalog, "catalog");
		this.art = Objects.requireNonNull(art, "art");
		this.orientation = Objects.requireNonNull(orientation, "orientation");
		setOpaque(false);
		setLayout(null);
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent event)
			{
				layoutTiles();
			}
		});
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (SwingUtilities.isRightMouseButton(event))
				{
					cancelListener.run();
				}
			}
		});
	}

	public void setHand(List<Card> hand)
	{
		Objects.requireNonNull(hand, "hand");
		clearTiles();
		faceDown = false;
		for (Card card : hand)
		{
			Optional<BattleCard> found = catalog.findById(card.getId());
			if (!found.isPresent())
			{
				log.warn("Duelscape TCG: hand card '{}' has no catalog entry, skipping tile", card.getId());
				continue;
			}
			addCardTile(found.get(), card.getId());
		}
		finishRebuild();
	}

	/** Receives only a count and constructs neutral backs without catalog lookup or art requests. */
	public void setFaceDownCount(int count)
	{
		clearTiles();
		faceDown = true;
		selectedCardId = null;
		for (int i = 0; i < Math.max(0, count); i++)
		{
			JComponent tile = new FaceDownTile();
			wireTile(tile, null, true);
		}
		finishRebuild();
	}

	public void setSelected(String cardId)
	{
		selectedCardId = cardId;
		applyCardStates();
		layoutTiles();
	}

	public void setPlayableCardIds(Set<String> cardIds)
	{
		playableCardIds = cardIds == null ? Collections.emptySet() : new HashSet<>(cardIds);
		applyCardStates();
	}

	private void applyCardStates()
	{
		for (int i = 0; i < tiles.size(); i++)
		{
			if (tiles.get(i) instanceof CardTile)
			{
				String id = cardIds.get(i);
				((CardTile) tiles.get(i)).setState(id != null && id.equals(selectedCardId)
					? CardTile.State.SELECTED : playableCardIds.contains(id)
						? CardTile.State.PLAYABLE : CardTile.State.DIMMED);
			}
		}
	}

	public void setCardClickListener(Consumer<String> listener)
	{
		cardClickListener = listener == null ? cardId -> { } : listener;
	}

	public void setCancelListener(Runnable listener)
	{
		cancelListener = listener == null ? () -> { } : listener;
	}

	public void setCardDragListener(CardDragListener listener)
	{
		cardDragListener = listener;
	}

	@Override
	public void doLayout()
	{
		layoutTiles();
	}

	private void addCardTile(BattleCard card, String cardId)
	{
		wireTile(new CardTile(card, art), cardId, false);
	}

	private void wireTile(JComponent tile, String cardId, boolean hidden)
	{
		tiles.add(tile);
		cardIds.add(cardId);
		MouseAdapter mouse = new MouseAdapter()
		{
			private Point pressed;
			private boolean dragged;

			@Override
			public void mousePressed(MouseEvent event)
			{
				if (!hidden && SwingUtilities.isLeftMouseButton(event))
				{
					pressed = event.getPoint();
					dragged = false;
				}
			}

			@Override
			public void mouseDragged(MouseEvent event)
			{
				if (pressed == null || cardDragListener == null)
				{
					return;
				}
				if (!dragged && pressed.distance(event.getPoint()) < 5)
				{
					return;
				}
				dragged = true;
				cardDragListener.onCardDragged(cardId, pointOnBoard(tile, event.getPoint()));
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				if (dragged && cardDragListener != null)
				{
					Point dropPoint = pointOnBoard(tile, event.getPoint());
					CardDragListener listener = cardDragListener;
					// Playing a card rebuilds this hand. Defer it until Swing finishes dispatching
					// MOUSE_RELEASED to the tile that is about to be removed.
					SwingUtilities.invokeLater(() -> listener.onCardDropped(cardId, dropPoint));
				}
				pressed = null;
			}

			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (SwingUtilities.isRightMouseButton(event))
				{
					cancelListener.run();
				}
				else if (!hidden && !dragged)
				{
					cardClickListener.accept(cardId);
				}
			}

			@Override
			public void mouseEntered(MouseEvent event)
			{
				if (!hidden)
				{
					hoveredTile = tile;
					layoutTiles();
				}
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				if (hoveredTile == tile)
				{
					hoveredTile = null;
					layoutTiles();
				}
			}
		};
		tile.addMouseListener(mouse);
		tile.addMouseMotionListener(mouse);
		add(tile, 0);
		restoreZOrder();
	}

	private Point pointOnBoard(JComponent tile, Point point)
	{
		return getParent() == null ? new Point(point) : SwingUtilities.convertPoint(tile, point, getParent());
	}

	private void clearTiles()
	{
		removeAll();
		tiles.clear();
		cardIds.clear();
		hoveredTile = null;
	}

	private void finishRebuild()
	{
		layoutTiles();
		revalidate();
		repaint();
	}

	private void layoutTiles()
	{
		int count = tiles.size();
		if (count == 0 || getWidth() <= 0 || getHeight() <= 0)
		{
			return;
		}
		double middle = (count - 1) / 2.0;
		int maximumFan = (int) Math.round(middle * 1.5);
		int verticalInset = (orientation == Orientation.BOTTOM ? SELECTED_RAISE : 0) + maximumFan + 2;
		int verticalRoom = Math.max(24, getHeight() - verticalInset);
		int cardHeight = Math.min(BoardTheme.CARD_HEIGHT, verticalRoom);
		int cardWidth = Math.max(18, cardHeight * BoardTheme.CARD_WIDTH / BoardTheme.CARD_HEIGHT);
		int step = count == 1 ? 0 : Math.min(cardWidth + BoardTheme.ROW_GAP,
			Math.max(MIN_STEP, (getWidth() - cardWidth) / (count - 1)));
		int runWidth = cardWidth + step * (count - 1);
		int startX = Math.max(0, (getWidth() - runWidth) / 2);
		for (int i = 0; i < count; i++)
		{
			JComponent tile = tiles.get(i);
			int fan = (int) Math.round(Math.abs(i - middle) * 1.5);
			int y = orientation == Orientation.TOP ? fan : SELECTED_RAISE + fan;
			String cardId = cardIds.get(i);
			if (orientation == Orientation.BOTTOM)
			{
				if (cardId != null && cardId.equals(selectedCardId))
				{
					y -= SELECTED_RAISE;
				}
				else if (tile == hoveredTile)
				{
					y -= HOVER_RAISE;
				}
			}
			int x = startX + i * step;
			if (orientation == Orientation.BOTTOM && tile == hoveredTile)
			{
				int grow = Math.min(HOVER_GROW, Math.min(x, getWidth() - x - cardWidth));
				tile.setBounds(x - grow, Math.max(0, y - grow), cardWidth + grow * 2, cardHeight + grow * 2);
				setComponentZOrder(tile, 0);
			}
			else
			{
				tile.setBounds(x, y, cardWidth, cardHeight);
			}
		}
		if (hoveredTile == null)
		{
			restoreZOrder();
		}
		repaint();
	}

	private void restoreZOrder()
	{
		for (int i = 0; i < tiles.size(); i++)
		{
			setComponentZOrder(tiles.get(i), tiles.size() - 1 - i);
		}
	}

	int renderedCardCount()
	{
		return tiles.size();
	}

	boolean rendersOnlyFaceDownCards()
	{
		if (!faceDown)
		{
			return false;
		}
		for (JComponent tile : tiles)
		{
			if (!(tile instanceof FaceDownTile) || tile.getToolTipText() != null)
			{
				return false;
			}
		}
		return true;
	}

	Rectangle cardBounds(int index)
	{
		return new Rectangle(tiles.get(index).getBounds());
	}

	JComponent tileAt(int index)
	{
		return tiles.get(index);
	}

	private static final class FaceDownTile extends JComponent
	{
		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setColor(new Color(39, 29, 21));
				g.fillRoundRect(1, 1, getWidth() - 2, getHeight() - 2, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
				g.setColor(BoardTheme.GOLD.darker());
				g.setStroke(new BasicStroke(2f));
				g.drawRoundRect(2, 2, getWidth() - 5, getHeight() - 5, BoardTheme.CARD_ARC, BoardTheme.CARD_ARC);
				g.setColor(new Color(94, 68, 39));
				for (int x = -getHeight(); x < getWidth(); x += 12)
				{
					g.drawLine(x, getHeight(), x + getHeight(), 0);
				}
				int size = Math.max(10, Math.min(getWidth(), getHeight()) / 3);
				int cx = (getWidth() - size) / 2;
				int cy = (getHeight() - size) / 2;
				g.setColor(BoardTheme.GOLD.darker());
				g.fillOval(cx, cy, size, size);
			}
			finally
			{
				g.dispose();
			}
		}
	}
}

package com.osrstcgbattles.ui.board;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/** Compact mana pips with a numeric fallback at narrow sizes. */
public final class ManaDisplay extends JComponent
{
	private int mana;
	private int maximumMana;

	public ManaDisplay()
	{
		setPreferredSize(new Dimension(92, 18));
		setToolTipText("Mana available");
	}

	public void setMana(int mana, int maximumMana)
	{
		this.mana = Math.max(0, mana);
		this.maximumMana = Math.max(0, maximumMana);
		setToolTipText(this.mana + " mana available of " + this.maximumMana
			+ ". Playing a card spends its shown mana cost.");
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int pipSize = 8;
			int runWidth = maximumMana == 0 ? 0 : maximumMana * (pipSize + 2) - 2;
			if (maximumMana > 0 && runWidth <= getWidth() - 30)
			{
				int y = (getHeight() - pipSize) / 2;
				for (int i = 0; i < maximumMana; i++)
				{
					g.setColor(i < mana ? BoardTheme.MANA : new Color(37, 50, 62));
					g.fillOval(i * (pipSize + 2), y, pipSize, pipSize);
					g.setColor(BoardTheme.TEXT_DIM);
					g.drawOval(i * (pipSize + 2), y, pipSize, pipSize);
				}
			}
			g.setColor(BoardTheme.TEXT);
			g.setFont(getFont().deriveFont(Font.BOLD, 11f));
			String value = mana + "/" + maximumMana;
			g.drawString(value, getWidth() - g.getFontMetrics().stringWidth(value),
				(getHeight() + g.getFontMetrics().getAscent()) / 2 - 1);
		}
		finally
		{
			g.dispose();
		}
	}
}

