import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class DeviceKeyStoreTest
{
	private Filepath temporaryDirectory;

	@Before
	public void createTemporaryDirectory() throws IOException
	{
		Filepath testDirectory = new TestPlugin().directory();
		testDirectory.createDirectories();
		temporaryDirectory = testDirectory.createTempDir("device-key-test-").rooted();
	}

	@After
	public void deleteTemporaryDirectory() throws IOException
	{
		if (temporaryDirectory != null && temporaryDirectory.exists())
		{
			temporaryDirectory.deleteRecursively();
		}
	}

	@Test
	public void createsPersistsAndReloadsSigningIdentity() throws Exception
	{
		DeviceKeyStore created = DeviceKeyStore.loadOrCreate(temporaryDirectory);
		DeviceKeyStore loaded = DeviceKeyStore.loadOrCreate(temporaryDirectory);

		assertEquals(created.getPublicKeyBase64Url(), loaded.getPublicKeyBase64Url());
		assertEquals(created.getFingerprint(), loaded.getFingerprint());
		assertTrue(temporaryDirectory.joinSegment(DeviceKeyStore.FILE_NAME).isFile());

		byte[] message = "canonical request bytes".getBytes(StandardCharsets.UTF_8);
		PublicKey publicKey = decodePublicKey(loaded.getPublicKeyBase64Url());
		Signature verifier = Signature.getInstance("SHA256withECDSA");
		verifier.initVerify(publicKey);
		verifier.update(message);
		assertTrue(verifier.verify(loaded.sign(message)));
	}

	@Test
	public void exposesFingerprintOfEncodedPublicKey() throws Exception
	{
		DeviceKeyStore store = DeviceKeyStore.loadOrCreate(temporaryDirectory);
		byte[] publicEncoding = Base64.getUrlDecoder().decode(store.getPublicKeyBase64Url());
		String expected = Base64.getUrlEncoder().withoutPadding()
			.encodeToString(MessageDigest.getInstance("SHA-256").digest(publicEncoding));

		assertEquals(expected, store.getFingerprint());
		assertFalse(store.getPublicKeyBase64Url().contains("="));
		assertFalse(store.getFingerprint().contains("="));
	}

	@Test
	public void rejectsCorruptExistingFileWithoutRotatingIt() throws Exception
	{
		Filepath keyFile = temporaryDirectory.joinSegment(DeviceKeyStore.FILE_NAME);
		byte[] corrupt = "not a device key".getBytes(StandardCharsets.US_ASCII);
		keyFile.write(corrupt);

		try
		{
			DeviceKeyStore.loadOrCreate(temporaryDirectory);
			fail("Expected corrupt key file to fail");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage().contains("device key") || expected.getMessage().contains("Device key"));
		}

		byte[] after = new byte[corrupt.length];
		try (java.io.InputStream input = keyFile.openInputStream())
		{
			int offset = 0;
			while (offset < after.length)
			{
				int count = input.read(after, offset, after.length - offset);
				if (count < 0)
				{
					break;
				}
				offset += count;
			}
		}
		assertArrayEquals(corrupt, after);
	}

	@Test
	public void rejectsOversizedExistingFile() throws Exception
	{
		Filepath keyFile = temporaryDirectory.joinSegment(DeviceKeyStore.FILE_NAME);
		byte[] oversized = new byte[2049];
		Arrays.fill(oversized, (byte) 1);
		keyFile.write(oversized);

		try
		{
			DeviceKeyStore.loadOrCreate(temporaryDirectory);
			fail("Expected oversized key file to fail");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage().contains("size"));
		}
		assertEquals(oversized.length, keyFile.size());
	}

	@Test
	public void rejectsValidEcKeysFromAnyCurveOtherThanP256() throws Exception
	{
		KeyPairGenerator generator = KeyPairGenerator.getInstance("EC");
		generator.initialize(new ECGenParameterSpec("secp384r1"));
		writeKeyPair(generator.generateKeyPair());

		try
		{
			DeviceKeyStore.loadOrCreate(temporaryDirectory);
			fail("Expected a non-P-256 key to fail");
		}
		catch (GeneralSecurityException expected)
		{
			assertTrue(expected.getMessage().contains("P-256"));
		}
	}

	@Test
	public void signaturesDoNotVerifyForChangedBytes() throws Exception
	{
		DeviceKeyStore store = DeviceKeyStore.loadOrCreate(temporaryDirectory);
		byte[] signature = store.sign("one".getBytes(StandardCharsets.US_ASCII));
		Signature verifier = Signature.getInstance("SHA256withECDSA");
		verifier.initVerify(decodePublicKey(store.getPublicKeyBase64Url()));
		verifier.update("two".getBytes(StandardCharsets.US_ASCII));

		assertFalse(verifier.verify(signature));
	}

	private static PublicKey decodePublicKey(String encoded) throws Exception
	{
		return KeyFactory.getInstance("EC").generatePublic(
			new X509EncodedKeySpec(Base64.getUrlDecoder().decode(encoded)));
	}

	private void writeKeyPair(KeyPair keyPair) throws IOException
	{
		byte[] privateKey = keyPair.getPrivate().getEncoded();
		byte[] publicKey = keyPair.getPublic().getEncoded();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes))
		{
			output.write(new byte[]{'O', 'S', 'R', 'S', 'T', 'C', 'G', 'K'});
			output.writeInt(1);
			output.writeInt(privateKey.length);
			output.write(privateKey);
			output.writeInt(publicKey.length);
			output.write(publicKey);
		}
		temporaryDirectory.joinSegment(DeviceKeyStore.FILE_NAME).write(bytes.toByteArray());
	}

	@PluginDescriptor(name = "Device key store tests", internalName = "device-key-store-tests")
	private static final class TestPlugin extends Plugin
	{
		private Filepath directory() throws IOException
		{
			return getPluginDirectory();
		}
	}
}

package com.osrstcgbattles.catalog;

import com.google.gson.Gson;
import com.osrstcgbattles.engine.DuelscapeEngine;
import java.io.StringReader;
import java.util.EnumSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class BattleCardCatalogLoaderTest
{
	@Test
	public void exposesDeathrattleSpiritOnlyAsABoardToken()
	{
		BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();

		assertFalse(catalog.findById("deathrattle-spirit").isPresent());
		BattleCard spirit = catalog.findBoardCardById("deathrattle-spirit").get();
		assertEquals("Spirit", spirit.getDisplayName());
		assertEquals(1, spirit.getAttack());
		assertEquals(1, spirit.getHealth());
	}

	@Test
	public void rejectsEffectsRequiringDifferentCommandTargets()
	{
		try
		{
			load(effect("DEPLOY_BOOST", "ALLIED_UNIT") + "," + effect("DEPLOY_DAMAGE", "ENEMY_UNIT"));
			fail("Expected incompatible targets to fail");
		}
		catch (CatalogValidationException error)
		{
			assertTrue(error.getMessage().contains("incompatible command targets"));
		}
	}

	@Test
	public void permitsSelfAndNoTargetEffectsWithOneCommandTargetClass()
	{
		BattleCardCatalog catalog = load(effect("DEPLOY_BOOST", "SELF") + ","
			+ "{\"type\":\"VANILLA\"}," + effect("DEPLOY_DAMAGE", "ENEMY_UNIT"));

		assertEquals(3, catalog.getCards().get(0).getAbilities().size());
	}

	@Test
	public void defaultCatalogLoadsNoTargetManaCards()
	{
		BattleCard lightbearer = new BattleCardCatalogLoader(new Gson()).loadDefault().findById("neutral-lightbearer").get();

		assertEquals(0, lightbearer.getManaCost());
		assertEquals(AbilityType.GAIN_MANA, lightbearer.getAbilities().get(0).getType());
		assertEquals(Integer.valueOf(1), lightbearer.getAbilities().get(0).getNumericParams().get("amount"));
		assertTrue(lightbearer.getAbilities().get(0).getStringParams().isEmpty());
	}

	@Test
	public void defaultCatalogMatchesLoaderAndEngineRulesetVersions()
	{
		BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();

		assertEquals(BattleCardCatalogLoader.SUPPORTED_CATALOG_VERSION, catalog.getCatalogVersion());
		assertEquals(BattleCardCatalogLoader.SUPPORTED_RULESET_VERSION, catalog.getRulesetVersion());
		assertEquals(DuelscapeEngine.RULESET_VERSION, catalog.getRulesetVersion());
	}

	@Test
	public void expandedCatalogContainsEverySupportedArchetype()
	{
		BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();
		EnumSet<AbilityType> found = EnumSet.noneOf(AbilityType.class);
		for (BattleCard card : catalog.getCards())
			for (CardAbility ability : card.getAbilities()) found.add(ability.getType());

		assertEquals(400, catalog.getCards().size());
		for (AbilityType type : AbilityType.values()) assertTrue("Missing " + type, found.contains(type));
	}

	private static BattleCardCatalog load(String abilities)
	{
		String json = "{\"catalogVersion\":2,\"rulesetVersion\":8,\"cards\":[{"
			+ "\"id\":\"test-card\",\"azCardName\":\"Test Card\",\"displayName\":\"Test Card\","
			+ "\"category\":\"UNIT\",\"faction\":\"NEUTRAL\",\"rarity\":\"COMMON\","
			+ "\"manaCost\":1,\"attack\":1,\"health\":1,\"tags\":[],\"rulesText\":\"Test\","
			+ "\"abilities\":[" + abilities + "]}]}";
		return new BattleCardCatalogLoader(new Gson()).load(new StringReader(json));
	}

	private static String effect(String type, String target)
	{
		return "{\"type\":\"" + type + "\",\"numericParams\":{\"amount\":1},"
			+ "\"stringParams\":{\"target\":\"" + target + "\"}}";
	}
}

package com.osrstcgbattles.collection;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.argThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

public class OwnedCardCollectionBridgeTest
{
	@Test
	public void queriesTheSharedBetaAndV1ProtocolOnStart()
	{
		EventBus eventBus = mock(EventBus.class);
		OwnedCardCollectionBridge bridge = new OwnedCardCollectionBridge(eventBus);

		bridge.start();

		verify(eventBus).register(bridge);
		verify(eventBus).post(argThat(event -> event instanceof PluginMessage
			&& OwnedCardCollectionBridge.NAMESPACE.equals(((PluginMessage) event).getNamespace())
			&& OwnedCardCollectionBridge.QUERY.equals(((PluginMessage) event).getName())));
	}

	@Test
	public void acceptsBetaOwnedNamesPayload()
	{
		OwnedCardCollectionBridge bridge = startedBridge();
		Map<String, Object> data = new HashMap<>();
		data.put(OwnedCardCollectionBridge.KEY_OWNED_NAMES, List.of(" Chicken ", "Kree'arra"));

		bridge.onPluginMessage(new PluginMessage(
			OwnedCardCollectionBridge.NAMESPACE, OwnedCardCollectionBridge.REPLY, data));

		OwnedCardCollectionSnapshot snapshot = bridge.snapshot();
		assertTrue(snapshot.isKnown());
		assertTrue(snapshot.owns("chicken"));
		assertTrue(snapshot.owns("KREE'ARRA"));
		assertEquals(2, snapshot.getOwnedNames().size());
	}

	@Test
	public void acceptsV1PayloadWithAdditionalOwnershipFields()
	{
		OwnedCardCollectionBridge bridge = startedBridge();
		Map<String, Object> data = new HashMap<>();
		data.put(OwnedCardCollectionBridge.KEY_OWNED_NAMES, List.of("Goblin"));
		data.put("ownedFoilNames", List.of("Goblin"));
		data.put("ownedItemIds", List.of(123L));
		data.put("ownedNpcIds", List.of(456L));

		bridge.onPluginMessage(new PluginMessage(
			OwnedCardCollectionBridge.NAMESPACE, OwnedCardCollectionBridge.CHANGED, data));

		OwnedCardCollectionSnapshot snapshot = bridge.snapshot();
		assertTrue(snapshot.isKnown());
		assertTrue(snapshot.owns("goblin"));
		assertFalse(snapshot.owns("chicken"));
	}

	@Test
	public void mapsV1CanonicalNamesToLegacyBattleCardNames()
	{
		OwnedCardCollectionBridge bridge = startedBridge();
		Map<String, Object> data = new HashMap<>();
		data.put(OwnedCardCollectionBridge.KEY_OWNED_NAMES, List.of("Ice troll", "npc:6616"));

		bridge.onPluginMessage(new PluginMessage(
			OwnedCardCollectionBridge.NAMESPACE, OwnedCardCollectionBridge.REPLY, data));

		OwnedCardCollectionSnapshot snapshot = bridge.snapshot();
		assertTrue(snapshot.owns("Ice troll male"));
		assertTrue(snapshot.owns("Frenzied ice troll male"));
		assertTrue(snapshot.owns("Scorpia's offspring"));
		assertEquals(2, snapshot.getOwnedNames().size());
	}

	@Test
	public void keepsBetaVariantOwnershipSeparate()
	{
		OwnedCardCollectionBridge bridge = startedBridge();
		Map<String, Object> data = new HashMap<>();
		data.put(OwnedCardCollectionBridge.KEY_OWNED_NAMES, List.of("Ice troll male"));

		bridge.onPluginMessage(new PluginMessage(
			OwnedCardCollectionBridge.NAMESPACE, OwnedCardCollectionBridge.REPLY, data));

		OwnedCardCollectionSnapshot snapshot = bridge.snapshot();
		assertTrue(snapshot.owns("Ice troll male"));
		assertFalse(snapshot.owns("Frenzied ice troll male"));
	}

	private static OwnedCardCollectionBridge startedBridge()
	{
		OwnedCardCollectionBridge bridge = new OwnedCardCollectionBridge(mock(EventBus.class));
		bridge.start();
		return bridge;
	}
}

package com.osrstcgbattles.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DuelscapeEngineTest
{
	private final DuelscapeEngine engine = new DuelscapeEngine();

	@Test
	public void matchStartsWithHearthstoneResources()
	{
		MatchState state = newMatch();

		assertEquals(20, state.getPlayer(PlayerId.PLAYER_ONE).getHeroHealth());
		assertEquals(20, state.getPlayer(PlayerId.PLAYER_TWO).getHeroHealth());
		assertEquals(1, state.getPlayer(PlayerId.PLAYER_ONE).getMana());
		assertEquals(0, state.getPlayer(PlayerId.PLAYER_TWO).getMana());
		assertEquals(6, state.getPlayer(PlayerId.PLAYER_ONE).getHand().size());
		assertEquals(5, state.getPlayer(PlayerId.PLAYER_TWO).getHand().size());
		assertEquals(PlayerId.PLAYER_ONE, state.getActivePlayer().get());
	}

	@Test
	public void unitsHaveSummoningSicknessAndExchangeCombatDamage()
	{
		MatchState state = accepted(newMatch(), new PlayCardCommand(PlayerId.PLAYER_ONE, "p1"));
		BoardUnit first = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0);
		assertFalse(first.isReady());
		assertEquals(RejectionReason.ATTACKER_NOT_READY, engine.execute(state,
			new AttackCommand(PlayerId.PLAYER_ONE, first.getInstanceId())).getRejectionReason().get());

		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new PlayCardCommand(PlayerId.PLAYER_TWO, "p2"));
		BoardUnit second = state.getBoard().getUnits(PlayerId.PLAYER_TWO).get(0);
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));
		first = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0);
		assertTrue(first.isReady());

		state = accepted(state, new AttackCommand(PlayerId.PLAYER_ONE, first.getInstanceId(),
			second.getInstanceId()));
		assertTrue(state.getBoard().getUnits(PlayerId.PLAYER_ONE).isEmpty());
		assertEquals(1, state.getBoard().getUnits(PlayerId.PLAYER_TWO).get(0).getCurrentHealth());
		assertEquals(1, state.getPlayer(PlayerId.PLAYER_ONE).getGraveyard().size());
	}

	@Test
	public void unitCanAttackHeroOnlyOncePerTurn()
	{
		MatchState state = accepted(newMatch(), new PlayCardCommand(PlayerId.PLAYER_ONE, "p1"));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));
		String attacker = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0).getInstanceId();

		state = accepted(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker));
		assertEquals(17, state.getPlayer(PlayerId.PLAYER_TWO).getHeroHealth());
		CommandResult secondAttack = engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker));
		assertFalse(secondAttack.isAccepted());
		assertEquals(RejectionReason.ATTACKER_NOT_READY, secondAttack.getRejectionReason().get());
	}

	@Test
	public void heroCannotBeAttackedWhileEnemyHasUnits()
	{
		MatchState state = accepted(newMatch(), new PlayCardCommand(PlayerId.PLAYER_ONE, "p1"));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new PlayCardCommand(PlayerId.PLAYER_TWO, "p2"));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));
		String attacker = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0).getInstanceId();

		CommandResult blocked = engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker));
		assertFalse(blocked.isAccepted());
		assertEquals(RejectionReason.HERO_PROTECTED, blocked.getRejectionReason().get());
		assertEquals(20, state.getPlayer(PlayerId.PLAYER_TWO).getHeroHealth());
	}

	@Test
	public void heroAttackIsAllowedOnceEnemyBoardIsCleared()
	{
		MatchState state = engine.newMatch(deck("p1", 5, 5), deck("p2", 1, 1), 43L);
		state = accepted(state, new PlayCardCommand(PlayerId.PLAYER_ONE, "p1"));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new PlayCardCommand(PlayerId.PLAYER_TWO, "p2"));
		String enemy = state.getBoard().getUnits(PlayerId.PLAYER_TWO).get(0).getInstanceId();
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));
		String attacker = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0).getInstanceId();

		state = accepted(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker, enemy));
		assertTrue(state.getBoard().getUnits(PlayerId.PLAYER_TWO).isEmpty());
		assertFalse(state.getBoard().getUnits(PlayerId.PLAYER_ONE).isEmpty());

		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));
		attacker = state.getBoard().getUnits(PlayerId.PLAYER_ONE).get(0).getInstanceId();

		state = accepted(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker));
		assertEquals(15, state.getPlayer(PlayerId.PLAYER_TWO).getHeroHealth());
	}

	@Test
	public void fatigueDamageIncreasesOnEachEmptyDraw()
	{
		PlayerState player = new PlayerState(20, 0, 1, 0, 0, Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), 0, true);

		player = player.drawOne(DuelscapeEngine.HAND_LIMIT);
		assertEquals(19, player.getHeroHealth());
		assertEquals(1, player.getFatigue());
		player = player.drawOne(DuelscapeEngine.HAND_LIMIT);
		assertEquals(17, player.getHeroHealth());
		assertEquals(2, player.getFatigue());
	}

	@Test(expected = IllegalArgumentException.class)
	public void unsupportedCardImplementationsAreRejectedAtMatchCreation()
	{
		List<Card> unsupported = new ArrayList<>();
		for (int i = 0; i < DuelscapeEngine.DECK_SIZE; i++)
		{
			unsupported.add(new Card()
			{
				@Override public String getId() { return "future"; }
				@Override public String getName() { return "Future"; }
				@Override public int getManaCost() { return 0; }
			});
		}
		engine.newMatch(unsupported, deck("p2", 2, 2), 1L);
	}

	@Test
	public void manaEffectAddsTemporaryManaWithoutRequiringATarget()
	{
		List<Card> manaDeck = new ArrayList<>();
		for (int i = 0; i < DuelscapeEngine.DECK_SIZE; i++)
		{
			manaDeck.add(new SpecialCard("lightbearer", "Lightbearer", 0, Collections.singletonList(
				new DeployEffect(DeployEffect.Type.MANA, DeployEffect.Target.HERO, 1))));
		}
		MatchState state = engine.newMatch(manaDeck, deck("p2", 2, 2), 1L);

		CommandResult result = engine.execute(state, new PlayCardCommand(PlayerId.PLAYER_ONE, "lightbearer"));

		assertTrue(result.isAccepted());
		assertEquals(2, result.getState().getPlayer(PlayerId.PLAYER_ONE).getMana());
		assertEquals(1, result.getState().getPlayer(PlayerId.PLAYER_ONE).getTemporaryMana());
		assertEquals(1, result.getState().getPlayer(PlayerId.PLAYER_ONE).getMaximumMana());
		assertEquals(1, result.getState().getPlayer(PlayerId.PLAYER_ONE).getGraveyard().size());

		MatchState ended = accepted(result.getState(), new EndTurnCommand(PlayerId.PLAYER_ONE));
		assertEquals(1, ended.getPlayer(PlayerId.PLAYER_ONE).getMana());
		assertEquals(0, ended.getPlayer(PlayerId.PLAYER_ONE).getTemporaryMana());
	}

	@Test
	public void spendingManaConsumesTemporaryManaBeforePermanentMana()
	{
		PlayerState spent = player(2, Collections.emptyList(), Collections.emptyList())
			.gainTemporaryMana(2).spendMana(1);

		assertEquals(3, spent.getMana());
		assertEquals(1, spent.getTemporaryMana());
		assertEquals(2, spent.getMana() - spent.getTemporaryMana());
	}

	@Test
	public void stateHashesDistinguishTemporaryFromPermanentMana()
	{
		PlayerState permanent = player(2, Collections.emptyList(), Collections.emptyList());
		PlayerState temporary = player(1, Collections.emptyList(), Collections.emptyList()).gainTemporaryMana(1);
		assertEquals(permanent.getMana(), temporary.getMana());

		MatchState permanentState = state(permanent, BoardState.empty());
		MatchState temporaryState = state(temporary, BoardState.empty());

		assertFalse(permanentState.getPublicStateHash().equals(temporaryState.getPublicStateHash()));
		assertFalse(permanentState.getSynchronizationStateHash().equals(
			temporaryState.getSynchronizationStateHash()));
	}

	@Test
	public void deployBoostAndDamageEffectsResolveOnTheirTargets()
	{
		UnitCard booster = new UnitCard("booster", "Booster", 0, 2, 3, Collections.singletonList(
			new DeployEffect(DeployEffect.Type.BOOST, DeployEffect.Target.SELF, 2)));
		MatchState boosted = accepted(state(player(1, Collections.singletonList(booster), Collections.emptyList()),
			BoardState.empty()), new PlayCardCommand(PlayerId.PLAYER_ONE, "booster"));
		assertEquals(4, boosted.getBoard().find("unit-1").getCurrentAttack());
		assertEquals(5, boosted.getBoard().find("unit-1").getCurrentHealth());

		SpecialCard strike = new SpecialCard("strike", "Strike", 0, Collections.singletonList(
			new DeployEffect(DeployEffect.Type.DAMAGE, DeployEffect.Target.ENEMY_UNIT, 2)));
		BoardState enemyBoard = BoardState.empty().add(PlayerId.PLAYER_TWO,
			BoardUnit.deploy("enemy", new UnitCard("enemy", "Enemy", 0, 1, 4)));
		MatchState damaged = accepted(state(player(1, Collections.singletonList(strike), Collections.emptyList()),
			enemyBoard), new PlayCardCommand(PlayerId.PLAYER_ONE, "strike", "enemy"));
		assertEquals(2, damaged.getBoard().find("enemy").getCurrentHealth());
	}

	@Test
	public void handAndBattlefieldCapsAreEnforced()
	{
		List<Card> fullHand = new ArrayList<>();
		for (int i = 0; i < DuelscapeEngine.HAND_LIMIT; i++) fullHand.add(new UnitCard("hand-" + i, "Hand", 0, 1, 1));
		PlayerState drawn = player(1, fullHand,
			Collections.singletonList(new UnitCard("overflow", "Overflow", 0, 1, 1))).drawOne(DuelscapeEngine.HAND_LIMIT);
		assertEquals(DuelscapeEngine.HAND_LIMIT, drawn.getHand().size());
		assertTrue(drawn.getDrawPile().isEmpty());
		assertEquals("overflow", drawn.getGraveyard().get(0).getId());

		BoardState fullBoard = BoardState.empty();
		for (int i = 0; i < DuelscapeEngine.BATTLEFIELD_LIMIT; i++)
		{
			fullBoard = fullBoard.add(PlayerId.PLAYER_ONE,
				BoardUnit.deploy("unit-" + i, new UnitCard("board-" + i, "Board", 0, 1, 1)));
		}
		PlayerState withUnit = player(1,
			Collections.singletonList(new UnitCard("extra", "Extra", 0, 1, 1)), Collections.emptyList());
		CommandResult rejected = engine.execute(state(withUnit, fullBoard),
			new PlayCardCommand(PlayerId.PLAYER_ONE, "extra"));
		assertFalse(rejected.isAccepted());
		assertEquals(RejectionReason.BATTLEFIELD_FULL, rejected.getRejectionReason().get());
		assertEquals(1, rejected.getState().getPlayer(PlayerId.PLAYER_ONE).getHand().size());
	}

	private MatchState newMatch()
	{
		return engine.newMatch(deck("p1", 3, 2), deck("p2", 2, 4), 42L);
	}

	private MatchState accepted(MatchState state, Command command)
	{
		CommandResult result = engine.execute(state, command);
		assertTrue(result.getRejectionReason().orElse(null) + "", result.isAccepted());
		return result.getState();
	}

	private static List<Card> deck(String id, int attack, int health)
	{
		List<Card> cards = new ArrayList<>();
		for (int i = 0; i < DuelscapeEngine.DECK_SIZE; i++)
		{
			cards.add(new UnitCard(id, id, 0, attack, health));
		}
		return cards;
	}

	private static PlayerState player(int mana, List<? extends Card> hand, List<? extends Card> drawPile)
	{
		return new PlayerState(20, mana, 1, 0, 1, hand, drawPile, Collections.emptyList(), 0, true);
	}

	private static MatchState state(PlayerState first, BoardState board)
	{
		Map<PlayerId, PlayerState> players = new EnumMap<>(PlayerId.class);
		players.put(PlayerId.PLAYER_ONE, first);
		players.put(PlayerId.PLAYER_TWO, player(1, Collections.emptyList(), Collections.emptyList()));
		return new MatchState(1, PlayerId.PLAYER_ONE, PlayerId.PLAYER_ONE, MatchStatus.ACTIVE,
			MatchPhase.PLAY, null, players, board, 1L);
	}
}

package com.osrstcgbattles.engine;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DuelscapeKeywordTest
{
	private final DuelscapeEngine engine = new DuelscapeEngine();

	@Test
	public void shieldBlocksFirstCombatDamage()
	{
		MatchState state = state(unit("attacker", 3, 3), unit("shield", 2, 2, UnitKeyword.SHIELD));
		CommandResult result = attack(state, "unit-1", "unit-2");

		BoardUnit shield = result.getState().getBoard().find("unit-2");
		assertEquals(2, shield.getCurrentHealth());
		assertFalse(shield.isShielded());
		assertEquals(1, result.getState().getBoard().find("unit-1").getCurrentHealth());
	}

	@Test
	public void poisonousCombatDamageDestroysAnyUnit()
	{
		MatchState state = state(unit("poison", 1, 2, UnitKeyword.POISONOUS), unit("giant", 0, 10));
		CommandResult result = attack(state, "unit-1", "unit-2");

		assertTrue(result.getState().getBoard().getUnits(PlayerId.PLAYER_TWO).isEmpty());
	}

	@Test
	public void shieldPreventsPoisonousWhenItPreventsDamage()
	{
		MatchState state = state(unit("poison", 1, 2, UnitKeyword.POISONOUS),
			unit("shield", 0, 10, UnitKeyword.SHIELD));

		BoardUnit target = attack(state, "unit-1", "unit-2").getState().getBoard().find("unit-2");

		assertEquals(10, target.getCurrentHealth());
		assertFalse(target.isShielded());
	}

	@Test
	public void lifestealHealsDamageActuallyDealt()
	{
		MatchState state = state(unit("leech", 3, 3, UnitKeyword.LIFESTEAL), unit("target", 0, 5), 10, 20);
		CommandResult result = attack(state, "unit-1", "unit-2");

		assertEquals(13, result.getState().getPlayer(PlayerId.PLAYER_ONE).getHeroHealth());
	}

	@Test
	public void rushCanAttackUnitsButNotHeroOnDeployTurn()
	{
		MatchState state = state(unit("rush", 2, 2, UnitKeyword.RUSH), unit("target", 0, 3));

		assertEquals(RejectionReason.RUSH_CANNOT_ATTACK_HERO,
			engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, "unit-1")).getRejectionReason().get());
		assertTrue(attack(state, "unit-1", "unit-2").isAccepted());
	}

	@Test
	public void tauntMustBeAttackedBeforeOtherUnits()
	{
		UnitCard attacker = unit("attacker", 2, 4);
		BoardState board = BoardState.empty()
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-1", attacker)).readyAll(PlayerId.PLAYER_ONE)
			.add(PlayerId.PLAYER_TWO, BoardUnit.deploy("unit-2", unit("taunt", 1, 4, UnitKeyword.TAUNT)))
			.add(PlayerId.PLAYER_TWO, BoardUnit.deploy("unit-3", unit("other", 1, 4)));
		MatchState state = state(board, defaultPlayer(20), defaultPlayer(20));

		assertEquals(RejectionReason.TAUNT_PROTECTED,
			engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, "unit-1", "unit-3"))
				.getRejectionReason().get());
		assertTrue(attack(state, "unit-1", "unit-2").isAccepted());
	}

	@Test
	public void stealthPreventsEnemyTargetingUntilTheUnitAttacks()
	{
		MatchState state = state(unit("attacker", 2, 3), unit("stealth", 2, 3, UnitKeyword.STEALTH));

		assertEquals(RejectionReason.TARGET_STEALTHED,
			engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, "unit-1", "unit-2"))
				.getRejectionReason().get());
	}

	@Test
	public void stealthIsRevealedWhenTheUnitAttacks()
	{
		MatchState state = state(unit("stealth", 2, 3, UnitKeyword.STEALTH), unit("target", 0, 4));

		MatchState next = attack(state, "unit-1", "unit-2").getState();

		assertFalse(next.getBoard().find("unit-1").isStealthed());
	}

	@Test
	public void rushRestrictionClearsAtTheStartOfTheUnitsNextTurn()
	{
		MatchState state = state(unit("rush", 2, 3, UnitKeyword.RUSH), unit("target", 0, 4));
		assertTrue(state.getBoard().find("unit-1").isRushRestricted());

		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_ONE));
		state = accepted(state, new EndTurnCommand(PlayerId.PLAYER_TWO));

		assertTrue(state.getBoard().find("unit-1").isReady());
		assertFalse(state.getBoard().find("unit-1").isRushRestricted());
	}

	@Test
	public void simultaneousLethalCompletesAsADraw()
	{
		List<DeathrattleEffect> lethal = Collections.singletonList(
			new DeathrattleEffect(DeathrattleEffect.Type.DAMAGE_ENEMY_HERO, 1));
		UnitCard attacker = new UnitCard("attacker", "Attacker", 0, 1, 1, Collections.emptyList(),
			Collections.emptySet(), lethal);
		UnitCard target = new UnitCard("target", "Target", 0, 1, 1, Collections.emptyList(),
			Collections.emptySet(), lethal);
		MatchState state = state(attacker, target, 1, 1);

		MatchState next = attack(state, "unit-1", "unit-2").getState();

		assertEquals(MatchStatus.COMPLETE, next.getStatus());
		assertEquals(MatchPhase.COMPLETE, next.getPhase());
		assertFalse(next.getActivePlayer().isPresent());
		assertFalse(next.getWinner().isPresent());
		assertEquals(0, next.getPlayer(PlayerId.PLAYER_ONE).getHeroHealth());
		assertEquals(0, next.getPlayer(PlayerId.PLAYER_TWO).getHeroHealth());
	}

	@Test
	public void mixedDeathrattlesDamageDrawAndSummon()
	{
		List<DeathrattleEffect> deathrattles = java.util.Arrays.asList(
			new DeathrattleEffect(DeathrattleEffect.Type.DAMAGE_ENEMY_HERO, 2),
			new DeathrattleEffect(DeathrattleEffect.Type.DRAW_CARD, 1),
			new DeathrattleEffect(DeathrattleEffect.Type.SUMMON_SPIRIT, 1));
		UnitCard victim = new UnitCard("victim", "Victim", 1, 0, 1, Collections.emptyList(),
			Collections.emptySet(), deathrattles);
		BoardState board = BoardState.empty()
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-1", unit("attacker", 1, 3)))
			.readyAll(PlayerId.PLAYER_ONE).add(PlayerId.PLAYER_TWO, BoardUnit.deploy("unit-2", victim));
		PlayerState second = new PlayerState(20, 1, 1, 0, 1, Collections.emptyList(),
			Collections.singletonList(unit("drawn", 1, 1)), Collections.emptyList(), 0, true);
		MatchState state = state(board, defaultPlayer(20), second);

		MatchState next = attack(state, "unit-1", "unit-2").getState();

		assertEquals(18, next.getPlayer(PlayerId.PLAYER_ONE).getHeroHealth());
		assertEquals(1, next.getPlayer(PlayerId.PLAYER_TWO).getHand().size());
		assertEquals("deathrattle-spirit",
			next.getBoard().getUnits(PlayerId.PLAYER_TWO).get(0).getDefinition().getId());
	}

	@Test
	public void nexRequiresAllCommandersAndWinsWhenSummoned()
	{
		UnitCard nex = new UnitCard("asgarnia-nex", "Nex", 10, 10, 10, Collections.emptyList(),
			EnumSet.of(UnitKeyword.NEX_ASCENSION), Collections.emptyList());
		BoardState completeBoard = BoardState.empty()
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-1", unit("asgarnia-general-graardor", 1, 1)))
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-2", unit("asgarnia-commander-zilyana", 1, 1)))
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-3", unit("asgarnia-kreearra", 1, 1)))
			.add(PlayerId.PLAYER_ONE, BoardUnit.deploy("unit-4", unit("asgarnia-kril-tsutsaroth", 1, 1)));
		PlayerState withNex = new PlayerState(20, 10, 10, 0, 10, Collections.singletonList(nex),
			Collections.emptyList(), Collections.emptyList(), 0, true);

		MatchState incomplete = state(completeBoard.remove("unit-4"), withNex, defaultPlayer(20));
		assertEquals(RejectionReason.NEX_REQUIRES_COMMANDERS,
			engine.execute(incomplete, new PlayCardCommand(PlayerId.PLAYER_ONE, "asgarnia-nex"))
				.getRejectionReason().get());

		CommandResult result = engine.execute(state(completeBoard, withNex, defaultPlayer(20)),
			new PlayCardCommand(PlayerId.PLAYER_ONE, "asgarnia-nex"));
		assertTrue(result.isAccepted());
		assertEquals(MatchStatus.COMPLETE, result.getState().getStatus());
		assertEquals(PlayerId.PLAYER_ONE, result.getState().getWinner().get());
	}

	private CommandResult attack(MatchState state, String attacker, String target)
	{
		CommandResult result = engine.execute(state, new AttackCommand(PlayerId.PLAYER_ONE, attacker, target));
		assertTrue(result.getRejectionReason().orElse(null) + "", result.isAccepted());
		return result;
	}

	private MatchState accepted(MatchState state, Command command)
	{
		CommandResult result = engine.execute(state, command);
		assertTrue(result.getRejectionReason().orElse(null) + "", result.isAccepted());
		return result.getState();
	}

	private static MatchState state(UnitCard attacker, UnitCard target)
	{
		return state(attacker, target, 20, 20);
	}

	private static MatchState state(UnitCard attacker, UnitCard target, int firstHealth, int secondHealth)
	{
		BoardUnit deployed = BoardUnit.deploy("unit-1", attacker);
		BoardState board = BoardState.empty().add(PlayerId.PLAYER_ONE, deployed);
		if (!deployed.isReady()) board = board.readyAll(PlayerId.PLAYER_ONE);
		board = board.add(PlayerId.PLAYER_TWO, BoardUnit.deploy("unit-2", target));
		return state(board, defaultPlayer(firstHealth), defaultPlayer(secondHealth));
	}

	private static MatchState state(BoardState board, PlayerState first, PlayerState second)
	{
		Map<PlayerId, PlayerState> players = new EnumMap<>(PlayerId.class);
		players.put(PlayerId.PLAYER_ONE, first);
		players.put(PlayerId.PLAYER_TWO, second);
		return new MatchState(1, PlayerId.PLAYER_ONE, PlayerId.PLAYER_ONE, MatchStatus.ACTIVE,
			MatchPhase.PLAY, null, players, board, 10L);
	}

	private static PlayerState defaultPlayer(int health)
	{
		return new PlayerState(health, 1, 1, 0, 1, Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), 0, true);
	}

	private static UnitCard unit(String id, int attack, int health, UnitKeyword... keywords)
	{
		EnumSet<UnitKeyword> set = keywords.length == 0 ? EnumSet.noneOf(UnitKeyword.class)
			: EnumSet.copyOf(java.util.Arrays.asList(keywords));
		return new UnitCard(id, id, 1, attack, health, Collections.emptyList(), set, Collections.emptyList());
	}
}

package com.osrstcgbattles.integration;

import com.google.gson.Gson;
import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.catalog.BattleCardCatalogLoader;
import com.osrstcgbattles.catalog.CardAbility;
import com.osrstcgbattles.catalog.CardCategory;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.engine.Card;
import com.osrstcgbattles.engine.DeathrattleEffect;
import com.osrstcgbattles.engine.DeployEffect;
import com.osrstcgbattles.engine.SpecialCard;
import com.osrstcgbattles.engine.UnitCard;
import com.osrstcgbattles.engine.UnitKeyword;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CatalogCardContractTest
{
	@Test
	public void convertsAllCardsAndEveryDeclaredAbilityExactly()
	{
		BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();
		CatalogDeckFactory factory = new CatalogDeckFactory(catalog);
		Set<AbilityType> coverage = EnumSet.noneOf(AbilityType.class);
		assertEquals(400, catalog.getCards().size());

		for (BattleCard definition : catalog.getCards())
		{
			Card card = factory.create(new Deck("test", "Test",
				Collections.singletonList(new DeckEntry(definition.getId(), 1)))).get(0);
			String message = definition.getId();
			assertEquals(message, definition.getId(), card.getId());
			assertEquals(message, definition.getDisplayName(), card.getName());
			assertEquals(message, definition.getManaCost(), card.getManaCost());
			for (CardAbility ability : definition.getAbilities()) coverage.add(ability.getType());

			List<DeployEffect> deployEffects = deployEffects(definition);
			if (definition.getCategory() == CardCategory.SPECIAL)
			{
				assertTrue(message, card instanceof SpecialCard);
				assertEquals(message, deployEffects, ((SpecialCard) card).getDeployEffects());
				continue;
			}

			assertTrue(message, card instanceof UnitCard);
			UnitCard unit = (UnitCard) card;
			assertEquals(message, definition.getAttack(), unit.getBaseAttack());
			assertEquals(message, definition.getHealth(), unit.getBaseHealth());
			assertEquals(message, deployEffects, unit.getDeployEffects());
			assertEquals(message, keywords(definition), unit.getKeywords());
			assertEquals(message, deathrattles(definition), unit.getDeathrattles());
		}

		assertEquals(EnumSet.allOf(AbilityType.class), coverage);
	}

	private static List<DeployEffect> deployEffects(BattleCard card)
	{
		List<DeployEffect> effects = new ArrayList<>();
		for (CardAbility ability : card.getAbilities())
		{
			if (ability.getType() == AbilityType.DEPLOY_BOOST)
			{
				effects.add(new DeployEffect(DeployEffect.Type.BOOST,
					DeployEffect.Target.valueOf(ability.getStringParams().get("target")), amount(ability)));
			}
			else if (ability.getType() == AbilityType.DEPLOY_DAMAGE)
			{
				effects.add(new DeployEffect(DeployEffect.Type.DAMAGE,
					DeployEffect.Target.valueOf(ability.getStringParams().get("target")), amount(ability)));
			}
			else if (ability.getType() == AbilityType.GAIN_MANA)
			{
				effects.add(new DeployEffect(DeployEffect.Type.MANA, DeployEffect.Target.HERO, amount(ability)));
			}
		}
		return effects;
	}

	private static Set<UnitKeyword> keywords(BattleCard card)
	{
		Set<UnitKeyword> keywords = EnumSet.noneOf(UnitKeyword.class);
		for (CardAbility ability : card.getAbilities())
		{
			switch (ability.getType())
			{
				case SHIELD: keywords.add(UnitKeyword.SHIELD); break;
				case LIFESTEAL: keywords.add(UnitKeyword.LIFESTEAL); break;
				case POISONOUS: keywords.add(UnitKeyword.POISONOUS); break;
				case RUSH: keywords.add(UnitKeyword.RUSH); break;
				case TAUNT: keywords.add(UnitKeyword.TAUNT); break;
				case STEALTH: keywords.add(UnitKeyword.STEALTH); break;
				case NEX_ASCENSION: keywords.add(UnitKeyword.NEX_ASCENSION); break;
				default: break;
			}
		}
		return keywords;
	}

	private static List<DeathrattleEffect> deathrattles(BattleCard card)
	{
		List<DeathrattleEffect> effects = new ArrayList<>();
		for (CardAbility ability : card.getAbilities())
		{
			DeathrattleEffect.Type type;
			switch (ability.getType())
			{
				case DEATHRATTLE_DAMAGE_HERO: type = DeathrattleEffect.Type.DAMAGE_ENEMY_HERO; break;
				case DEATHRATTLE_DRAW: type = DeathrattleEffect.Type.DRAW_CARD; break;
				case DEATHRATTLE_SUMMON: type = DeathrattleEffect.Type.SUMMON_SPIRIT; break;
				default: continue;
			}
			effects.add(new DeathrattleEffect(type, amount(ability)));
		}
		return effects;
	}

	private static int amount(CardAbility ability)
	{
		return ability.getNumericParams().get("amount");
	}
}

package com.osrstcgbattles.integration;

import com.google.gson.Gson;
import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.catalog.BattleCardCatalogLoader;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.engine.UnitCard;
import com.osrstcgbattles.engine.UnitKeyword;
import java.io.StringReader;
import java.util.Collections;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class CatalogDeckFactoryTest
{
	@Test
	public void randomizesBeforeSelectingFirstCard()
	{
		CatalogDeckFactory factory = new CatalogDeckFactory(catalog("LEGENDARY", "LEGENDARY", "LEGENDARY"),
			new Random()
			{
				@Override
				public int nextInt(int bound)
				{
					return 0;
				}
			});

		Deck deck = factory.randomDeck(1);

		assertEquals("card-b", deck.getEntries().get(0).getCardId());
	}

	@Test
	public void enforcesCopyLimitsAndRejectsInsufficientCapacity()
	{
		CatalogDeckFactory factory = new CatalogDeckFactory(catalog("COMMON", "LEGENDARY"), new Random(1));
		Deck deck = factory.randomDeck(3);

		assertEquals(3, deck.getEntries().stream().mapToInt(entry -> entry.getCount()).sum());
		assertEquals(2, deck.getEntries().stream().filter(entry -> entry.getCardId().equals("card-a"))
			.findFirst().get().getCount());
		assertEquals(1, deck.getEntries().stream().filter(entry -> entry.getCardId().equals("card-b"))
			.findFirst().get().getCount());
		try
		{
			factory.randomDeck(4);
			fail("Expected insufficient capacity to fail");
		}
		catch (IllegalStateException error)
		{
			assertEquals("Catalog cannot fill a 4-card random deck", error.getMessage());
		}
	}

	@Test
	public void mapsCatalogKeywordsAndDeathrattlesIntoEngineCards()
	{
		BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();
		BattleCard shield = find(catalog, AbilityType.SHIELD);
		BattleCard deathrattle = find(catalog, AbilityType.DEATHRATTLE_SUMMON);

		UnitCard shieldCard = createOne(catalog, shield);
		UnitCard deathrattleCard = createOne(catalog, deathrattle);

		assertTrue(shieldCard.hasKeyword(UnitKeyword.SHIELD));
		assertEquals(1, deathrattleCard.getDeathrattles().size());
	}

	private static UnitCard createOne(BattleCardCatalog catalog, BattleCard card)
	{
		Deck deck = new Deck("one", "One", Collections.singletonList(new DeckEntry(card.getId(), 1)));
		return (UnitCard) new CatalogDeckFactory(catalog).create(deck).get(0);
	}

	private static BattleCard find(BattleCardCatalog catalog, AbilityType type)
	{
		return catalog.getCards().stream().filter(card -> card.getAbilities().stream()
			.anyMatch(ability -> ability.getType() == type)).findFirst().get();
	}

	private static BattleCardCatalog catalog(String... rarities)
	{
		StringBuilder cards = new StringBuilder();
		for (int i = 0; i < rarities.length; i++)
		{
			if (i > 0)
			{
				cards.append(',');
			}
			char suffix = (char) ('a' + i);
			cards.append("{\"id\":\"card-").append(suffix).append("\",\"azCardName\":\"Card ")
				.append(suffix).append("\",\"displayName\":\"Card ").append(suffix)
				.append("\",\"category\":\"UNIT\",\"faction\":\"NEUTRAL\",\"rarity\":\"")
				.append(rarities[i]).append("\",\"manaCost\":1,\"attack\":1,\"health\":1,")
				.append("\"tags\":[],\"rulesText\":\"None\",\"abilities\":[{\"type\":\"VANILLA\"}]}");
		}
		return new BattleCardCatalogLoader(new Gson()).load(new StringReader(
			"{\"catalogVersion\":2,\"rulesetVersion\":8,\"cards\":[" + cards + "]}"));
	}
}

package com.osrstcgbattles.integration;

import com.google.gson.Gson;
import com.osrstcgbattles.catalog.AbilityType;
import com.osrstcgbattles.catalog.BattleCard;
import com.osrstcgbattles.catalog.BattleCardCatalog;
import com.osrstcgbattles.catalog.BattleCardCatalogLoader;
import com.osrstcgbattles.collection.OwnedCardCollectionStatus;
import com.osrstcgbattles.deck.Deck;
import com.osrstcgbattles.deck.DeckEntry;
import com.osrstcgbattles.deck.DeckValidator;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StarterDeckFactoryTest
{
	private final BattleCardCatalog catalog = new BattleCardCatalogLoader(new Gson()).loadDefault();
	private final StarterDeckFactory factory = new StarterDeckFactory(catalog);

	@Test
	public void createsThreeValidThirtyCardDecks()
	{
		List<Deck> starters = factory.createStarterDecks();

		assertEquals(3, starters.size());
		for (Deck deck : starters)
		{
			assertEquals(30, deck.getEntries().stream().mapToInt(DeckEntry::getCount).sum());
			assertTrue(new DeckValidator().validate(deck, new CatalogCardLookup(catalog), Collections.emptySet(),
				OwnedCardCollectionStatus.UNKNOWN).isValid());
		}
	}

	@Test
	public void deckThemesContainTheirCoreMechanics()
	{
		List<Deck> starters = factory.createStarterDecks();

		assertTrue(count(starters.get(0), AbilityType.DEATHRATTLE_DAMAGE_HERO,
			AbilityType.DEATHRATTLE_DRAW, AbilityType.DEATHRATTLE_SUMMON) >= 10);
		assertTrue(count(starters.get(1), AbilityType.RUSH) >= 10);
		assertTrue(count(starters.get(2), AbilityType.SHIELD, AbilityType.LIFESTEAL, AbilityType.TAUNT) >= 20);
	}

	@Test
	public void ownershipExemptionRequiresTheExactBuiltInDefinition()
	{
		Deck starter = factory.createStarterDecks().get(0);

		assertTrue(factory.isUnmodifiedStarter(starter));
		assertFalse(factory.isUnmodifiedStarter(new Deck(starter.getId(), "Edited", starter.getEntries())));
	}

	@Test
	public void exposesStableProtectedStarterDefinitions()
	{
		List<Deck> starters = factory.createStarterDecks();

		assertTrue(starters == factory.createStarterDecks());
		assertTrue(factory.isStarterId(StarterDeckFactory.DEATHRATTLE_ID));
		assertEquals(starters.get(0), factory.getStarter(StarterDeckFactory.DEATHRATTLE_ID));
		assertFalse(factory.isStarterId("custom-deck"));
	}

	private int count(Deck deck, AbilityType... types)
	{
		int count = 0;
		for (DeckEntry entry : deck.getEntries())
		{
			BattleCard card = catalog.findById(entry.getCardId()).get();
			for (AbilityType type : types)
			{
				if (card.getAbilities().stream().anyMatch(ability -> ability.getType() == type))
				{
					count += entry.getCount();
					break;
				}
			}
		}
		return count;
	}
}

package com.osrstcgbattles.match;

import com.google.gson.Gson;
import com.osrstcgbattles.engine.Card;
import com.osrstcgbattles.engine.DuelscapeEngine;
import com.osrstcgbattles.engine.MatchState;
import com.osrstcgbattles.engine.PlayerId;
import com.osrstcgbattles.engine.UnitCard;
import java.util.ArrayList;
